/* 平成28年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h28.committeeSessions.push(...[{"id":"h28-20160927-7","meetingId":"h28-cm09","date":"2016年9月27日","dateIso":"2016-09-27","committee":"厚生委員会","time":"午前１０時００分～午後 ２時４６分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を52件整理しています。","topics":[{"id":"topic-01","title":"第８８号議案 品川区立地域密着型多機能ホームおよび品川区立認知症高齢者グループホーム条例の一部を改正する条例","agenda":"第８８号議案 品川区立地域密着型多機能ホームおよび品川区立認知症高齢者グループホーム条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２１２％ということで、それがなぜ、３００％までいかない容積率になったのか教えてほしいと求めました。改めて総事業費と、補助金が総事業費に対してどれだけ出ているのかについてもお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"これは、あくまでも、公募のときはこれぐらいというところで見込んだものです。今申し上げましたように、特定財源としては１億６,０００万円の補助が入っているところです。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"理念はすごいすばらしく、本当に利用者主体の理念でやられていて、お話を伺うたびに、すばらしいと思うところなのです。働く側にとってはかなり大変厳しい状況があるというのもお聞きしているのですけれども、その中で、離職率もわかったら教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"近隣の町会長にご説明に上がったときにも、大崎第一地域センターまで行かないと、そういう集まれる場所があると助かるというお声をいただきました。利用者および近隣の皆様方への非常時の食料等の配付ということで考えておりまして、１０人分程度は備蓄していきたいと考えていま…","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"屋上に太陽光パネルを設置して、吸引が必要だったり、電源が必要な高齢者は出てくるのではないかと思うのです。多分、こういうグループホームについても太陽光パネルを設置することにしたほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"太陽光パネルの設置ができるか、できないかといったところで検討はさせていただいたのですが、太陽光パネルをつけてもというところがありました。それなりの規模の太陽光パネルが設置できると思うのですが、今回、太陽光パネルの設置を見送ったところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"新生寿会の考え方として、いろいろと視察したときにも、全室にトイレがついていると確認させてください。そういった考えのもと、今回、備品の設置がされているのかあわせて説明を求めました。","respondent":"大串福祉計画課長","answer":"居室にトイレが設置されているかというところです。初度備品については区が負担する形をとっておりますので、その一定の予算の中で、法人でしかるべきものを購入していただく形になろうかと思います。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後に、本当にこういう施設は求められる必要な施設なのですけれども、利用料が幾らぐらいになるのかをお聞かせほしいと求めました。介護保険料で第３段階までの方まで、２万４,０００円の補助制度ができましたので、幾らぐらいになるのかを最後にお聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"利用料としては、今現在、想定しているのが１７万円ほどです。ただ、委員、ご紹介いただいたような形での助成等が入ってまいりますので、必ずしも１７万円相当ではないと考えているところです。","id":"exchange-005"},{"speaker":"浅野委員","kind":"質問","question":"何点かお伺いしたいのですが、ここは１つの避難ルートにもなるのかというのと、そこら辺かと思います。外観のところで、そちらのほうにも出られるようになっていると思うのですが、有事の際の避難ルートに関して教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"２階、３階部分にバルコニーがしかれておりますので、そちらのバルコニーを通りながら外階段に抜けていくといったところです。避難としては、そういった２方向の避難を確保しながら、今現在、運用を進めているところです。","id":"exchange-006"},{"speaker":"浅野委員","kind":"質問","question":"１階の緑化だけではなく、屋上で楽しめるイベントなんかも、芝生がもしあるのであればできると思うのです。２点について説明を求めました。","respondent":"大串福祉計画課長","answer":"というのも、やはり近隣とのプライバシー関係がありまして、入所者の方が屋上に出て何かというのはなかなか難しいところです。こちらの屋上につきましては、緑化はしておりますけれども、今のところは、何かイベントという想定はしていないところです。","id":"exchange-007"},{"speaker":"浅野委員","kind":"質問","question":"３０センチメートル、５０センチメートルぐらいだと思います。１人で屋上に上がって、そういうことを考えながら設計をされていると思いますけれども、その安全対策について説明を求めました。","respondent":"大串福祉計画課長","answer":"通常は、上階、塔屋の部分には行かない形になっております。あるいは、上がるという形になりますので、入所者の方がこのエレベーターに乗って塔屋の部分まで行くということは想定していないところです。","id":"exchange-008"},{"speaker":"浅野委員","kind":"質問","question":"気になったところだけを質問させていただきましたけれども、このグループホームが地域にとりましても、また区民にとりましても、大切な施設でありますので、これからも。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"いかがでしょうか。そうはいっても、設計とか、いろいろ制約もあるでしょうから、検討していただきたいと要望いたします。","respondent":"大串福祉計画課長","answer":"５月以降、開設をして、いろいろな形で地域の中に溶け込んでいくという中で、いろいろな、お声が出てこようかと思います。十分、指定管理者候補者に対応していただけると考えていますので、地域の中で高齢者を見守る仕組みをつくっていければと考えております。","id":"exchange-010"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"２４０名までいったということで、どのように残りの整備をしていくお考えがあるのか、そこら辺もお伺いします。こういった施設を求めている方というのは、利用料はもっと下げていただくような方向で検討していただきたいと思うのですけれども、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"先ほどもご質問にお答えしましたように、今後とも、こういった形での整備を進めていきたいと考えております。法人の運営も十分勘案しながら、利用料については検討していただいているところですので、こちらの金額となろうかと考えています。","id":"exchange-011"}]},{"id":"topic-02","title":"第８９号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","agenda":"第８９号議案 品川区立特別養護老人ホーム条例の一部を改正する条例","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"特養ホームのところは、リビングとダイニングを別にしつらえると書いてあるのですけれども、これが愛生福祉会の特徴でしょうか。３番のところでは、地域へ利用開放ということなのですけれども、広さと活用がどうなるのか。","respondent":"大串福祉計画課長","answer":"平成２６年度に実施のものです。特養の運営に支障がない範囲で、当然、こちらのスペースについては有効に活用していただければと考えているところです。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"インシュリン注射なんかは在宅で普通にやっているわけですから、その辺がどうなっていくのかもお聞かせほしいと求めました。その設計のところも教えていただけたらと思います。","respondent":"大串福祉計画課長","answer":"こちらも精力的に人材確保には取り組んでいただいているところで、今のところ、法人側としては１３０人ほどの採用を考えていらっしゃるところです。そこからの異動も含めて、配置については十分対応できるということで、法人から回答をいただいているところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"前のときは太陽光パネルが１０キロワット分ついているということであったのですけれども、その予定どおりつくのかということが１つです。１.５倍以上ぐらいになっているというのは、どういう理由で、本体工事費が増えたのかについてもお聞かせいただけたらと思いますとの意見を述べました。","respondent":"大串福祉計画課長","answer":"ただ、いずれにせよ、４５億円の大きな要因としては、やはり建設工事費単価の値上がり等、こういったものが出てきているというのが事実です。こういった工事に携わる職人の方の人材不足といったところで…","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"２７億９,８７４万７,０００円で、擁壁工事が８,３５４万７,０００円ということで、それではできなかったということですね。これはショートステイもすごい数が多いですから、通常、それぐらいかかると捉えていいのかということを最後に説明を求めました。","respondent":"大串福祉計画課長","answer":"そういったところで、当初考えていた金額よりも高くなったというのは事実あります。とはいえ、やはり１００人規模の特養をつくっていくとなると、どうしてもこれぐらいの経費が様々かかってこようかというのは正直なところです。","id":"exchange-015"},{"speaker":"渡辺委員","kind":"質問","question":"これだけの規模のときに、今、伺っている中で、今後、展開するにも、他地域でもそうですし、すごくモデルになるような気がしています。時間はどうなのだろうとか、期待もすごくある中で、このケースではこんなイメージというのをまず教えてほしいと求めました。","respondent":"大串福祉計画課長","answer":"法人と話し合っている中では、週４日の開設、それを一般開放していこうというところで話し合いを進めているところです。今現在、配置する医師の方とも交渉しながら進めているところです。","id":"exchange-016"},{"speaker":"渡辺委員","kind":"意見","question":"相談的なことも、法人として、地域貢献の色彩としてあるべきかと。そういったことは法人とのやりとりでいけるものなのかを最後に聞いて終わりますとの意見を述べました。","respondent":"大串福祉計画課長","answer":"そうしたことを踏まえまして、正直申し上げて、この地に特養をつくるにあたっては、地域との調整は非常に難しいところがあったのも事実です。親しまれるかといったところは、また今後、特養を運営する法人とも一緒に考えながらやっていきたいと考えています。","id":"exchange-017"},{"speaker":"浅野委員","kind":"質問","question":"これだけの施設ですから、ここをさらに右に行くと、これは通行どめで通れない。決めておいていただかないと、いざというときに逃げ惑う危険性もあるという気がしてならないのですが、いかがか尋ねました。","respondent":"大串福祉計画課長","answer":"ショートステイ等、あるいは送迎が発生した場合には、気をつけて運用はしていくというところで考えているところです。基本はここにとどまっていただくという形をとるというのが、今のところ、考えているところです。","id":"exchange-018"},{"speaker":"浅野委員","kind":"質問","question":"それしか手はないと思いますけれども、そういう意味では、ご家族の方にも少しメリットがあるようなことが出せればいいと思います。そういう見解もあるということを捉え、ちょっと一声かけてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"その経過といいますか、どんな感じで話し合いを続けてきたのか、その経過などを教えていただきたいというのが１点です。そういった地域というのは他にあるのかどうかなどもあわせて、考え方をお伺いします。","respondent":"大串福祉計画課長","answer":"その運営事業者による事業計画の説明会、擁壁の改修工事の説明会、本体工事の説明会。生活圏域にバランスよく施設等を整備していきたいと考えているところでございまして、この特養を旧みやこ荘の跡地に整備すると考えたところです。","id":"exchange-020"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"それとあと、この空白地域ということなのですが、まだあると思うのです。バランスよくこういう施設をつくっていくというお考えなのかどうか、その辺をもう一度、お聞かせほしいと求めました。","respondent":"大串福祉計画課長","answer":"先ほども申し上げましたように、１３の生活圏域にということで考えているところです。グループホーム、あるいはそれ以外の施設といったものも、バランスを考えながら整備を進めていければと考えています。","id":"exchange-021"}]},{"id":"topic-03","title":"第９３号議案 指定管理者の指定","agenda":"第９３号議案 指定管理者の指定","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"教えていただきたいのですけれども、今年の４月から八潮と戸越分室ということで、福栄会が今はされているわけです。そこのところをまず教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"現在は、戸越ルームは区立直営ということになっておりまして、事業の委託ということで福栄会にお願いをしています。平成２９年度につきましては、こちらの指定の議決をいただいた暁には、共同事業体フリーユニティーの中のゆうゆうに事業委託をする運びになります。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"北海道の指定管理者だと思うのですけれども、初めて東京に来て運営を行うにあたり職員をどう確保していくのかお聞かせほしいと求めました。どういう資格の人がどれぐらいの人数の体制になるのかということを、戸越と八潮、それぞれ教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"特に今、仮移転中ということもありますので、同じ体制で運営をしていこうと考えております。それから、何人かは、核となる職員をゆうゆうあるいはグローから持ってくるという形になろうかと考えております。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"引き継ぎをどうしていくのかと思っていたので、また、運営のやり方というのが新鮮な形になっていくという思いがするのです。福栄会とゆうゆうのそもそもの待遇が違うと、あわせて、どんな職種の方が何人くらいいるのかという職員の体制も教えていただけたらと思います。","respondent":"中山障害者福祉課長","answer":"正規職員１人、非常勤職員８名、心理職です。それから、非常勤職員ということで９人の職員がおりますが、心理職あるいは心理の見込みという職員構成になっております。","id":"exchange-024"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、そこを利用されている方にとっても混乱なくというところで、ぜひやってほしいと求めました。資料をつけていただいたのだと思うのですが、今回の場合は、どこに当たると考えられるのかをお聞かせいただけたらと思います。","respondent":"大串福祉計画課長","answer":"(1)のところですが、指定管理者候補者の選定にあたっては、公募プロポーザル方式というのが前提になっています。２番のところですが、4)のところと5)のところを採用させていただいて、このような形で選定をさせていただいた流れになっているものです。","id":"exchange-025"},{"speaker":"浅野委員","kind":"質問・要望","question":"この中で、構成事業者で社会福祉法人グローが代表者となって、４事業者ということでお話を伺いました。例えば代表者のグローの責任というのでしょうか、どのような体制で、この４社が一丸となってやっていくのかということについて教えていただきたい。","respondent":"中山障害者福祉課長","answer":"そのほか、事業者間の連絡ということでは、やはり顔を合わせたものが最低でも月１回は行われています。全員の職員が移行するわけではありませんので、今、調整をとっているところです。","id":"exchange-026"},{"speaker":"浅野委員","kind":"質問","question":"もう一点ですけれども、Ａ３の福祉部公の施設の指定管理者候補者選考基準というのをいただきました。基本的には、全て満たさないとだめということだと思うのですけれども、この点について説明を求めました。","respondent":"大串福祉計画課長","answer":"例えば特養であれば入所系サービス施設、それぞれその施設の持っている特性に応じて、選考基準を当てはめて考えているといったところです。一番左側にあります通所系サービス施設の基準の１から４、それに合わせた形で選考させていただいて…","id":"exchange-027"},{"speaker":"安藤副委員長","kind":"質問","question":"ゆうゆうについてお伺いしたいのですけれども、建て替え後の総合支援施設においては、ゆうゆうはどの部門を担当する予定なのでしょうか。この間、いろいろやりとりをしている中で、その辺をどのようにお感じになっているのかお伺いします。","respondent":"中山障害者福祉課長","answer":"それから、訪問系のサービスというところで、ホームヘルプを担う予定となっております。２年後には新施設ができて、そこで働くということに対する期待ですとか、東京でぜひ働きたいという北海道の職員もいると聞いております。","id":"exchange-028"},{"speaker":"安藤副委員長","kind":"質問","question":"支援実績を評価されているわけですけれども、具体的にはどのような実績を評価しているのか、もう少しお伺いしたいと思います。法人の人材育成や待遇面についての考えなどについて、どのように把握して、どこを評価しておられるのか、説明を求めました。","respondent":"中山障害者福祉課長","answer":"この法人の評価というところになりますが、特に、お子さんの支援だけではなく、親支援がすごく重要な時期かと考えています。今やっていらっしゃるのが北海道になりますので、一概に東京と比較して、そこの比較がいいからということで評価をしたということはありません。","id":"exchange-029"},{"speaker":"安藤副委員長","kind":"質問","question":"待遇面も含めたことになると思いますけれども、人材育成ですとか待遇面というのは、やはりすごく大事になってくるとは思うのです。評価しているのかということをお伺いしたので、そこに関する、法人のどのようなところを評価しているのかというのをお伺いしたかったので。","respondent":"中山障害者福祉課長","answer":"このほか、全国地域生活支援ネットワークという大きな全国組織のネットワークにも入っておりまして、働いていきたいという職場ではあるかと思います。職員の声にまずは耳を傾け、一緒に考えて、新しいものをつくっていくといったような法人の姿勢があろうかと考えています。","id":"exchange-030"}]},{"id":"topic-04","title":"第８５号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","agenda":"第８５号議案 平成２８年度品川区一般会計補正予算（歳出 厚生委員会所管分）","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それから、そういう形であれば、警察との連携、警察の体制がどうなるのかも教えてください。それから、ショートステイの部分があると思うのですけれども、そういうところに対してはどう考えられているのかについても説明を求めました。","respondent":"大串福祉計画課長、永尾高齢者福祉課長","answer":"１１０番通報をして、もう異常事態だということが認識されて、スピーディーな対応ができるというのが１つです。それから、基本的に、ご案内のように入所系の施設につける予定でおります。 対応し切れないのではないかというご意見もあるということで、調整する中では、ここに挙げた施設で始めているところです。それをやってみて、その結果によって、また検討するのではないかと思っているところです。","id":"exchange-031"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"こういう対応をされたということでいいのかということを、１点、確認させていただきたい。そしてまた、今後、どういう取組みをしていこうとしているのかがありましたら、教えてほしいと求めました。","respondent":"中山障害者福祉課長","answer":"区として、それを受けて、どういった対応を行ったかということなのですが、まず安全管理の状況の確認は行いました。そういったところでは、やはり法人の対応がいち早かったこともあろうかと考えています。","id":"exchange-032"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"障害者の理解を深めるような取組みでは、ぜひ、今後とも進めていっていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"浅野委員","kind":"質問","question":"何らかの変化というのでしょうか、１点、教えてほしいと求めました。この点が私は理解できなかったのですけれども、もくろみというのでしょうか、そういう考え方があれば、教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"今、出ているところですので、各施設の中で検討が始まっているという状況になっています。それで、このボタンについては、１カ所と言われておりますので、場所については、また施設と協議をしながら決めていきたいと考えています。","id":"exchange-034"},{"speaker":"浅野委員","kind":"意見","question":"やはりボタンは１カ所なのかというのは思うところでありまして、２カ所も３カ所も、なかなか難しいと思います。私どもとしてもあるということを肝に銘じていきたいと考えていますので、ぜひともとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"松永委員","kind":"質問・要望","question":"例えば、警察であれば、大体、事故ですか、事件ですかという話でされると思うのですけれども、どういった内容なのか教えてほしいと求めました。要するに、押されては困るという形で答えられていたので、警察が考えている異常事態はどういうところなのかということを聞きたいと思います。","respondent":"永尾高齢者福祉課長","answer":"先ほど説明が不十分だったと思うのですが、施設側が危険を感じたら押すとなっておりますので、そこは警察と一致しています。特定施設等、かなりの数になっていきますので、それに対して警察側が対応し切れるかどうかというところは課題と思っているところです。","id":"exchange-036"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"上限２泊３日までということなのですが、出産というのは、何泊何日で退院するのが通常なのでしょうか。その後、２泊３日だと２万円になるのかと思うのですけれども、そのうちの何割が自己負担でこれだけの額になるのかを教えてほしいと求めました。","respondent":"太田品川保健センター所長","answer":"そのまま継続滞在の方のみということで、外に一旦、帰られた方を預かることはできないということです。自己負担の金額としては６,０００円から１万８,０００円の中で、２万円ということになりますので、金額としてはそれほど高くないと考えております。","id":"exchange-037"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"５泊６日が、結局、７泊８日いられる形になると思うのですけれども、そういった所が、事業としては求められていると思います。そこのところの確認だけ、お願いします。","respondent":"太田品川保健センター所長","answer":"国が２分の１、都は区が支払う分の２分の１を５年間、出産・子育て応援事業として支払うということです。５年たてば、国が２分の１、区が２分の１ということになります。","id":"exchange-038"},{"speaker":"安藤副委員長","kind":"質問","question":"期限が決まっていることなのか、これはいつまで考えているのかをお伺いしたいのと、他自治体の実施状況というのはどうなっているのかをお伺いします。でも、どうやって里帰りをせずというのを判断するのか、その基準がもしありましたら、お伺いします。","respondent":"太田品川保健センター所長","answer":"モデル実施で、本年度は４カ月の実施になりまして、来年度、１年間の本格実施の間に、この事業の検証は進めてまいりたいと考えています。次に、実施について予定をされている自治体もありまして、今のところ８区は産後ケア宿泊型あるいは日帰り型等を実施している状況です。","id":"exchange-039"},{"speaker":"渡辺委員","kind":"質問・要望","question":"そういう中で、スケジュール感を伺いたいと思います。これは品川区だけで、独自ということも言いますが、そうでもない要素がすごく多いと思うので、スケジュール感を伺えればと思います。","respondent":"川島健康課長","answer":"受動喫煙防止対策強化検討チームの立ち上げが今年の１月に行われておりまして、こちらでは国と東京都が検討を始めたということです。これが１５年ぶりにあったというところで、屋内１００％、何らかの動きが近々あるのではないかと推測するところが普通と私どもは考えてあります。","id":"exchange-040"},{"speaker":"渡辺委員","kind":"意見","question":"何が言いたいかというと、そういうお声が所管の中にも入っているかどうか。区の考え方はともかく、そういった地域の声、情報は入っているのかだけ説明を求めました。","respondent":"川島健康課長","answer":"煙がくさいですとか、企業の喫煙スペースが外にあって煙いとか、そういったお話が主に入ってきているところです。","id":"exchange-041"},{"speaker":"渡辺委員","kind":"意見","question":"そういう一定の目安があると、私たちも、こういうものを判断しやすい。逆に、それまでは厳しいという思いで聞かせていただきますとの意見を述べました。","respondent":"川島健康課長","answer":"区商連の取組みにつきましては、１０月末に全部の区商連の取組みの集約が終わるです。先ほどお話ししました、大井、旧東海道、荏原町は、もう先行して独自の取組みを進めていると聞いてあります。","id":"exchange-042"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"この喫煙をする方をどう少なくしていくかというところは、そこのところを１つ、お聞かせほしいと求めました。このしながわ健康プラン２１の中に、これがどんなものなのかということもお聞かせいただきたいのと、いかがか尋ねました。","respondent":"川島健康課長","answer":"平成１５年に策定したものですので、少しまた直さなければならないところもあるのかもしれないので、内部でまだまだ検討したいところがあります。区がどういう方針かというのをしっかり打ち出すというのは大事だと思いますので、もう少し、少し研究していきたいと考えております。","id":"exchange-043"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"喫煙者がいなくなれば全くこれは解決できてしまうわけですから、そういう取組みにぜひつなげていくことがすごく必要なのではないかと思います。私たち共産党としては、条例化をすべきではないかと思っているところです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"松永委員","kind":"意見","question":"お店の方の思いとか考えがあるので、日本は日本の独自の方法で、今回のオリンピック・パラリンピックに向けていくべきだと私たちは思っております。今後、国と都の動向を見ながら、慎重に進めていくべきだと考えていますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"浅野委員","kind":"質問・要望","question":"今回は区に求められているということもありまして、東京都がこのような姿勢でいるということ自体が、やはり遺憾と私は思います。そういう意味で、判断をしていかなければならないと感じております。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"渡辺委員","kind":"意見","question":"国や東京都の見解のペース、スケジュール感がそんなに遠いものではないと思いますので、今日時点で、当議会として判断するのは早急かと。後で正式な判断は言いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"そこは１点、お考えをお伺いしたいと思います。そちらのほうでの区としての考え方とか取組みはどうなっていらっしゃるのか、そちらもあわせてお伺いしたほうが、質問します。","respondent":"川島健康課長、濱田生活安全担当課長","answer":"受動喫煙防止対策基本方針につきましては、平成１５年ということですので、内容をまず見直してからということになると思います。先ほどの国のたばこ白書の中では… 予算を５００万円つけておりまして、この５００万円の使い道は、路面シートの張りかえと横断幕の張りかえです。これが屋外のポイ捨ての取組みです。","id":"exchange-048"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"それ以外は、区内全面禁煙なのだけれども、歩いているたばこはだめといった仕切りがあったではないですか。どれだけ効果を上げているのかというのを今の段階で教えていただきたいのです。","respondent":"濱田生活安全担当課長","answer":"９月末現在、９件の取り締まりを行い、昨年と同じペースです。前年度も１２件ずつで、今、頑張っているところです。","id":"exchange-049"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"条例化をすべきだという姿勢が私たちの態度ということは明確にさせていただいた上で、ただ、とてもいい機会になったと思うのです。そういうところで、条例化をすべきだという態度を示しながら、皆様の中で継続ということであれば、継続でも了としますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"先ほど言ったとおりに、条例化すべきだと思いますけれども、継続ということでも結構ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"}]},{"id":"topic-05","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、厚生委員会にかかわる項目","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一般質問の１日目の自民党の鈴木真澄議員の質問なのですけれども、道路付けが悪くて、なかなか難しいという話だったと聞いているのです。区がつかんでいること、それから、どんな状況に今後なっていくのかをお聞かせいただきたいというのが１点です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3456#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":59932,"voices":157}},{"id":"h28-20160927-8","meetingId":"h28-cm09","date":"2016年9月27日","dateIso":"2016-09-27","committee":"建設委員会","time":"午前１０時００分～午後 ０時０１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を36件整理しています。","topics":[{"id":"topic-01","title":"第９０号議案、品川区立区民住宅条例の一部を改正する条例","agenda":"第９０号議案、品川区立区民住宅条例の一部を改正する条例","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"区民住宅は入居率もそれほど高くないということもよく聞くのですけれども、この２カ所の入居率を伺いたいと思います。出ていかなければいけなかったり、不利益になるような人がいるかどうか、伺いたいと思います。","respondent":"今井住宅課長","answer":"それ以降は３％ずつ家賃が上がってまいりまして、区の条例で決めました使用料にすり寄っていく、すりついていくという形になります。７月末につきましては、１戸のみほかの場所に転出したとは聞いておりますが、そのようにオーナーが対応されていると認識しております。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この区民住宅は、借上型と建設型とあると思うのですけれども、今現在、建設型と借上型が区内にどれだけあるのかお伺いします。","respondent":"今井住宅課長","answer":"建設型ですけれども、こちらは８団地７５８戸という形になっております。借上型については現在、６団地１３６戸のところから今このサンライズ品川が減りましたので、５団地１１９戸という形になっております。","id":"exchange-002"},{"speaker":"石田（ち）委員","kind":"質問","question":"借上型のほうは、６団地から４団地になってくるのではないかと思うのですが、そこの戸数もまた伺えたらと思います。オーナーとの契約というところで、建設型だったら廃止されるということはないと考えてよいのか尋ねました。","respondent":"今井住宅課長","answer":"借上型につきましても、７月末の時点で入居率が６割という形で、やはりこの借上型区民住宅というのは一定の役割を終えたのかと考えています。空き室率等の今後の変遷を見ながら、更なる有効活用への検討が可能かどうか、今年度引き続き検討していきたいと考えています。","id":"exchange-003"},{"speaker":"石田（ち）委員","kind":"質問","question":"建設型が入居率９０％ある中で、借上型が６割程度というこの差は何なのかをちょっと伺いたいのと、そちらを選ばれる方もいるのかとも思うのです。やはり区が公的に建設している、または持っている住宅として、そこら辺のお考えはいかがか尋ねました。","respondent":"今井住宅課長","answer":"将来的にまたオーナーチェンジが行われ、かつ２０年経過するその借上型区民住宅にはなかなか入居が進まないというのが現状だと考えております。やはりほかの民間住宅が決まったなどという辞退届も出ておりますので、今後そのような動向も踏まえまして検討してまいります。","id":"exchange-004"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりどの方も安心して暮らしたいというのが、一番の思いだと思うのです。ですので、区が公の住宅をさらに増やしていくという方向転換をしていただきたいと要望しておきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"今まではどういう取り決めになっていたのでしょうか。ましてや入っていないところもあるものですから、区のほうはどれだけかぶってきたのでしょうか、説明を求めました。","respondent":"今井住宅課長","answer":"これまでの対応ですけれども、初めに借上型の区民住宅につきましては、やはり入居率は地域によります。もちろん個人負担の部分、使用者の方の負担の部分を除きまして、２分の１ずつ区とオーナーとで負担しています。","id":"exchange-006"},{"speaker":"西本委員","kind":"質問","question":"入居年数が短い人はその分ギャップが出てくるのだと思うのですけれども、そういう方はいらっしゃらないのですか。でも来年、もう１ヶ月後に退居される方に対してはありませんとか、そういうはっきりしたことを提示されているのかどうか伺います。","respondent":"今井住宅課長","answer":"ですので、やはり使用料というものを目安にご検討いただくということが一番だと考えています。途中、空き室についても原状回復という形でもしておりますので、そういう点も含めましてオーナーにはご説明しています。","id":"exchange-007"},{"speaker":"西本委員","kind":"質問・要望","question":"一番はオーナーたちがそれで納得しているかということを最後に聞きたいと思うのです。お互いが納得する形で移行に移していただきたいという思いがあるので、スムーズに移行となってきているのかだけ説明を求めました。","respondent":"今井住宅課長","answer":"こちらのほうのオーナーとは定例的に打ち合わせの機会を持ちまして、今後の方針について確認しております。大分返却といいますか、あとこれで４戸になりますが、今までの事例やほかのオーナーたちとの懇談も含めてきちんと対応していきたいと考えております。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"質問","question":"１２月以降の、今お話のあった借上型の４団地のほうの、借上げ期間の満了日だけ説明を求めました。","respondent":"今井住宅課長","answer":"アイルサイドテラスにつきましては平成３０年８月。ロビン成田につきましては平成３２年の２月ということで、平成３１年度をもちまして、借上型区民住宅については満了を迎えるという状況です。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"借上型というスキームに対する総括というか、どうだったのかというところで、ご見解をお伺いしたいと思います。","respondent":"今井住宅課長","answer":"民間のオーナーのほうに建物を建てていただいて、それを２０年間借り上げるというスキームでやってまいりました。やはりその時点では、流入する人口を含めて定住化という大きな方針がございましたので、その方針には合致した施策だったと考えています。","id":"exchange-010"},{"speaker":"塚本委員","kind":"質問","question":"こういった借上型のやり方の経験なども踏まえて、今後はどのような方向性、見解みたいなものがあるのかを最後にちょっとお伺いしたいと思います。","respondent":"今井住宅課長","answer":"そういった中では、区全体の住宅施策の中の状況を一定見直してみる必要があると考えております。そこにも配慮しつつ検討を進めていきたいと考えていますけれども、慎重に検討していきたいと考えています。","id":"exchange-011"},{"speaker":"石田（ち）委員","kind":"質問","question":"私たちも先日の一般質問で、移動支援をということで質問させていただきましたけれども、言い当てているなと私はすごく思うのです。区は、こうした陳情の中にあります「交通の便が悪くいつも苦労しています」というこの声をどう考えているのか尋ねました。","respondent":"中村都市計画課長","answer":"バス勢圏、この５００ｍの駅勢圏の中での考慮というのは、このコミュニティバスとはまた別に検討する必要があるのかなと考えております。必ずしもコミュニティバスでの解決が唯一の方法ではないと認識をしております。","id":"exchange-012"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"こうした高齢者の皆さんは、自転車にも乗れなくなってしまった、こういう方々が求めているわけですね。それができなくなってしまった人にとって、乗換えというのがどれだけ不便か、アクセスが悪いことを問題と思わないのか、伺いたいと思います。","respondent":"中村都市計画課長","answer":"あるいは駅とバスを１回ずつ併用する、この乗換えの１回から２回、これはもう致し方ないかなと思います。と申しますのも、鉄道もダイレクトに目的地まで網の目のように網羅されているわけではございませんので、一定の乗換えは必ず生じると考えています。","id":"exchange-013"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"やはりこの品川区内でコミュニティバスを走らせてほしいと求める請願は、この間、２０１４年あたりでは１１本もの請願が出されてきていました。こうした皆さんの社会参加を区はどう考えているのかを伺いたいと思います。","respondent":"中村都市計画課長","answer":"これは区民の方、小さいお子様から高齢者まで様々な形で社会に参加していただくことはもう非常に重要ですし、またそうしていただきたいと考えております。","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"品川区が進めている、高齢者に元気な生活をこれからも送ってほしいといういろいろな施策を進めているのにも、矛盾してくると思うのです。ここをちょっと詳しくもう一度ご説明いただきたいのですけれども、そういった将来的なところでの考えをお聞かせほしいと求めました。","respondent":"中村都市計画課長","answer":"この資料でもお示しいたしました徒歩圏に駅やバス停があるという現在の状況においては、コミュニティバスについて検討する予定はございません。将来、そういった種々の路線バスも今ぎりぎりの状態で経営をしておりますので、状況によってということになると思います。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"そして、八潮においては高齢化率３２％と、陳情第１０号の中にもあります。ですので、住民にとって不便だということは問題ではないか、そこを改めてもう一回伺いたいと思います。","respondent":"中村都市計画課長","answer":"これはそれぞれ個人の考え方によると思います。それは便利と言われますが、大体１回から２回、これはもう公共交通の中では一般的な考えの中では許容範囲だと認識をしております。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"多くの皆さんが、そうは言っても１本で行ければ便利だと思うのです。病気になったから自転車に乗れなくなってしまったという皆さんの苦労はわかりますよね、そこをちょっとお伺いします。","respondent":"中村都市計画課長","answer":"これからは一般の道路も歩きやすくさらに進めていくとか、それからあと、歩きやすさといったものの環境も整えていくことが必要と考えております。高齢者、障害者の方に外出の機会を多くとっていただきたいと考えております。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"意見","question":"もうこの区内の移動、高齢者や障害者の皆さんの社会参加というのは進んでいかないのではないかというところまで来ているのではないかと私は思います。ぜひこの陳情者の皆さんの思いに応えて、もう待てない、苦労している、ここに今こそ応えるために…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"高橋（伸）委員","kind":"質問","question":"これから補助２６号線の整備に伴って、スクエア荏原に対しても、それはやはりバス事業者に対して働きかけていただくのが一番好ましいと考えています。その辺、現在の進捗状況というか働きかけはどのようにされているのか、ご答弁。","respondent":"中村都市計画課長","answer":"補助２６号線が、東京都からは開通の予定といたしましては平成３０年度中ということで、平成３１年３月に開通の予定だと聞いてあります。この開通と同時に路線運行ができればいいと考えておりますが、それから具体的なバス停ですとか、そういったものは未定です。","id":"exchange-019"},{"speaker":"高橋（伸）委員","kind":"質問・要望","question":"ありがとうございました。ぜひこれから先、区民の皆様のご要望に対して。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"塚本委員","kind":"質問・要望","question":"幾つか確認をさせていただきたいのですけれども、１つは公営、丸っきり公営でやる。そこを、今までの審査でさんざんそれはやられたかもしれませんが、建設委員は初めてなので教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"既存の路線バスの採算性にも影響を与えるということで、既存の路線バスへの影響と、それから採算性。それからあともう一つは、これは現実的には、バス停の設置を新たにするというのは近年非常に難しくなってきているというような話も伺っております。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"今、確かに２１区で実施をしているということから、何で品川区はやっていないのという話が区民の方からは自然に出ると。そういうところを区としてどのように見ているのか、もう少し具体的に、他区の例などを引きながら教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"これはもう本当になかなか他区にはないという状況です。コミュニティバスを走らせている例も、その区内のご自宅付近から目的地までを網羅するといったコミュニティバスとしての使い方は一区もない状況です。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問・要望","question":"今、もう少しざっくばらんに言うと、各区はこのコミュニティバスを走らせていることにおいてそれなりの財政負担が発生しているわけです。課長が漏れ聞くところというか、聞いているところでどのように評価しているのかというのを、わかる範囲で結構ですので教えてほしいと求めました。","respondent":"中村都市計画課長","answer":"港区とか千代田区といったところは、港区などは毎年３億円かそのぐらい補助、負担をしていると聞いてあります。足立区とか世田谷区、こういったところも路線は少ないのですけれども数千万円単位で出して、いずれも負担はやはりどうしても出てきてしまうです。","id":"exchange-023"},{"speaker":"筒井委員","kind":"質問・要望","question":"縦のバスのラインと鉄道網はぱっと見６本ぐらいあると思うのですけれども、横のラインが２本ぐらいしかないという状況だと見受けられます。せめてこの品川区の真横を通るコミュニティバス１路線程度は、将来というか検討を進めていただきたいのですけれども、いかがお考えか尋ねました。","respondent":"中村都市計画課長","answer":"これは大井町の駅まで来ていただきますと、武蔵小山までこの路線としてつながれば、非常に利便性が高くなるかなと認識をしております。こういったところを、今、現実的に進めていきたいと考えております。","id":"exchange-024"},{"speaker":"筒井委員","kind":"質問","question":"では、区としてはやはり補助２６号線を活用して、バスの乗入れを促していきたいというのが基本的なお考えだということか尋ねました。","respondent":"中村都市計画課長","answer":"現時点におきまして、今、一番可能性として高いところで、事業者のほうに積極的にお願いしていくべき路線と認識しております。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"コミュニティバスの要望というのは、それからニーズの把握、どれだけニーズがあるのでしょうか。それらを踏まえて、では、品川区にとってコミュニティバスという考え方をどのように捉えているのか尋ねました。","respondent":"中村都市計画課長","answer":"それからこの路線バスを１路線走らせるのに数千万円から数億円とかという話ですけれども、その辺の利用者の方々でこの運行費が相殺できるかどうか。その使っている税金を別の移動の手段として利用するという方法も、また別の選択肢も出てまいりますので…","id":"exchange-026"},{"speaker":"西本委員","kind":"提案","question":"ただ、これはコミュニティバスでないとできないのですかという話ですね。ここは建設委員会ですからそこまで踏み込みませんけれども、ほかの政策の中で叶えられますよという提案はできるかなと私は率直に思いましたとの意見を述べました。","respondent":"中村都市計画課長","answer":"本当の需要調査ということで、あるいは年齢層がどのぐらいの方がいらっしゃるか、そういったものを調査する必要があると考えています。これは、検討の際にはそういった必要があると考えます。","id":"exchange-027"},{"speaker":"西本委員","kind":"質問","question":"本当に具体的にどういうものが必要ですかということと、必要な人はこのぐらいいますというような、それこそコミュニティということだと思うので。やはり売上げを奪うような現象も起きてくるわけですから、やはりそれも含めて開示をして、。","respondent":"藤田都市環境部長","answer":"現段階ではやはりコミュニティバスの導入については考えていないという中での調査、直接今ストレートにやるという考え方は持ってございませんけれども、その調査のあり方については慎重に考えていかなければいけないと考えています。","id":"exchange-028"},{"speaker":"鈴木（真）委員","kind":"質問","question":"その中で、一部高橋委員から質問させてもらった補助２６号線の開通に伴って、そこの部分は路線の必要性も感じておりますが。やはりその部分は十分に対応できていると考えておりますので、その点からも、この陳情につきましては不採択という対応でお願いいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"塚本委員","kind":"質問・要望","question":"地場の方からそういったより充実したコミュニティバスの要望等をよく私どもも受けているところですけれども、供給型、サプライ型のサービスでいくと。これだけの効果で本当にいいのですか、どの路線に走らせればいいのですか、全ての要望のある路線に走らせるなどということはできないので。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"これを私たちは持っているわけですから、それを基本的人権として責務を負うというのは、地方自治体の責任だと私は考えます。ですので、こうした皆さんの声に応えるだけの税金はしっかり持っているわけですから、こんなにたくさんの請願がこの間寄せられている。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"},{"speaker":"木村副委員長","kind":"意見","question":"個人的には継続という形をとりたいという思いもあるのですけれども、結論を出すということで。今現在ではこれを通していくを軽々と考えることは私はどうなのかなと思いますので、現在のところは不採択との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"西本委員","kind":"提案","question":"それから地域の状況であったり、コミュニティバスというそもそもの考え方をやはり区民の皆様方の統一した見解をもとに走らせていく、さらに深く。今回の陳情者の方々の思いはわかりますが、ほかの方法でも十分に対応できるものもあるのではないかということを提案を申し上げて…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"}]},{"id":"topic-02","title":"平成２７年度指定管理者による管理に対するモニタリング・評価","agenda":"平成２７年度指定管理者による管理に対するモニタリング・評価","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"平成２７年のところの滞納者１件当たりの滞納回数が０.数回だったのが、２.３３回に増えていると感じるのですけれども、どのような状況だったのか伺いたいと思います。","respondent":"今井住宅課長","answer":"やはり１人ひとりの滞納者に複数回、なるべくお声かけをしていこうということで、対応回数を増やしたものです。これは、やはり株式会社品川宅建管理センターのほうが、職員だけではなくて、現場の管理主任も含めて対応していることからできているものです。","id":"exchange-034"},{"speaker":"西本委員","kind":"質問・要望","question":"それで、区営駐輪場本来の役割というのは何なのでしょうかということを教えてください。予算執行について、予算、コストの面から、あり方について教えてほしいと求めました。","respondent":"今井住宅課長、桑波田交通安全担当課長","answer":"やはり１人ひとりの方に対して、そういうことも含めて対応するのは、やはり現場にいる株式会社品川宅建管理センターの職員がやっております。あくまでも滞納が継続していく場合には、地域支援課との連携が必要になってまいりますので… 委託料につきましては、平成２５年度のほうからも増額している状況です。そういった場合にはまた必要経費ということでつけしていますので、今のところ適切に経費を払ってやっていただいているということで考えております。","id":"exchange-035"},{"speaker":"西本委員","kind":"質問・要望","question":"いろいろな部署との関係があるわけですから、速やかにリファーするのであればリファーして、速やかな対応をしていただきたいと思っています。自転車が非常にごつくなってきて、今後の大きな課題かなと私も感じましたので、このほうは今後の検討課題で。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-036"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4182#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":35177,"voices":108}},{"id":"h28-20160927-9","meetingId":"h28-cm09","date":"2016年9月27日","dateIso":"2016-09-27","committee":"文教委員会","time":"午前１０時００分～午後 ２時３９分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を107件整理しています。","topics":[{"id":"topic-01","title":"第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","agenda":"第８７号議案 品川区家庭的保育事業等の設備および運営の基準に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"確認","question":"そして、現在、品川区内で４階以上にある認可、認証、小規模、そして、わかれば無認可の園の数も含めて、それぞれ教えてください。そして３点目、屋外階段などをなくしてもいいということになるのかどうか、確認したいと思います。","respondent":"竹田保育課長","answer":"ちょっと今、手元にございませんので、ご回答できません。それから３番は、屋外階段も有効な避難方法の１つと考えておりますので、今のところはそういった考え方は示されていないところです。","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問","question":"そういう階段がなくなるということはないということでいいのかと受け取りましたが、もし違えばご答弁ほしいと求めました。１点目のところで、４階以上のところにこの小規模の保育園ですとかが、どういったものがあるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"屋外階段の考え方ですが、屋外階段については検討していくというような議論がされておりますので、その議論を見守っていきたいと考えています。それから、最上部に、直接外気に開放する排煙設備を設けること等が示されているものです。","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり子どもの安全がしっかり保たれていくことが重要だと思いますので、そういった視点で注視していってほしいと求めました。そういったものはやはり電気で動いていると思うのですけれども、停電時の場合、予備電源等というのはあるのか尋ねました。","respondent":"竹田保育課長","answer":"施設によって、構造等は異なると思いますが、非常時にも対応できるような設備にしていくように指導していきたいと思います。","id":"exchange-003"},{"speaker":"あべ委員","kind":"質問","question":"区内に４階以上の保育室はないということだったのですけれども、４階以上にできやすくなるとか、そういう感触はありますか。あるいは、これがハードルになって、なかなか場所が見つからないというような状況というのはあるのか尋ねました。","respondent":"大澤待機児童対策担当課長","answer":"１階でどうしてもできない場合でも、せめて２階ということでお願いしていますので、つくっていただくというような方向性を変える考えは今のところございません。","id":"exchange-004"},{"speaker":"あべ委員","kind":"質問・要望","question":"区はできるだけ１階、あるいはぜいぜい２階ということで、今後もそれを現実としてやっていただきたいなと。４階というのはちょっと考えづらいものもありますので、そのとおりに。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"既存の建物で２方向避難を確保したりするのがすごく困難だということで、確保がしやすくなっていくのかどうか、ちょっとそこが。品川区が認める、認めないよりも、そういう施設が上の階にできていく可能性が増えていくのかどうかというのを聞いています。","respondent":"竹田保育課長","answer":"４階以上の規定ですが、４階以上に関する規定はございまして、新たに４階以上が可能になったということではございません。４階以上と想定されるのは、なかなかそういうところで保育施設の経営が成り立っていくのかというのは、難しい課題もあろうかと考えています。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"可能にならないのですか。そこをちょっと、はっきりお答え下さい。","respondent":"竹田保育課長","answer":"先ほども申し上げましたとおり、４階以上の規定は従来もございました。可能性が増えたかというご質問ですけれども、安全性の選択肢は増えましたが、可能性といったものが大きく変わるものではないと考えています。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"変わらないですかね。改修等によって、選択肢が増えるということは、従来よりもよりやりやすくなる、確保しやすくなるという認識なのですけれども、違いますかね。","respondent":"竹田保育課長","answer":"今回の改正の一番の趣旨は、やはり子どもの安全性を高めるということが趣旨ですので、確保しやすくするための改正ではないと考えております。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"今回は、家庭的保育事業等の設備なのですけれども、認可保育園とか認証のところは、この部分はどこに含まれているのか。多分、建築基準法施行令の改定なので、みんな影響していると思うのですが、そこのところはどこであらわれているのか、説明を求めました。","respondent":"竹田保育課長","answer":"民間保育園等につきましては、東京都の条例のほうで定めておりまして、そちらが改正されたというふうに聞いております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問","question":"建築基準法施行令第１２３条の３項の改正のところは、建築課長にも保育課長にもお伺いして理解をしたところです。私は慎重に考えていかなくてはいけない規制緩和の１つと捉えて、反対をいたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"あべ委員","kind":"意見","question":"品川区では現実的に４階という選択肢は、運営について指導しつつ、運用してほしいと求めました。条例そのものについては、これは法改正に伴う一時的なものと考えておりますので、賛成いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"}]},{"id":"topic-02","title":"第９１号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","agenda":"第９１号議案 品川区立学校の学校医、学校歯科医および学校薬剤師の公務災害補償に関する条例の一部を改正する条例","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"こういった、ダブルで受けている方というのが、区内ではいるのかどうか伺いたいと思います。今回の改正に至った経緯も説明を求めました。","respondent":"有馬学務課長","answer":"平成１４年から市区町村が自ら行うということで条例を制定いたしましたけれども、そういう意味では、実例が今までないと。区は、東京都のほうに準じておりますので、それに合わせる形で今回の条例改正をするという形になったものです。","id":"exchange-012"},{"speaker":"のだて委員","kind":"質問","question":"済みません。ちょっと勉強不足で申しわけないのですけれども、この人事院の勧告が変更になったその経緯も、ぜひ教えてほしいと求めました。","respondent":"有馬学務課長","answer":"公立学校ですと、東京都の人事委員会勧告に基づいておりますので、都の基準をベースに改定は行われるというものが基礎になっております。そういうことを受けまして、今回の改正になったです。","id":"exchange-013"},{"speaker":"あべ委員","kind":"質問","question":"何かこう、これからもほとんど使う方がないだろうなと思われる内容。国から、都からといって、改正していくことになるのか尋ねました。","respondent":"有馬学務課長","answer":"これはまさに給与改定に連動している部分ですので、毎年あるような形になっています。いわゆる、何区かがそういうやり方をしているということがわかりましたので、ちょっとこれから研究をさせていただきたいというふうに思っております。","id":"exchange-014"}]},{"id":"topic-03","title":"第８５号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","agenda":"第８５号議案 平成２８年度品川区一般会計補正予算（歳出 文教委員会所管分）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"この補助単価の全体像がどうなっているのかをお聞きしたいのですが、この２つのほかに、伺いたいと思います。そして、今回出されたこの単価なのですが、園児１人当たり、１カ月の単価ということでいいのか、確認です。","respondent":"竹田保育課長","answer":"これ以外にも、障害児を受け入れた場合、アレルギー対応をした場合等々、加算項目がございまして、その加算項目に従って支給しています。こちらは、先ほど申し上げたとおり、児童１人当たりの単価です。","id":"exchange-015"},{"speaker":"のだて委員","kind":"質問","question":"別の点。開設支援の家賃支援補助、開設後月々の運営費の補助ということになってくるのかと思うのですが、その関係性を教えてほしいと求めました。","respondent":"大澤待機児童対策担当課長","answer":"開設後の家賃補助につきましては、坪単価で１万２,０００円を超える場合に、超えた部分を上限１万円までで５年間、区として補助する運用ですので、今回の賃借料加算とはまた別枠として補助しているものです。","id":"exchange-016"},{"speaker":"のだて委員","kind":"質問","question":"学校１１０番のほうをお聞きしたいのですが、今回、どんな事業者が工事していくのかということもご説明ほしいと求めました。今回、設置した後に、ランニングコストというのはかかってくるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"各施設によって異なりますが、設置場所は保育園の中ですと、多くは事務所の緊急時に使うことを想定した使いやすい場所に設置しています。ちょっと今、手元に資料がございません。","id":"exchange-017"},{"speaker":"のだて委員","kind":"確認","question":"どういう工事が必要かということもお聞きしたので、誰が工事していくのか、どういう事業者になるのか、伺いたいと思います。電話するよりも早いということで、効果があるということで設置していくということだと思うのですけれども、そういうことでいいのか確認です。","respondent":"竹田保育課長","answer":"企業等が多数ございまして、こちらのほうでこのシステムを運営しておりますので、こちらの参加企業等が実際に工事等を行うものです。それから、こちらのメリットですが、もうボタンを押すだけで通報ができるということで、緊急性を重視したという点が、こちらの最大のメリットで…","id":"exchange-018"},{"speaker":"のだて委員","kind":"質問","question":"工事はどういうものが必要なのかというところで、大規模な工事が必要になってくるのでしょうか。小規模保育事業の運営のほうにも影響が出てくると思うのですが、どういった工事が必要なのか、改めて伺いたいと思います。","respondent":"竹田保育課長","answer":"もの自体は、受話器とボタン部分だけですので、スペース的には本当に限られた、壁面に設置するような小さなスペースですので。は配線、あるいは電源等ですので、そんな大規模な改修工事というのは必要ないと考えております。","id":"exchange-019"},{"speaker":"あべ委員","kind":"確認","question":"ちょっと確認なのですが。先ほどご答弁のあったＮＰＯ、東京都セキュリティ、何とおっしゃいましたっけ。","respondent":"竹田保育課長","answer":"ＮＰＯ法人東京都セキュリティ促進協力会です。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"このセキュリティ促進協力会というのは、区としては、ここにもう全てをお願いする形なのでしょうかね。例えば、機種とか事業者とかは、一切かかわらず、あちらが決めて、あちらの仕組みで、あちらが決めて工事するという形になるのでしょうかね。","respondent":"竹田保育課長","answer":"こちらの団体は、東京都が契約している団体ですので、実際の工事のほうは、こういったノウハウをお持ちのところがやったほうが一番効率的なのかと思いますが、ちょっとほかの事業者、区内の事業者等ができるかどうかについては、ちょっと研究したいと思います。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"質問するにも、また。こちらで調べます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今回は１,７００万円の追加ということなのですが、全体的にはこれで幾らぐらいの補助になるのか、教えていただきたいのが１点です。これがいつぐらいにお金が入ってくるのかも説明を求めました。","respondent":"竹田保育課長","answer":"それ以外にも、冷暖房加算とか、賃借料加算とか、各種の加算項目を加えてそれぞれの施設に支給してまいるものです。予算規模としましては、１年間で約１３億円ほどを予定しています。","id":"exchange-023"},{"speaker":"飯沼委員","kind":"質問・要望","question":"基本的なところが抜けていたので、今日お伺いして、知りたいと思ったことなのですけれども。賃借料の加算も、今回６,３００万円、かなり大きいのですが、この辺の全体の規模、予算の規模も説明を求めました。","respondent":"竹田保育課長","answer":"賃借料に関する規模ですが、約３,４００万円ほどを予定しているものです。それから、品川区の独自補助という点では、認証は、大きなものは特段ございません。","id":"exchange-024"},{"speaker":"飯沼委員","kind":"質問","question":"今ちょっと、賃借料のところ、規模は３,４００万円で、今回加算の額のほうが大きいということですか。今までの賃借料加算よりも、今回、増額分、かなり、では、賃借料のところの増額が大きくなったという捉え方でいいのか尋ねました。","respondent":"竹田保育課長","answer":"こちら、お手元の資料をごらんのとおり、倍以上の増額になっておりますので、当初予算に比べて大きく増額になる予定です。","id":"exchange-025"},{"speaker":"飯沼委員","kind":"質問","question":"事業者さんとしては、大変、家賃とか高いので助かる中身であると思うのですが、この辺、この加算がされる経緯とかは、何か都のほうから聞いているのかどうか、その辺を説明を求めました。","respondent":"竹田保育課長","answer":"賃借料の実勢価格と、今までの加算額が開きがあったということで、その地価相場、実勢価格に近づけるといいますか、即した内容に充実するための改正だというふうに聞いております。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問","question":"考えていないところはなぜなのかなと、ご配慮が必要ではないかなと思っているのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"認可保育園と認証保育所は、基本的に性格が異なるものだと考えております。今後、認証保育所の支援については、検討していきたいと考えております。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"話を聞いたら、簡単な工事で終わるといった中身においては、ぜひ地元の電気工事ですか。地元に発注をするような申請、こういう工事は地元の発注をしていただけるような仕組みにしていただきたいなと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"今のところ、訓練等のときの使用のみとなっておりますので、基本的にランニングコストはそんなにかからないものだと思います。それから、実際の設置に当たっての方法等については、研究してまいりたいと考えています。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問","question":"今、ちらっとお答えいただいた、実際に余り、ケース的には使われていないということでよろしいのか尋ねました。","respondent":"竹田保育課長","answer":"実際に、緊急時、緊急な事件が発生して、そのボタンを押して応援を求めたというのは、近年はないというふうに聞いています。","id":"exchange-029"},{"speaker":"飯沼委員","kind":"質問・要望","question":"このような設備は使われないほうがいいのであって。そういった事例は余りないというか、安心させていただきたいところなのですが、いかがか尋ねました。","respondent":"村尾教育総合支援センター長","answer":"多分平成１３年の大阪の池田小事件があってからつけられたものということで、不審者対応では使っていますが、私の記憶では多分ないかなというふうに思っています。","id":"exchange-030"},{"speaker":"沢田副委員長","kind":"意見","question":"学校１１０番ということで、もう少し一本化というか、整理というのはできないのかなと思うのですけれども。ちょっと、この保育園だけではないのですけれども、その辺のお考えがあればと思うのですけれどもとの意見を述べました。","respondent":"中島教育長","answer":"なかなか一本化という体制での設置にはなっていないものですから、今からそれらの設備を一本化するというのは、なかなか難しいことかと思います。基本的な考え方だろうと思いますので、どこかでも、どこかで防波堤になれるような形を考えていきたいなと思います。","id":"exchange-031"}]},{"id":"topic-04","title":"平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願、および平成２８年請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願","agenda":"平成２８年請願第１１号 ひろまち保育園の公設公営を求める請願、および平成２８年請願第１３号 ひろまち保育園を区直営の保育園にすることを求める請願","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"ちょっと確認したいのですが、理事長の関与をさせないよう区が求めたという報道もありましたけれども、そこは確認です。この保護者会で行っている回答の方針でやっていくということでいいのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"先ほど申し上げたとおり、基本的に私どもが話す立場ではないのですけれども、新しい事業者と十分話し合っていきたいと考えております。以上です。","id":"exchange-032"},{"speaker":"のだて委員","kind":"質問・要望","question":"１年で事業者が変わってしまうというところでも心配はあると思うのですが、今回の事業者交代ということになったのか、伺いたいと思います。あるいは、保育士だけということになるのか、そこのところを教えてほしいと求めました。","respondent":"竹田保育課長","answer":"信頼関係を築いていくのは難しいというふうに考えたことと、来年４月から新しい体制を築くには、今回の決断に至ったものです。それから、職員については、次の事業者が決めることです。","id":"exchange-033"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、芦屋や横浜で建設中止の動きになった理由も、それは情報をやはりつかんでいってほしいと求めましたので、それは要望しておきます。保護者会の資料のところの６番のことですが、これから行っていくところで何が違うのか、具体的にご説明ほしいと求めました。","respondent":"竹田保育課長","answer":"港区は現法人が直接運営する私立認可保育園、こちらは区立の業務委託による保育園ですので、基本的に施設の性格が違うと考えております。基本的なやり方、選考方法に問題はなかったと考えておりますので、同様の内容で実施していきたいと考えております。","id":"exchange-034"},{"speaker":"のだて委員","kind":"質問","question":"つまりは、できるだけ気をつけていくと。どう、この事業者交代が繰り返されないようにしていくのか、担保はあるのか伺いたいと思います。","respondent":"竹田保育課長","answer":"委託というのは、あらゆるリスクを抱えている手法ですが、選考方法に問題はないと考えておりますので、このやり方でやっていきたいと考えます。今後も、万が一、不適切な場合は、強い気持ちで臨んでいきたいと考えています。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"これまで品川区立として質の高い保育を保ってきたという中で、保育の質を保てないと思うのですけれども、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"変える考えはありませんけれども、こういう解除に向けた対応もしたということもありますので、そういった事業者は来ないものだと考えています。そういった対応をしたのは、こういった期待に応える保育というものを、品川区として積み重ねていきたいと考えています。","id":"exchange-036"},{"speaker":"のだて委員","kind":"質問","question":"やはり、同じやり方でやっていく中で、この事業者変更というのが繰り返されない担保というのが、何もないと思うのですが。気持ちだけではなくて、しっかりやっていく、それだけではなくて改善が必要だと思うのですけれども、いかがか尋ねました。","respondent":"齋藤子ども未来部長","answer":"今回の事業者を変更したこと、合意解除に至ったこと、これは正しかったと私は思っております。品川区ではさまざまな取り組みをして体制も強化しておりますので、十分、今回の事案を通して広く発信できたのだと考えています。","id":"exchange-037"},{"speaker":"のだて委員","kind":"質問","question":"開設後の運営費のことだと思うのですけれども、運営費のチェックはしたのか、伺いたいと思います。もう１つ、受給しているとしても、正直に話せば不正ではないということか尋ねました。","respondent":"竹田保育課長","answer":"ただ、看護師の未配置の件ですが、４月の当初から定員が見つからないということで、求人中との報告を受けております。それから、運営費についても適正に使われているかどうかというのは、確認してまいると考えています。","id":"exchange-038"},{"speaker":"のだて委員","kind":"確認","question":"それとも、していくというご答弁だったのか、それを確認したいと思います。配置されていないけれども、運営費をもらっていたということを正直に話せば、不正ではないというお考えなのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"不正だと思いますが、事実の報告に基づいて報告していただいていますので、それを不正とは呼ばないと考えております。それから、運営費については、現在も確認しておりますし、今後も確認してまいります。","id":"exchange-039"},{"speaker":"のだて委員","kind":"質問・要望","question":"区民の理解も得られないと思いますが、やはり不正があったということでよろしいのか、伺いたいと思います。先の一般質問でも、このことを質問されてご答弁ありましたが、どこが相入れなかったのか教えてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"のだて委員","kind":"質問・要望","question":"ご答弁ありましたけれども、ほかに何が相入れなかったのか、伺いたいと思います。その後に、合意解除がされたということですので、法人のほうから、この契約を終わらせたいという問いかけがあったのか、伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"のだて委員","kind":"質問・要望","question":"１つ１つの細かいことの違いがあったということですが、それをしっかり、やはり明らかにしていくべきだと思います。やはりこの事態を明らかにしてほしいということと、私としては賛成し、採択を主張していきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"鈴木（博）委員","kind":"質問","question":"やはりどう対応するかというのが、１つの、要するに直面した問題だと思うのですけれども。その点に関してお伺いいたします。","respondent":"竹田保育課長、齋藤子ども未来部長","answer":"新しい事業者の選定につきましては、より厳正に、より慎重に、十分時間をかけて、しっかりと選定していきたいと考えます。 はなくて、子どもたちのために何が主点であるかということを考えて、対応していただいたところでございまして。本当に３月末まで、信頼関係、継続と。","id":"exchange-043"},{"speaker":"鈴木（博）委員","kind":"意見","question":"そうですね。こういうことはないだろうと思いながらも、やはりその点の追及というのも、しっかりお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問・要望","question":"教えていただきたいのが、締め切りはまだ来ておりませんけれども、関心を示してくださっているか。あるいは応募しそうかということは、わかれば説明を求めました。","respondent":"竹田保育課長","answer":"今回の選定に関しましては、より厳正に行っていきたいと思いますので、数字については現段階での発表ではなく、決まった後にご報告させていただきたいと考えております。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"より高い保育の質ということを求めてのことと思いますが、それはそれで品川区の姿勢を示すものであると、私は考えております。今回の選定に当たっては、そうした部分というのはお考えか尋ねました。","respondent":"竹田保育課長","answer":"これから、審査あるいは仕様書等の提示等が、今後あるわけですけれども、事業者に誤解の生じないような綿密な打ち合わせを行うことによって、しっかりと対応していきたいと考えております。","id":"exchange-046"},{"speaker":"あべ委員","kind":"質問・要望","question":"そこはやはり、区としても、さらにこういうところに気を使うというメッセージとしてわかりやすい言葉で出してほしいと求めました。再度お考えを伺いたいと思います。","respondent":"竹田保育課長","answer":"新しい事業者の決定が１０月を予定しております。１１月には、また次回の保護者会を開きたいと考えておりますので、保護者の方にも十分に説明していきたいと考えております。","id":"exchange-047"},{"speaker":"あべ委員","kind":"質問・要望","question":"その意味で、区は民間の事業者に保育を任せるのであれば、その目ききと言ったらいいのですかね。私立園として求めるレベルと、区立園として運営に求める保育の質や、その点についてはいかがお考えか尋ねました。","respondent":"竹田保育課長","answer":"公立の保育の答えというのは１つではないと思います。そういったものを融合させて、より高いレベルの保育を実施して、公設民営を通して実施していきたいと考えております。","id":"exchange-048"},{"speaker":"あべ委員","kind":"質問・要望","question":"今のお答えでは、先ほど、別の質問に対する答弁にあった、私立園に求めるものと、やはり区立園として守るべきものというのが違うのだと。ここは守るべきことなのだということは、区としてきちんと整理しておくべきだと考えるのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"おっしゃられるとおり、保育を実施していく中で、譲れる部分、譲れない部分というのはあります。今後、そういった面で整理して、今後の運営委託に生かしていきたいと考えております。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問・要望","question":"チェックするというところで、今されている、第１次審査会を迎えるに当たって、今されている具体的なチェックの内容ですかね。そういうところがもしお答えいただけるところがありましたら、教えてほしいと求めました。","respondent":"竹田保育課長","answer":"書類を通じて確認しておりますので、その確認を通して、適切な事業者かどうかというのを確認してまいりたいと思います。今後も２次審査等控えておりますので、そういったあらゆる場を使って確認していきたいと考えております。","id":"exchange-050"},{"speaker":"新妻委員","kind":"質問・要望","question":"大丈夫だという見方ではなくて、何か心配な点はないのかという、そういう視点で新たにまたチェックしてほしいと求めました。この選定会議というのが最終決定になると思うのですけれども、この選定会議で決定をする方々というのはどのような方で決定をされているのか尋ねました。","respondent":"竹田保育課長","answer":"選定会議のメンバーですが、副区長を筆頭に、部長、課長で構成されております。","id":"exchange-051"},{"speaker":"新妻委員","kind":"意見","question":"このことをまた教訓にしながら、本当に、一番子どもたちを守っていく、保育の質を高めるということが一番でありますので、そういう視点でまた、再度、選定をお願いをしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"飯沼委員","kind":"確認","question":"プロポーザルの要領で確認をし、こういった中身に一致していたにもかかわらず、何が違っていたのですか。保育方針の違いって何なのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"飯沼委員","kind":"質問・要望","question":"５年間は無理だったのですということで、区は何を求めて、それに対して不十分だったのか。姫路市に求めた信頼関係が保てなかった向こうの説明、ここの２つ、２点は具体的にお伺いしたいと思います。","respondent":"竹田保育課長","answer":"保育方針の違いということですが、扇風機の設置とか、聞き方によっては小さなことというふうにお考えになる方もいらっしゃるかもしれません。どういう原因で、どういう内容の不正があり、どういう再発防止策がとられるのかというような詳細の説明を求めたところです。","id":"exchange-054"},{"speaker":"飯沼委員","kind":"質問・要望","question":"詳細を求めて、何がどう不十分だったのか、それが１つです。その辺の中身はどうだったのか尋ねました。","respondent":"竹田保育課長","answer":"ただ、こちらの求めていたものとは隔たりがあったので、さらなる説明を求めましたが、出てきていない状況です。保育の方針というのは、小さいことの積み重ねですので、その積み重ねた結果が相入れなかったです。","id":"exchange-055"},{"speaker":"飯沼委員","kind":"質問","question":"港、いろいろなところから夢工房の実態の告発が届いているのですが、区はそういった中身を捉えていらっしゃるのでしょうか。先のことを見通して円満解決なのですという考え方が、とても理解できないのですが、法人についてどの程度担当されているのかをお伺いします。","respondent":"齋藤子ども未来部長","answer":"個々、何があったか、何を言ったか、向こうは何なのだということで、２つ目なのですけれども、我々は、相手方の法人を糾弾する立場にはありません。このことは、繰り返し申し上げさせていただきたいと思います。","id":"exchange-056"},{"speaker":"飯沼委員","kind":"質問・要望","question":"お互いの責任を不明確にして、先の、次の事業者を決めることが、子どもを守る立場なのでしょうか。経験年数が少ないうちに、給料が上がる前にやめてほしいって。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ひろまち保育園は、１２人かと思っていましたが、さっき１３人ってお話が。この点をどうお考えか尋ねました。","respondent":"齋藤子ども未来部長","answer":"いつも同じような論法でおっしゃいますけれども、６５％、３年以内に離職して、７都道府県、二十数園、理論値として運営できないのですけれども。どこでお知りになりましたか。","id":"exchange-058"},{"speaker":"飯沼委員","kind":"質問・要望","question":"普通は目に見えないところがわかったのだけれども、そこが全然、表に出てきていないではないですか。だから、理事長さんとかの方針と合わない保育で頑張っていたのではないかと。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"飯沼委員","kind":"質問","question":"契約をした中身と違う保育を実施していたというところでは、事業者の責任も明らかなのではないでしょうか。いかがか尋ねました。","respondent":"竹田保育課長","answer":"区は、昨年７月に、事業者の選定を行いました。以上です。","id":"exchange-060"},{"speaker":"飯沼委員","kind":"質問","question":"閉園にしてしまうことがあるのかもしれないけれども、区立の違いって、やはりそこなのではないですか。繰り返してしまいますが、検証が必要と思いますが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"繰り返しになりますけれども、次の選定に当たっては、しっかりと調査して、現場も見に行って、それで選定していきたいと考えております。","id":"exchange-061"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"話し合っていきたいという表現でしたけれども、そこのところを、これは要望ですけれども、きちんとしていただきたいということ。１つだけですけれども、そのあたりの違いの中で、どういうふうに指摘や指導をされていくかというのだけ確認したいと思います。","respondent":"竹田保育課長","answer":"しっかり３月までは保育を行っていくということを明言されておりますので、３月まではしっかりとやっていただきたいと考えております。指導検査を行う部署がありますので、そちらを通して、しっかりと保育の状況をチェックしていきたいと考えております。","id":"exchange-062"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"今、最後のところで、指導検査の部署ですか。こういったことにならないような形で、最終的にそごが出ないような形で、日常的にチェックのほうをしっかりしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"鈴木（博）委員","kind":"意見","question":"その理由は、要するに民設公営で、おおむね問題はないと思っているので。とりあえず、この公設公営ということに関しては、不採択ということでお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"},{"speaker":"新妻委員","kind":"質問・要望","question":"不採択です。ご説明をいただきましたとおり、今後しっかりとしたチェック機能をさせていただいた上で、民間の活力をしっかりと生かしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子ども第一のことを考えたならば、ぜひ区立認可保育園にしていただきたいという、この願いは十分理解できます。そして、ぜひ原因を明らかにしていただきたいという立場で、採択を主張します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-066"},{"speaker":"あべ委員","kind":"質問・要望","question":"それから２番。以上の理由をもって、今回の請願には不採択とさせてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-067"},{"speaker":"高橋（し）委員","kind":"意見","question":"１番のほうですけれども、民間活力の導入にもつながることでありますから、１番のほうは不採択ですね。２番のほうも、先ほどのご説明で、原因については理解できましたので、不採択ということですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"飯沼委員","kind":"意見","question":"問題点としては、待機児解消のために、民間保育園にどんどん誘致している品川区に来てほしいと。ひろまち保育園は区の責任で、区直営の公立保育園としてくださいという願いは十分理解できますので、採択を主張いたしますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-069"},{"speaker":"あべ委員","kind":"意見","question":"理由は、先ほど述べたところと同様です。１つつけ加えるのであれば、どういった形で公設民営をしていくのか、合わせて申し上げますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-070"}]},{"id":"topic-05","title":"を行います。 初めに、(1)専決処分の報告","agenda":"を行います。 初めに、(1)専決処分の報告","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"文書督促のところで滞納件数が２２５件というところですけれども、連絡があって返済に結びついたというのは何件になるのか伺いたいと思います。３番目としては弁護士の督促となっておりますけれども、この間で、電話での連絡というのはできたのか伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"１番目に、文書督促も行いながら、具体的にどの対応により数字が落ちていくというわけではないのですが。全く反応がなかったものが２件ございまして、電話も出なくなってしまった、文書による通知も受け取らないという。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"分納不履行だと、１回連絡がとれたけれども、また払いが滞ったというところで、連絡もとれなくなってしまったということだと思います。全く連絡がとれないのが２件あるというところで、ほかの３件についても、丁寧な対応をしていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-072"},{"speaker":"高橋（し）委員","kind":"意見","question":"１２０万円というのは、随分、額があれだと思ったのですけれども。私立で３年間、入学金も借りていても５、６０万円だと思ったのですけれども、その辺、済みませんとの意見を述べました。","respondent":"廣田子ども家庭支援課長","answer":"平成２４年に弁護士を導入するまでは、債権としては半分ぐらいになっておりますが、古いものもあるような状況です。今回、訴えを提起しているところは５年くらい、５年前後、滞納している方々に訴えを起こしているようなことになります。","id":"exchange-073"},{"speaker":"新妻委員","kind":"意見","question":"済みません。これを回収するに当たっての、どれだけお金がかかっているのか、説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"シルバー人材センターにつきましては、総価契約をしておりまして、年間で１３５万円ほどなのですが、２名の方に定期的に訪問をしていただいているところです。","id":"exchange-074"},{"speaker":"新妻委員","kind":"質問","question":"これは、基本、区の持ち出しというふうに考えてよろしいのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"そうですね。委託料よりも上回っているので、何もしないよりも回収したお金の中から報酬を払っているというところで、費用対効果はあると考えています。","id":"exchange-075"},{"speaker":"鈴木（博）委員","kind":"質問","question":"ずるい人間が、正直者がばかを見ないような社会にしていくように、その辺はくれぐれもお願いしたいと思うのですね。そういう意見に関してはいかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"弁護士を入れたことで、大分、取れるようになってきております。客観的な事実を積み重ねる必要があるので、ぜひ出てきてほしいと考えながら、訴えも辞さないという形をとっております。","id":"exchange-076"},{"speaker":"鈴木（博）委員","kind":"質問","question":"弁護士というのは、どういう方にお願いしているのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"かなり滞納があった分を、かなりの実績を上げた弁護士事務所を選びまして、債権管理を主にやってらっしゃる弁護士事務所に委託しております。","id":"exchange-077"},{"speaker":"鈴木（博）委員","kind":"質問","question":"そういう点は、検討とか踏まえて選択されているのでしょうか。弁護士費用をたくさん払うというよりは、むしろ公的な色彩を強く持っているような方にも流用できるのではないかと思います。","respondent":"廣田子ども家庭支援課長","answer":"丁寧な対応をしていただける弁護士、全部目を通しておりますが、きちんと対応していただいていると認識しております。着手金の金額については、自治体ということで３万円台でやっていただいているというところで、そんなに高く払っているという認識はないです。","id":"exchange-078"},{"speaker":"あべ委員","kind":"質問","question":"委員会では構わないのですけれども、閲覧なども全てこの状態になっているのでしょうか。ちょっと、個人情報の扱い、特に若年の方が被告となると、ちょっと社会的に影響もあるものですから。","respondent":"廣田子ども家庭支援課長","answer":"この個人名の部分につきましては、傍聴用と公開は、マスキングされております。","id":"exchange-079"},{"speaker":"あべ委員","kind":"確認","question":"一応確認させていただきました。この５件については、それぞれ生活状況を把握されて、返済能力ありと判断された上での提訴ということで理解してよろしいか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"連絡が全くない２件につきましては、会いたいので、訴えて会おうとしているという状況です。それに関して、きちんと聞き取りをしたいので、出てきていただくために提訴しているという意味合いのほうが強いです。","id":"exchange-080"},{"speaker":"あべ委員","kind":"質問","question":"それ以外の方法というのは、済みません。ほかにはとられる余地はなかったのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"適正な債権管理ということで、いたし方なく提訴し、裁判所から連絡が行っています。そうすると、あらかじめ和解のお話をするようなこともできますので、いたし方なくということでご理解いただきたいと思います。","id":"exchange-081"},{"speaker":"あべ委員","kind":"意見","question":"この奨学金に関しては、これまで何回ぐらい、何件の提訴をして、その後、どのような形になっているのか。皆さん、連絡がついて、それぞれ、それなりにお支払いいただいて終わり、ということであればいいのですけれども、その後について把握されていますかとの意見を述べました。","respondent":"廣田子ども家庭支援課長","answer":"提訴はしたのですが、本当に、明らかに払える能力がないということが、お話をしてわかったので、取り下げたのが３件。裁判所にも訪れなかったため、債務名義をとるということで判決をいただいたのが１４件という形になっております。","id":"exchange-082"},{"speaker":"あべ委員","kind":"質問","question":"９割返済してというのは、お名前が変わっていることなどを見ても、何と言ったらいいのですかね。その辺は、区としてどのようにお考えか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"弁護士から督促が行くときも、これで反応しないと提訴をしますという予告はさせていただいているところです。財産を押さえたりすることができませんので、公平性を考えると、苦渋の選択と考えていただければと思います。","id":"exchange-083"},{"speaker":"あべ委員","kind":"確認","question":"ちょっと確認なのですけれども。それも合わせてご答弁してください。","respondent":"廣田子ども家庭支援課長","answer":"この貸付金の滞納額の中には、これは貸し付けた金額だけしか入ってございません。年で０.５％〔翌日「５％」と答弁訂正あり〕という形ですが、取ったことは、実績はないです。","id":"exchange-084"},{"speaker":"あべ委員","kind":"質問・要望","question":"この５件の中を見ていても、提訴によらない方法というのも、今後もぜひ模索してほしいと求めました。とりあえず以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-085"},{"speaker":"飯沼委員","kind":"質問・要望","question":"月１５０戸とありますけれども、初めの２２５件から減っているのかというところも、それぞれの督促のところの効果というのを教えていただきたいのと。文書督促のところ、どのような文書を出しているのか、ちょっと、封筒の外と、中身もどういうことが書いてあるのか、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"２００件前後という形で、１５０万円から１７０万円ぐらい、コミュニケーションをとってもらっています。名前が出ているだけで、督促状であることがあけてみなければわからないですが、シンプルな内容です。","id":"exchange-086"},{"speaker":"飯沼委員","kind":"質問","question":"さっき、シルバーさんに任せるだけではなくて、職員の方が会っていろいろ相談に乗れるというような状況になるといいと思っているのですけれども。生活困難な人への対応で、福祉の必要な方など、支援のケースにつながったのがどのくらいあるのか、ちょっと教えていただけたらと思います。","respondent":"廣田子ども家庭支援課長","answer":"生保だったという方はいらっしゃいますが、どちらかというと、弁護士と話して、就労もきちんとしてくれたというようなケースは見られております。もう整理ができてきたので、なるべく電話等で、１件１件丁寧にやれるような時期に差しかかってきたかなという状況です。","id":"exchange-087"},{"speaker":"飯沼委員","kind":"質問","question":"一番最初の２２５件、平成２７年７月３０日現在の、これは何年間分の件数なのか。どこからの起点で数えてあるのかを説明を求めました。","respondent":"廣田子ども家庭支援課長","answer":"済みません。いつから、何年からかは申し上げられないのですけれども、昭和の時代から残っています。","id":"exchange-088"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１件１件いろいろな方がいらっしゃるし、コミュニケーションがとれるような状況に、なるべく努力をしていただきたいなと思うのと。早期にどんどん働きかけをして、状況をつかんで解決をしていく方向に行ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-089"}]},{"id":"topic-06","title":"大崎図書館の移転","agenda":"大崎図書館の移転","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"そして、芳水小学校内の２番のところですけれども、図書機能施設と書いてあるのですが、これはどういう位置づけになるのでしょうか。図書館とは違うということなのか伺いたいと思います。","respondent":"木村品川図書館長","answer":"これからまだ検討しているところでございまして、実際に１つ、新しいサービスを展開しようというところもあります。今のところは考えておりますけれども、それから位置づけに関しましても、これからまだ検討しています。","id":"exchange-090"},{"speaker":"のだて委員","kind":"質問","question":"２番の芳水小学校のところで、なくなっているように見えるのですが、今後どうしていくのか伺いたいと思います。当初冊数の問題は、増えてくる、２カ所になるので増えると思うのですが、その点のお聞きしたいと思います。","respondent":"木村品川図書館長","answer":"それから、西口の取次サービス、どこにですけれども、こちらのほうは、現在、調整、検討、先方とやっているところです。約５万冊の蔵書を、予定を今しているところでございまして、その分については新たに用意をするというような形になろうかというふうに思います。","id":"exchange-091"},{"speaker":"のだて委員","kind":"質問・要望","question":"やはり現地でこれまで歴史もあってやってきた中で、利用率も高いというところで、現地での存続を求めてまいりました。移転しなくても、改修や建てかえを行っていけばいいと思うのですが、改めて大崎図書館の現地での存続を求めたいと思いますが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"今まで議会でもご説明を繰り返しておりますとおり、移転に関しましての考え方は変えるつもりはございません。今ご説明しました芳水小学校のところの整備、地元の方、今まで愛してくださった方のご期待に応えたいというふうに思っております。","id":"exchange-092"},{"speaker":"あべ委員","kind":"質問","question":"新しいほうの大崎図書館、移転先のほうについてお伺いしたいのですが。何か、今、決まっている段階のものがあれば、イメージでも教えてほしいと求めました。","respondent":"木村品川図書館長","answer":"いわゆる近隣の方々の、基本的におはなし会と共用するかもしれませんけれども、そういうようなところも考えているところです。それから、いわゆるベビーカーの置き場でありますとか、あとは基本的に本を置く、本が読めるスペースというようなところで考えております。","id":"exchange-093"},{"speaker":"あべ委員","kind":"質問・要望","question":"閲覧席、これは何席ぐらい考えていらっしゃいますでしょうか。ぜひ子育て世代にも配慮していただきたいし、ぜひしていただきたいと思うのですが、その点も合わせて答弁をお願いします。","respondent":"木村品川図書館長","answer":"閲覧席につきましては、全部で１３０席程度を予定しております。そこは計画の説明会とかで、配慮をしてまいりたいと思うのと、ビジネス街というところがあります。","id":"exchange-094"},{"speaker":"あべ委員","kind":"質問・要望","question":"２年後の開館まで、いろいろと要望を出させてほしいと求めましたが、楽しみにされている施設でもあります。どういった内容の契約になっているのか、内容を教えてほしいと求めましたが、わかりますか尋ねました。","respondent":"木村品川図書館長","answer":"定期借地権のことでよろしいでしょうか。","id":"exchange-095"},{"speaker":"あべ委員","kind":"質問","question":"逆に図書館のほうは、建物の一部のフロアをお借りする形になるのでしょうかね。それとも、これは、区の持ち分として所有を残す形なのかも説明を求めました。","respondent":"木村品川図書館長","answer":"区分所有として、区のものとして所有します。","id":"exchange-096"},{"speaker":"あべ委員","kind":"質問","question":"本当に普通の取次サービス、あるいは武蔵小山などのイメージだったものですから、ちょっと伺ってびっくりしたのですけれども。まだ未定かもしれませんけれども、営業時間といったらいいのか、開設時間はどのような感じになるのか尋ねました。","respondent":"木村品川図書館長","answer":"そちらで検討しています。そういう形の集えるスペースというのですか、そういうものをちょっと予定をしているものですが、これも検討中です。","id":"exchange-097"},{"speaker":"あべ委員","kind":"質問","question":"いろいろ、１５０平方メートルというと、できることがとても増えてくると思うのですが、これは今後、どのような形で検討をされていくのでしょうか。単なるフリースペースで終わるということはないのですよね。","respondent":"木村品川図書館長","answer":"今、委員からのご指摘もございましたということもないのですけれども、実際にそれも踏まえまして、まだ、いわゆる検討段階ですので、そこの活用方法、使い方という形は、さらにちょっと練っていきたいというふうに考えております。","id":"exchange-098"},{"speaker":"あべ委員","kind":"質問・要望","question":"どういうふうに使うかということを、あるいは議会の意見なども聞きながら進めていってほしいと求めましたが、いかがでしょうか。質問です。","respondent":"木村品川図書館長","answer":"ちょっと先方の調整との関係もございまして、今、そういう形です。それから、使用方法、活用方法につきましては、引き続き、おっしゃるとおり、いろいろな方の意見を聞きながら検討してまいりたいと考えています。","id":"exchange-099"},{"speaker":"あべ委員","kind":"提案","question":"このたび新たにご提案が、しかも図書にかかわる施設が３つできようとしているわけで、これはこれで大変ありがたいことだと思います。埋めていくような中長期的なお考えというのは、区としては問題意識として持っているかどうか、確認したいと思いますとの意見を述べました。","respondent":"木村品川図書館長","answer":"例えば面積の拡充だとか、そういう形で可能であれば、そういう形で考えていきたいというふうに思っておりますが。新規で図書館を何かというような形の考えは、今のところございません。","id":"exchange-100"},{"speaker":"飯沼委員","kind":"質問","question":"何か、地域の方が同じような規模というか、現地に建てかえてほしい。どうなっていくのだろうということでは、とても失望されてしまうなと思うのですが、その辺はいかがか尋ねました。","respondent":"木村品川図書館長","answer":"現在予定しています、そういう意味では違うではないかと言われるかもしれませんが、小規模の図書館としてのスペースは確保してきたつもりです。そういう部分も活用いただきながら…","id":"exchange-101"},{"speaker":"飯沼委員","kind":"質問・要望","question":"蔵書なのですが、先ほど５万冊ということなのですが、児童図書とか、あと、現在、ここの特色のビジネス図書がどこに行くのか教えていただきたいです。とりあえず、それで。","respondent":"木村品川図書館長","answer":"基本的には一般の図書、それから児童の図書、整備してまいる考えでおります。今の区の関連という部分で、いわゆる差配ができる部分ですので、これから検討してまいりたいというふうに思っています。","id":"exchange-102"},{"speaker":"飯沼委員","kind":"提案","question":"そういった意味では、やはりこのご提案では、明らかに縮小だと思うのですね。図書館という機能にしていただきたいということと、ぜひお答えいただきたいのですが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"考えではおりますけれども、要望されているかという部分も含めまして、重ねてこれからも検討してまいりたいというところで。すぐ即答という形でのお答えはできませんけれども、それから西口に関しましては、今後明らかにご報告をしてまいりたいというふうに考えています。","id":"exchange-103"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ機能をしっかりと備えてほしいのと、あっちに移したというのではなくて、やはり活用される方向を続けていっていただきたいなと思います。区のほうにも伝わっていることと思いますので、ぜひぜひ前向きにご検討を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-104"}]},{"id":"topic-07","title":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","agenda":"今定例会の一般質問に係る所管質問ですが、今定例会の一般質問中、文教委員会にかかわる項目","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"質問したのですが、その項目を具体的に出していただきたい、お答えほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-105"},{"speaker":"のだて委員","kind":"質問","question":"区の責任がないのかという質問にも、具体的な答弁がありませんでしたので、それについてもお聞きしたいと。その理由ですね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-106"},{"speaker":"飯沼委員","kind":"質問","question":"コスト等、民間委託についての検証を行っていきますというご答弁があったので、この辺の中身をもうちょっと具体的にお伺いしたいなと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-107"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4894#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":64859,"voices":348}},{"id":"h28-20160927-5","meetingId":"h28-cm09","date":"2016年9月27日","dateIso":"2016-09-27","committee":"総務委員会","time":"午前１０時００分～午前１１時１０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を22件整理しています。","topics":[{"id":"topic-01","title":"第８６号議案、品川区特別区税条例の一部を改正する条例","agenda":"第８６号議案、品川区特別区税条例の一部を改正する条例","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"３、１のところが１年ちょっと違っている、その点についてどういうふうに考えていったらいいのかというのをちょっと教えてほしいと求めました。その辺について教えてほしいと求めました。","respondent":"黒田税務課長","answer":"今回、国のほうの施策で自己管理を進めセルフメディケーション等を実現するということで、制度が設けられたということでではないかと思います。３点目の、現在こういった制度がありませんので、現時点では把握できていないというものです。","id":"exchange-001"},{"speaker":"吉田委員","kind":"質問","question":"すみません、今の質疑を伺っていて、セルフメディケーションの考え方はわかりました。区民としてはこういうふうに控除の制度が変わった場合、この一般医薬品なら控除が受けられるとかいう判断はどういうふうにできるのか尋ねました。","respondent":"黒田税務課長","answer":"この８２種類を有効成分とする医薬品で市販されているものが対象だということで、調べますと今年の８月時点で１,５２３製品が対象となっているということで、そういった対応がなされてくるのではないかと考えているものです。","id":"exchange-002"},{"speaker":"吉田委員","kind":"質問","question":"では、区として控除のことはこの制度をつくるということだけであって、あとは薬局に行ったときに区民が問い合わせるなり、業界のほうでこれは使えますよという表示がされていくであろう、そこ頼みという言い方は変ですけれども、そういう制度に任せられるというふうに理解するということか尋ねました。","respondent":"黒田税務課長","answer":"「関係者と協力して周知を行っていく」ということになっておりますので、要は医薬品を販売する会社等、これが新たに対象となるということを当然周知を図っていくということになるかと思います。","id":"exchange-003"},{"speaker":"つる副委員長","kind":"確認","question":"今の１点、細かいことで恐縮なのですが確認で、処方箋とかだと薬局で薬を確認する。もし、わかっているところがあれば教えていただければと。","respondent":"黒田税務課長","answer":"今後、ご自身できちんと控除を申告していただいて、税務署についてはその申告書を受けて所得税を算定すると。住民税は、確定申告書に基づいて計算するということで、今後新たな制度としてわかるのが表示されるのではないかと考えているところです。","id":"exchange-004"}]},{"id":"topic-02","title":"第９２号議案、芳水小学校第１期校舎改築その他給排水衛生設備工事請負契約","agenda":"第９２号議案、芳水小学校第１期校舎改築その他給排水衛生設備工事請負契約","exchanges":[{"speaker":"南委員","kind":"質問","question":"いつもこういう契約については、学校ですからほかの電気設備だとか空調設備だとかそういうところと一緒に出るのですけれども、今回、これだけになったのはなぜかというところを一つ伺いたいと思います。","respondent":"立川経理課長","answer":"関連別途工事ということで３つ挙げているところですが、こちらは平成２８年第２回定例会におきまして、既に議決をいただいたところです。第２回定例会に上程する準備をしておりましたが、こちらにつきましては不調になりまして…","id":"exchange-005"},{"speaker":"南委員","kind":"質問・要望","question":"今回の２億４,０２１万３,０００円と比較してどのような数字だったのか、ちょっと教えていただきたいのと。さっき言ったように不調になった原因を改めてどのようなふうに区としては捉えているのか、お話を伺いたいと思うのですけれども。","respondent":"立川経理課長","answer":"入札の予定価格が２億１,４０６万６,０００円でございまして、今回が予定価格２億４,０２１万３,６００円ということで、実施したところです。国や都の基準に沿って予定価格を積算していますが、いわゆる現場の実勢価格と多少乖離していたということで、増額を図ったです。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"税金の執行ですからできるだけ安く、安くというのかしら、なかなか運営そのものも人を雇用するのも含めて大変な事態があると聞いているのですね。ちょっと教えていただきたいのと、安かろう、そのあたりについての区の考え方というものとちょっと改めてこの際伺っておきたいなと思います。","respondent":"立川経理課長","answer":"公共工事につきましては、以前からお話しをしているとおり、国と都の基準に沿ってまず予定価格を出す、そういう縛りがあるところです。区としましては、今後とも最新の国、東京都の単価を用いて積算しまして適正に執行していきたいと考えております。","id":"exchange-007"},{"speaker":"南委員","kind":"質問・要望","question":"それはそのとおりだとは思うのですが、しかし、一つちょっとそこのところを説明していただきたいのですが。さっきも言ったように職人さんと言っていいのでしょうか、循環させていくという点で、どうなのか尋ねました。","respondent":"立川経理課長","answer":"いわゆる予定価格の中身につきましては、その３つが主ですけれども、二年についてはかなり安定してきているのではないかです。それを参考にさせていただきまして予定価格を設定するということで、いわゆる不調にならない工事契約を実施していきたいと考えているところです。","id":"exchange-008"},{"speaker":"南委員","kind":"質問","question":"これはそういう方々がいなければどのような大事な工事であっても進んでいかないわけですから、そういう実態があるのではないかと私は思うのです。あるいは幾つも契約関係をやっていただいているという事業所がいっぱいあるわけですから、考え方としてどうなのかを伺って終わりにしたいと思います。","respondent":"立川経理課長","answer":"いわゆる契約の執行ですので、まず適正な予定価格をどう設定するかということが一番重要かと考えております。かつ、現場の実勢価格を反映できるように見積もりをとったりということで、今後とも実施していきたいと考えております。","id":"exchange-009"},{"speaker":"南委員","kind":"質問・要望","question":"そういうことをして実態を掌握していくということは私は大事なことだと思うので、さきほど聞いていただきたいとお願いしたのですけれども。そこの点の意見の見解も求めたつもりなのですが、その辺、答弁お願いします。","respondent":"立川経理課長","answer":"経理課としましては、いわゆる労働者の団体の方のお話を聞く機会を定期的に設けておりますので、年に１回ですけれども、実際に現場のさまざまな業種の方の意見は聞いているところです。","id":"exchange-010"},{"speaker":"南委員","kind":"質問・要望","question":"すみません、最後と言いながら、本当に最後にしたいと思います。年１回ということで聞いているという話は、年１回ということではなくてもう少しきめ細かくつかむ努力というのはしていただきたいと思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"須貝委員","kind":"質問","question":"質問なのですが、工事費というのは民間の算定会社に入札予定価格というのを区としては、経理課としてはそこにお願いをしているのですか。それとも、区の中にやれる人がいるのか尋ねました。","respondent":"小林施設整備課長","answer":"設計につきましては、民間のほうの設計事務所に委託をかけておりまして、そちらのほうで積算をして値入れ等の単価を入れて工事費を出しています。","id":"exchange-012"},{"speaker":"須貝委員","kind":"質問","question":"算定会社というところが専門にあって、民間ですからいろいろな会社が見積もりをとっているわけですよね、見積もり価格を出しているわけですけれども。１社の１番目の入札価格が１回目、２億４,０２１万３,０００円、どんびしゃではないか尋ねました。","respondent":"小林施設整備課長","answer":"品川区の入札制度は、東京都にならいまして、いわゆる事前に予定価格を公表しておりますので、ですからこういった金額になるです。","id":"exchange-013"},{"speaker":"須貝委員","kind":"意見","question":"どんぴしゃということは、本当に気持ちが合ってやるわけだし、何か何でこんな金額をわざわざ出すのかなというのも非常に不可解なこともあるので。ただ、ちょっと一般の人から見ても疑念を持たれるような感じになるのではないかと思いますので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"吉田委員","kind":"質問・要望","question":"そもそもの概要書と図面の中の読み取り方をもう少し伺いたいのですけれども、その説明が私には何かよくわからなくて。それから雨水利用設備と太陽熱利用設備というのがどういうものになるのか教えていただきたい。","respondent":"小林施設整備課長","answer":"今回の給排水衛生設備工事につきましては、これは説明し始めますとかなり細かくなります。中身についてはこれは膨大になっていますので、そこら辺についてはちょっと今回の概略の工事内容ということで明記をしたところです。","id":"exchange-015"},{"speaker":"吉田委員","kind":"質問・要望","question":"この概要書でこれを承認というようなことが今この委員会に求められていますので、何かそれで判断してしまっていいのかなと思ったので伺いました。大変なのはわかりますが、雨水利用設備と太陽熱利用設備について、どういうものになるのか説明を求めました。","respondent":"小林施設整備課長","answer":"これは、２つとも今小学校、中学校、学校関係でエコがかなり進んでおります。配管に水を入れまして、太陽の熱でそれを温めて給湯に補助的に使うとか、そういうシステムです。","id":"exchange-016"},{"speaker":"吉田委員","kind":"質問","question":"私、そういう設備は大変推進する立場ですのでとてもいいと思うのですが、規模はどれぐらいか教えていただけますか。その辺のことを教えていただけますか。","respondent":"小林施設整備課長","answer":"なくなれば当然今説明された上水で流すということで、雨水利用というのはあくまでも補助ですよというところで、全部それで賄うわけではございません。というところで、私のほうでここでお話しできるのは以上です。","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"提案","question":"それこそ税金をしっかり使うなら、そこでもう一回提案してもらったほうがよほどいいわけではないですか、ＶＥかけるとか。そういうことのほうを考えるというのが、だけれども区でもそれぐらいのことを今のこの時期はしょうがないから考えたらどうですかと、入札に対してとの意見を述べました。","respondent":"小林施設整備課長、立川経理課長","answer":"最初の工期の問題についてお答えします。そちらのほうが今現在芳水小学校がかかり始めたところですので、十分工期的には現状の工期で間に合うというところは確認はしております。 これまでもいわゆる区内業者だけで落札されない場合は都内全域の業者まで広げて再入札を実施したりということも年に数件やっているところです。いわゆるＪＶ、過去にも実施した例があるのですけれども…","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"提案","question":"ＶＥというのは、提案してもらってどういうものだったらこういう代替で同等品でこれなら下がるというのを相当かける。これだから、そこら辺はぜひお考えいただいて、こういうのが不調にならないようにやっていただきたいなというのだけ要望しておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"}]},{"id":"topic-03","title":"平成２８年請願第９号、固定資産税及び都市計画税の軽減措置の継続","agenda":"平成２８年請願第９号、固定資産税及び都市計画税の軽減措置の継続","exchanges":[{"speaker":"南委員","kind":"確認","question":"それに加えて後継者不足と、数年そういう状況が続いているという状況になっています。区としてもこういう経済状況についての認識というのはどういうふうに持っていられるのか、改めてちょっとその点を確認をしたいと思います。","respondent":"黒田税務課長","answer":"経済状況の認識ですが、とりわけ経済状況という中でも２３区内の地価に対して不均衡があるのではないかという願意というふうに受けとめております。経済としては少し回復基調にあるのかなということになりますが、そういった傾向にあるかと思っているものです。","id":"exchange-020"},{"speaker":"南委員","kind":"質問・要望","question":"金融緩和が実態に反映していないというのがずっと長引いている状況があるわけですから、その辺について改めて伺っておきたいと思いました。","respondent":"黒田税務課長","answer":"一つをもって説明しにくいところもあるのですが、特に２３区内、地価の側面から言えば回復基調にあると言えるのではないかと思います。固定資産税は持っているだけでかかる税ですので、そういった面もあるのではないかと思っているものです。","id":"exchange-021"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"２３区はこの部分については市町村民税と考えていますが、もうずっといろいろ語り尽せないほど語り尽しておりますし、都議会にもこの請願は出ている。なかなかそういう形にはいかないということなので、ぜひ品川区としても採択をしていただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2056#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":20201,"voices":83}},{"id":"h28-20160928-6","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"区民委員会","time":"午前１０時００分～午後 ０時５３分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を43件整理しています。","topics":[{"id":"topic-01","title":"はじめに、(1)平成２７年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"はじめに、(1)平成２７年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"ここに来る人たちはみんなビジネスなわけですから、目的を持って来ているわけですから、この辺は１００％になってもいいのではないかなと。ヤマダ電機側というのでしょうか、正面側も老朽化をしているわけですから、管理をしている場所が違うというならあれなのですが。","respondent":"立木産業活性化担当課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"現在８５％の方が満足ということでいただいている中では、これをより１００％に近づけるような形に今後もやっていきたいと考えています。… 全部で４台をうちのほうの管理、その中で連携をしながら、現在調整をしています。ご指摘ありましたように… 委員からお話のありました２０２０年のオリンピックに対する対応ですけれども、そちらの会議の席で、周知はさせていただいたところです。ということで…","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"１桁台なのかとか思ってしまうので、稼働率が低いのは本当に残念というか、この辺はしっかりやってほしいと求めました。それで一言何かあれば。","respondent":"立木産業活性化担当課長","answer":"その利用時間となりますので、全ての機器を使ってということではないのですけれども、おおよそ１０％の利用率ということになってあります。スタッフの増員等も含めまして、例えば利用しやすい環境等も整えながら、ＰＲを含めて考えたいと考えています。","id":"exchange-002"},{"speaker":"中塚委員","kind":"質問","question":"先ほどあった品川区スポーツ協会の３つですけれども、区のＯＢは何人天下っているのか、それを区は把握しているのかを伺いたいと思います。それともそれぞれの指定管理者が声をかけているということなのか、そもそも品川区自身は把握していないのか、全体像についてもあわせて伺いたいです。","respondent":"立木産業活性化担当課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"品川ビジネスクラブにただいま在籍しております区のＯＢ職員としましては、部長級で退職した職員がただいま１名、品川ビジネスクラブに在籍はしています。 文化振興事業団につきまして、元区の職員の人数ですが、手元に資料がないので正確な数字はあれですけれども、たしか七、八名、今いるかと思います。… スポーツ協会ですけれども、スポーツ協会につきましては、およそ１０人ぐらいの元区の職員が勤務しています。","id":"exchange-003"},{"speaker":"中塚委員","kind":"質問","question":"住民から見れば、チェックが甘くならないのか、関係がどうなっているのかという率直な声を伺うことはあります。もちろん区としての立場の答弁を伺うのですけれども、区としては、この関係についてはどのように考えているのか伺いたいと思います。","respondent":"立木産業活性化担当課長、鈴木文化観光課長、池田スポーツ推進課長","answer":"こちらの品川ビジネスクラブも理事会、評議会がございまして、人事案件はこちらで全て決定をとっているところです。連携して事業を行っていく上では… 人材の登用につきましては、事業団側の必要に応じて、区に打診をしたりということでやっていると思われます。人事関係のことなので… スポーツ協会におきましても、評議員会、理事会等を経まして人事案件について決定されているです。こちらにつきましては…","id":"exchange-004"},{"speaker":"中塚委員","kind":"質問","question":"部長も含めてご答弁いただきましたけれども、１点だけ、ＯＢがいることで連携ができると。その点について、最後にもう一度伺いたいと思います。","respondent":"堀越地域振興部長","answer":"区としての評価ですが、この総括シートの裏面に、経営会議における評価結果というところがあります。その点につきまして、公正かつ適切に議会にもご報告し、運用をされていると考えているところです。","id":"exchange-005"},{"speaker":"中塚委員","kind":"質問・要望","question":"９０％の現状でも、きゅりあんはなかなかとれないという話も私は伺っているだけに、ここのお考えを１つ伺いたいと思います。とても大事な視点ではないかと思うのですけれども、現状が幾つかというのと、今後増やしていく方向についても伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"改修に取り組む調整、計画を立てているところですので、その中でまた検討したいと考えております。指定管理者の側、それから今後の対応について話し合いをしていますので、できるだけ早く対応がしっかりとできるようにと考えているところです。","id":"exchange-006"},{"speaker":"中塚委員","kind":"質問・要望","question":"点字ブロックのほうは実態も見ていただいて、また障害者団体の方々のご意見もよく伺って、進めていただきたいと改めて伝えておきます。区からのお願いという形になりますけれども、ぜひこれは調整していただけたらと思うのですが、その１点だけ伺いたいと思います。","respondent":"鈴木文化観光課長、池田スポーツ推進課長","answer":"聴覚に支障のある方への対応ですが、チラシへの表示も委員ご指摘のとおり、効果があるかと思います。区のものと事業団のものと… 基本的に平成２７年度につきましては、その分についてはその年度で終わりまして、次の年に違うスポーツ教室を行ったということで。… 体育館事業ということでなく、連盟の自主事業ということで、教室は実施しています。","id":"exchange-007"},{"speaker":"中塚委員","kind":"質問","question":"最後に１点だけ。最後に、マイナースポーツへの将来性といいますか、視点について伺いたいと思います。","respondent":"池田スポーツ推進課長","answer":"私どものスポーツ協会としましては、区民の皆様にいろいろなスポーツを体験してもらう。そして上達していっていただけるような教室というものを、私どもとして、スポーツ協会とともに今後は検討しながらやっていきたいと考えております。","id":"exchange-008"},{"speaker":"藤原委員","kind":"質問・要望","question":"ああいうふうにしますというお考えがあったり、話し合いがあったりしているならば、具体的に改めて教えてほしいと求めました。感覚的にもうウォシュレットを使っていますと、なぜウォシュレットになっていないのか、今後ともなる形はないのかということを教えていただきたい。","respondent":"堀越地域振興部長、鈴木文化観光課長、安藤文化スポーツ振興部長、池田スポーツ推進課長、小川オリンピック・パラリンピック準備課長","answer":"区の設置者としての主体性に関与しつつも、指定管理者の側で主体的に運営にかかわってこられるという部分が、非常に評価している部分です。… 具体的にはエレベーターについては来年度、工事を予定しておりますので、具体的な詳細の設計の調整をしています。それと民間事業者の方… 事業団もさることながら、区民の文化芸術についての振興を第一の役割としています。そんな中でのさまざまな事業展開の中では… 今後トイレの改修等がございましたら…","id":"exchange-009"},{"speaker":"田中委員","kind":"確認","question":"いいこと、言い方があれなのですけれども、悪い面も出してもらわないとあれだなというのが。区民満足度が高いところが確認できるというのは、そういうことに関して、今後どういうふうに考えているのかを聞かせていただけると。","respondent":"立木産業活性化担当課長","answer":"指定管理業者のほうで実施しました利用者アンケート等で、例えば先ほど事例で申し上げました、そういったところが幾つか出てきているものはあります。決して不満の声が全くないということではございませんので、そういった部分は改善しながらという形でやらせていただいておりま…","id":"exchange-010"},{"speaker":"田中委員","kind":"意見","question":"きゅりあんの授乳室について、とてもありがたいといった声をすごくいただいていたので、ありがとうありますという話です。誰でもトイレに大人用のベッドがあると本当に助かるというお話を、障害者団体の方たちからいただいているので、ぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"伊藤副委員長","kind":"質問・要望","question":"果たして正しいのかどうかということを、正しいと思ったから品川区は指定しているのだろうけれども、改めて品川区にお伺いしたい。さらに進んで情報公開やら、今この時点でふさわしい報告を求めていくことが必要だと思うのですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"そこでは選定をしっかりやりまして、３団体とも非常に拮抗した中身になってございました。３年ほど前に公益法人になってから、全てガバナンス等も明確にして、今やっているところです。","id":"exchange-012"},{"speaker":"伊藤副委員長","kind":"質問","question":"公募したことは聞いていなくて、すみませんでした。それこそ１０年に一遍ぐらい事業見直しをして、おそらく指定管理者制度の制度の構造な気がするのだけれども、品川区のお考えはいかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"コンプライアンスも、透明性をとにかく確保しろということで、今言った財務諸表だとかそういうものを、全て公開しているところです。そんな中で、なおかつ財務状況等を公表、また機会を通じて、ガラス張りになるよう、事業団のほうにも働きをかけながら…","id":"exchange-013"},{"speaker":"本多委員","kind":"確認","question":"平成２７年度の評価ですけれども、自己点検なのですが、例えば平成２７年度のきゅりあんで行った成人式。こういうモニタリング、ペーパーでは読み取れない部分があるものだと思うのですが、その辺についてだけ確認をさせてください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]},{"id":"topic-02","title":"品川区制７０周年記念品川歴史館特別展 品川産業事始─日本を支えた近代産業群─","agenda":"品川区制７０周年記念品川歴史館特別展 品川産業事始─日本を支えた近代産業群─","exchanges":[{"speaker":"藤原委員","kind":"質問・要望","question":"なぜ品川区制７０周年記念という形に持ってきたのか教えていただきたいのと、歴史館の中には学芸員がいらっしゃいますよね。だから、そこがどうなのかなという思いがあるのですけれども、その辺について答えていただけますか。","respondent":"鈴木文化観光課長","answer":"さまざまなことを取り組んでいたり、それと区民の方へのいろいろな説明とか学習会の講師、非常に重要な人材の皆さんだと考えております。非常勤の位置づけの中で、勤務の体制のシフトを少し変更させていただいて、集中して事業にしっかり取り組めるようなことも対応する中で。","id":"exchange-015"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、私はその辺の、経済は大事ですから、どうか今までずっといてくださっているのは、１年間の契約ですよね。この件はじっくりやりたいので、決算特別委員会のときにまた聞かせてほしいと求めましたが、いただきますということで終わりたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"こんの委員","kind":"質問","question":"まちの状況のこととかお聞きしたいと思いますが、大変いつも見てほしい内容なのですが、こういうものをされているのかなと思います。立地条件からすると、なかなか足を運んでもらいにくい位置なので、どのように考えていらっしゃるのか、その点をまず。","respondent":"鈴木文化観光課長","answer":"講習室とかいろいろ考えますと、特別展のときにはそのテーマによって、特に何人ぐらいの予定というのはあまり目標としては持っておりません。できるだけ多く来ていただきたいというのが考え方で、それに沿った周知、ＰＲをしています。","id":"exchange-017"},{"speaker":"こんの委員","kind":"質問・要望","question":"品川区として発信をする１つのテーマであるものとしては、広く来てほしいだけではなくて、しっかりやっていただきたいなという思いです。見てほしい、こういうものをされたらどうなのかなと思うのですけれども、何かあればご答弁を。","respondent":"鈴木文化観光課長","answer":"歴史館も十分品川の観光資源として活用できるというのは考えているところですので、今いただいたアクセスとか、そのために効率的に回る方法ですね。そういうトータルで歴史館の知名度を上げたり、活用していただけるという方法も…","id":"exchange-018"}]},{"id":"topic-03","title":"しながわ観光フェア","agenda":"しながわ観光フェア","exchanges":[{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば7)番に東急バス乗車のアトラクションと書いてありますけれども、西大井から大井町のバスは巡回ですから、というのが１点。開催場所も、周知方法を考えてというか、さっき私が申し上げたところにやらない理由を説明を求めました。","respondent":"鈴木文化観光課長","answer":"説明が足りなかったのですが、連携した事業で、できるだけ区内全域で展開できるような趣旨は考えているところです。大変申し訳ありません、これは私の説明の仕方が悪くて、東急にもお願いをしております。","id":"exchange-019"},{"speaker":"いながわ委員","kind":"質問・要望","question":"施設、いろいろなところで文化プログラムは同時にやるわけですから、そういった部分も同時にやるのに慣れていかないといけないのかなと。品川区も多分、そういった考え方をしっかり持って事業を進めてほしいと求めましたので、何か一言あったら。","respondent":"鈴木文化観光課長","answer":"今年度も限られた部分では連携を想定はしているのですが、ご指摘のような、区内全域が観光の対象だよということで進めていければと考えています。これはしっかりと役割分担を見きわめた上で…","id":"exchange-020"},{"speaker":"中塚委員","kind":"質問","question":"では、いいですか。１点伺いたいのですけれども、今のお話も聞いて、最近、大井町でイベントがすごく多いのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-021"},{"speaker":"中塚委員","kind":"質問","question":"鎌倉パスタの前ですか。〔「いつも宣伝カーがとまっているところ」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"中塚委員","kind":"質問","question":"これは偶然なのか、それとも何か区の狙いがあるのか、そこを伺いたいと思ったのです。何か大井町の気運づくりというのでしょうか、それとも単なる偶然なのか、区の問題意識を伺いたいと思います。","respondent":"鈴木文化観光課長","answer":"それ以外のものは、地域のＮＰＯ法人だとか商店街で実施をされている事業が多いと聞いております。ただ、どうしても広いスペースで、多くの方が集まるには適しているということで、あそこの使用が多いのではないかと考えております。","id":"exchange-023"},{"speaker":"中塚委員","kind":"質問","question":"現状はそうだと思うのですけれども、それが、広町の暫定利用を見通したイベントが今増えているのか、品川の観光事業もそれぞれかかわってくるとは思うのですけれども、その辺の気運づくりという位置づけは区にあるのか、観光だったり、それについて、現状とともに見通しを伺いたい。","respondent":"鈴木文化観光課長","answer":"そこの広町、今後どういうふうに活用するかというのは検討中だということは聞いておりますので、事業を中央通りで実施しているものではございません。先ほど申し上げましたように、多くの人を集められて露店等も出しやすいということで…","id":"exchange-024"},{"speaker":"藤原委員","kind":"質問","question":"２点お伺いしますけれども、観光フェアを開催する日時ですが、なぜこの日にしたのでしょうか。その辺についてお伺いします。","respondent":"鈴木文化観光課長","answer":"ほぼ毎月のように予定をされているということで、当然近隣の方への事前の説明もして、この時期に設定したものです。今後は、先方の自治体の考え方もありますけれども、相互に交流することで相乗効果が出るような場合があれば、ぜひ連携したいと考えております。","id":"exchange-025"},{"speaker":"藤原委員","kind":"質問","question":"よく夏とかやるのは、うちわとかに協賛会社などのＰＲがあって、そういうのでいいのではないかなと思ったので、伺わせていただいたのです。企業の協賛をしていくことに、私も前向きな考えがあるもので、改めてその辺についてはいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"先ほどもお答えしましたように、確かに協賛の視点は、観光の事業を継続する上で重要だと考えております。それから民間の方がそれぞれ取り組むものというのが、その辺を見きわめた上で、取り入れるということは検討したいと考えております。","id":"exchange-026"},{"speaker":"こんの委員","kind":"質問","question":"周知方法のモノレールの車内広告等と、内訳も含めて、この事業の予算はどれぐらいになるのでしょうか。スタッフだとか、そういったことが予想されるのですけれども、予算の関係を説明を求めました。","respondent":"鈴木文化観光課長","answer":"それともう一つ大きなものが、各周知、１両編成のＰＲだとか、そのために使用する動画の作成ですね。そういうものに配分されるものです。","id":"exchange-027"},{"speaker":"こんの委員","kind":"質問","question":"これはそもそもご報告をするご予定がなかったのですか。大々的にこういうふうに、予算のあり方とか使い方というところはご報告があってもいいのかなと思ったのですけれども、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"大変申し訳ありません。きちんと説明できなければいけないのですが、こちらからきちんとご説明できるように、申し訳ございませんでした。","id":"exchange-028"},{"speaker":"伊藤副委員長","kind":"確認","question":"どうしても出てくると思いますソニーや、いろいろな区内の商品があるわけだから、そういうところと将来的には連携をしていく。そういう鉄道事業者やホテル事業者、マスコミとの関係はどうなのでしょうかということを、まず確認をお願いします。","respondent":"鈴木文化観光課長","answer":"ご指摘のように、地下鉄とか各鉄道事業者、それから宿泊施設、ホテル、関係する観光にかかわる機関・団体とは連携が必要だと認識をしております。全ての事業者の方に参加いただくブースの場所は確保できないのが１つと、連携をしてやっていくということで…","id":"exchange-029"},{"speaker":"伊藤副委員長","kind":"質問","question":"もちろん品川区がかかわっていくのだけれども、品川区主導でやっていると、どうしても限界がある。だから、これを１つのステップとして考えていいと思うのだけれども、将来的な構想はいかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"観光の振興、それから継続、維持に関しましては、委員ご指摘のとおりだと区も考えております。ご質問のとおり、今後は民間の皆さん主導で品川区内の観光を維持して継続していけるように、この辺を目指して進めていきたいと考えております。","id":"exchange-030"},{"speaker":"伊藤副委員長","kind":"意見","question":"もう話は伝わっているので、あまり重ねませんけれども、行政がある程度のスキームをつくって進めていく。円滑性もあるのだったら、いろいろな形で品川区の観光ＰＲをしていただくことのほうが成功すると私は思うので、ぜひとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-04","title":"イルミネーション事業","agenda":"イルミネーション事業","exchanges":[{"speaker":"田中委員","kind":"質問","question":"私はまぶしさを感じてしまって、色というのは決まってしまっているのですか。〔「ＬＥＤだから」と呼ぶ者あり〕。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-032"},{"speaker":"田中委員","kind":"質問","question":"と聞きますし、幾らＬＥＤといっても、そんな話にもなってきますので、明るさとかの調整とか、見る方たちの意見というのをもっと聞いてほしいかなと思うのですけれども、そこら辺はどうなっているのか尋ねました。","respondent":"鈴木文化観光課長","answer":"今年度、裏面にあります目黒川の桜は、以前から地域で実施しているとおり、ピンク色ですので、これは合わせた色を用意いたします。実は今年度予算では２カ所のイルミネーション事業を予定していたのですが、３回目を実施することにしたので、両方を使います。","id":"exchange-033"},{"speaker":"田中委員","kind":"質問","question":"目黒川沿いの今おっしゃったコンセプト、この色になった理由を教えていただけたら。","respondent":"鈴木文化観光課長","answer":"これは地域の団体で取り組んでいることなので、詳細までその検討について、この色で冬の桜ということでやっていると伺っております。","id":"exchange-034"},{"speaker":"田中委員","kind":"意見","question":"きらびやかな、五反田のイメージとピンクの色というので、ちょっと違うイメージを持たれる方とかが結構いるので。〔「逆に合っているかな」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"ピンクなイメージがちょっとあれなので、何かちょっと色が、さっきの白と交ざったりとか、何か工夫がされたらいいなと思うのですけれども、どうか尋ねました。","respondent":"鈴木文化観光課長","answer":"協賛も地域の企業が、環境に配慮するという趣旨から協賛金を出していただいたりということで、手づくりで地域自体で実施しているものです。今回、区で連携をして距離を延ばす場合も、こちらからいろいろ注文をつけて変えていただくというのは難しいかなと考えております。","id":"exchange-036"},{"speaker":"藤原委員","kind":"質問・要望","question":"「花子と太郎」、このごろ埋もれてしまっているではないですか。ちょっと延ばしてくれればいいわけですから、どういうふうにしているのか、ご意見をいただきたい。","respondent":"鈴木文化観光課長","answer":"昨年は道路課が実施して今年度から文化観光課の実施というふうにかわった経緯ですけれども、ご指摘のとおり、文化観光課に移ったものです。来年度以降、いろいろな範囲の変更だとか、場所自体のバリエーションを増やすことも考える中で検討していきたいと思います。","id":"exchange-037"},{"speaker":"こんの委員","kind":"質問","question":"大井町の最初の１０月２９日はそうだということだったのですが、五反田でいうならば１１月１８日からというのは、この設定の考え方。もう一つ、西小山もそうですけれども、その地域によって点灯の時期が違うのですが、その点灯時期の考え方を説明を求めました。","respondent":"鈴木文化観光課長","answer":"裏面、地域の皆さんが取り組んでいらっしゃる事業なので、そちらに合わせたというのが目黒川についての考え方です。２カ所で区が実施する分の資機材を使えるということで、集客ということを考えたので、ちょっと長目にこの時期に設定したということでございました。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問","question":"なぜこの時期からやって、始まりがなぜこの時期なのかという声だとか、わりとお声を受けたことがあったのです。考えたほうがいいのかなという感もするのですけれども、こういうご意見に対しては、どうお考えになりますか尋ねました。","respondent":"鈴木文化観光課長","answer":"実施時期につきましてですが、先ほど申し上げましたように、昨年度初めて大井町でやったということで、まだ１回しかやっていないのです。イルミネーションの成果が出るようにというのを考えておりますので、当然…","id":"exchange-039"},{"speaker":"こんの委員","kind":"質問・要望","question":"これからの後、続けていくにあたって、ぜひそのお声を聞きながらしていくということ。ここにかかわる方々、よりよいイルミネーションの効果を進めていくためにも、そういったお声もキャッチをしていただきたいなという要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"伊藤副委員長","kind":"質問","question":"なぜ武蔵小山でやらないのでしょうかという点と、阪急、みずほがあります。それぞれの企業の名前をＰＲするからイルミネーションに協力してくれとか、そういうのをしていったほうがいいのではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"区としても当初は候補地として考えていたのですが、まち並みに合わせて再度検討ということで、候補地としてはまだ維持をしております。徐々に区主導ではなくて、観光資源として民間で取り組んでいただけるようであれば、そちらへの移行というのは検討したいと考えております。","id":"exchange-041"},{"speaker":"伊藤副委員長","kind":"質問","question":"１点だけ。ああいう形でもいいから、やるのであれば、そういうふうにしていかないと、観光資源として上手くいかないと思うので、いかがか尋ねました。","respondent":"鈴木文化観光課長","answer":"考えていることもおありのようなので、相談をして進めたいなと思っていますが、もしくは記念になるようなもの。そういう工夫も含めて、単なる飾りつけ以外のイベントとして展開したいと考えております。","id":"exchange-042"},{"speaker":"伊藤副委員長","kind":"質問","question":"しかも観光資源にしたいわけですから、しながわ水族館をモデルにしたはまかぜ水族館で、ラバーズベンチとはっきり出ていました。ああいうものをいっぱい取り込んで、だからＮＨＫのドラマとコラボレーションしてもいいではないか尋ねました。","respondent":"鈴木文化観光課長","answer":"ご提案いただいたアイデアも含めて、幅広くやりまして、単なる木に装飾をつけるだけではない、観光的に魅力のあるイベントにしたいと考えております。","id":"exchange-043"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/294647?Template=document&Id=2764#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":53088,"voices":149}},{"id":"h28-20160928-7","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"厚生委員会","time":"午前１０時００分～午後 ２時２５分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を21件整理しています。","topics":[{"id":"topic-01","title":"平成２７年度指定管理者の管理に対するモニタリング・評価の結果","agenda":"平成２７年度指定管理者の管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"安藤副委員長","kind":"質問・要望","question":"５７ページなのですが、団体の方からも要望を出ていますし、ここはいかがでしょうか。６２ページの一番上のぷらーす、この内容も含めて、どういったふうに仕事の確保に対して品川区は改善されようとお考えなのかお伺いします。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"その話の中で、こちらの対応に対しての改善が必要とされた原因等が食い違っていることがあれば、この総括シートをつくり上げているところです。指定管理者の実施状況ヒアリングを行っておりまして… これからもそういうふうに個々のご利用者を理解していただくような説明に努めていければと考えています。そうした取り組みをすることで、あるいは…","id":"exchange-001"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"最終的に現場でサービスを担っていらっしゃる福祉労働者の方々の賃金や待遇や離職率等がどのようになっているかというのは把握されているのでしょう…私は把握すべきだと思うのですけれども、いかがか尋ねました。","respondent":"中山障害者福祉課長、永尾高齢者福祉課長、川島健康課長","answer":"そして、幅広く障害の理解をし、できるだけそれぞれの施設で特徴を持ちながら対応できるのが一番かなと考えています。とは言っても… ご質問のございました３３ページの大起エンゼルヘルプのところで対応方針等記載がありますけれども、そうすると、やはりそれが悪循環になりまして。… 利用料金収入という制度、こちら、全て指定管理者のほうに収入が入っていくというような仕組みになっています。まさに利用料金…","id":"exchange-002"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"ですから、改善をしていただく必要があると思うのですけれども、よろしくお願いします。これは、私の要望ですが、最後に、ちょっと考えをお伺いします。","respondent":"永尾高齢者福祉課長","answer":"ですので、なかなかこれ以上深くというのが難しいかなというふうに考えているところです。この施設１つだけを見ても、そこまで全ての報告をするというのは、ちょっと難しいかなというふうに感じているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つは、よくなったのか、変わらなかったのかというところも１つ教えてほしいと求めました。去年のときも私伺っていて、離職率１２.５％というのは、そこら辺のところが現場のところではどうなっているのか教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"それで、これはやはり将来に備えてというところの改正というふうに認識をしています。検討しているところですので、国も、また区のほうでも重要視しているというふうに考えております。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"一人ひとりの働く方にとっては、処遇が改善された、賃金が平成２７年度から上がったということになっているのかをお聞かせほしいと求めました。１０ページの一番下のところの、この業務体制の見直しというのは、具体的にどういうことなのか教えてほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"軽度の方から、本当に要支援の重い方まで動きが様々ですので、この数字だけをもって簡単には言い切れないのかなというふうに思っています。当然、どのようにその人に対応したケアができるかという意味において…","id":"exchange-005"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そうすると、賃上げになったとしたら、この加算によってどれぐらいの賃上げになったのかということも教えてほしいと求めました。それから経営がしっかりと成り立つ介護報酬というのは、一番の基本になると思いますので、そこら辺のところもお聞かせほしいと求めました。","respondent":"永尾高齢者福祉課長","answer":"全国の社会福祉法人で、頭を悩ませているところで、そういう勉強会みたいなものも各地で開かれているところです。全てが絡み合っているところの中で、健全な社会福祉法人の経営ができるように、区のほうでも会計諸表等も参考にしながら一緒に考えているところです。","id":"exchange-006"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"企業の平均の賃金よりも１０万円安いというふうに言われているわけですから、質の担保ができるように、ぜひともしてほしいと求めました。重度化して、この必要な設備更新というのは、具体的にどういうものなのか教えてほしいと求めました。","respondent":"永尾高齢者福祉課長、中山障害者福祉課長","answer":"経営に関しては、１つの独立した法人ですので、経営努力というのはとても大事だというふうに考えております。区のほうで経営支援費の積算等につきましては、前年度の決算の実績に稼動成績とかも勘案しながら… 区内にはもう１つ、８床あるベッドを活用しながら、こういった緊急対応に備えています。地域生活支援拠点についての構築に向けて話し合いも行っているのですが、ショートステイも考え方として緊急対応の考え方として、研究をしています。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私はぜひそういう形で現場で働く介護の方々が本当に平均よりもこんなに低い賃金体系をしっかりと改善できるための対策を区のほうからもしっかりと求…処遇改善交付金という形でぜひ求めてほしいと求めましたけれども、そのことだけお願いしたいと思います。","respondent":"永尾高齢者福祉課長","answer":"介護職員の方の給料が安定的に上がらないこともあって、その後、加算という制度に変わってきているという経過があります。現在考えているさらなる処遇改善加算というところを、どういうような枠組みになるのか区としても重視していきたいというふうに考えております。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"国がその気になればできるわけですから、ぜひそれを恒久的な制度として、区から国へ求めていっていただきたい。社会保障を充実をさせるという、その立場でぜひ税金の使い方も変えていくという、発想の転換をしていただきたいということで、要望で終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"},{"speaker":"浅野委員","kind":"質問・要望","question":"ちょっと教えていただきたいのと、１９ページの三徳会のほうですけれども、こちらのほうは空きをつくらずということでうまくいった例だと思うのです。ですから、そしてまた利用者サービスの向上に努めてほしいと求めましたが、いかがか尋ねました。","respondent":"永尾高齢者福祉課長","answer":"大変判断が難しいところになるというのが１つと、施設の見学会とか、なるべく間なく入るような努力をしているというふうに聞いております。ご本人の認知症の度合いで、本人もそこが自分のおうちだという認識がなかなかできないというところで…","id":"exchange-010"},{"speaker":"浅野委員","kind":"意見","question":"ありがとうございました。ぜひともこれからも続けていっていただいて、品川区の介護、さらに充実するように取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"１つ先ほど聞けなかったことが、今回の平成２７年度の改正のもう１つの特徴が、それによってどう変わったのかを教えてほしいと求めました。いきいき活動支援も、そしてまた、デイサービスがどのように総合事業で変化してきているのかということについてお聞かせほしいと求めました。","respondent":"松山高齢者地域支援課長","answer":"ほぼ利用者とそのご家族の方に丁寧に説明をしていただきまして、円滑に移行しているというのが総括シートの中でかなり見られる点です。いきいき活動支援プログラムにつきましても、各サービスセンターでそれぞれ特性を生かして実施し、ここに出ているところは全て実施しています。","id":"exchange-012"}]},{"id":"topic-02","title":"平成２９年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用）」の入居待機者の募集","agenda":"平成２９年度分「高齢者住宅（建設型・借上型の単身用）」および「区立大井林町高齢者住宅（単身用）」の入居待機者の募集","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"平成２６年度でどれくらい、平成２７年度は、現在までに何人入れているのかということを教えてほしいと求めました。回覧板なり、何かもうちょっと周知を工夫していただきたいなと思っているのですが、その点もお聞かせいただけたらと思います。","respondent":"松山高齢者地域支援課長","answer":"２点目の周知方法ですけれども、あるいは区のホームページ、そのほかに民生委員協議会のほうできちんと周知をしております。窓口に民生委員と一緒に来られる方も比較的多うありますので、やはり民生委員をキーに、こちらのほうは周知の工夫を図っております。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"２０人登録すると言っても、こんなに申し込みがくるかどうかわからない、そういう捉え方でいいのか。実際に困っているのに、どこかでまた工夫ができないかというのは、引き続いてご検討ほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"安藤副委員長","kind":"質問","question":"２点お伺したいのですが、これはなぜ申請者数が減ってしまっているとお考えなのか、いかがでしょうかというのが１点です。大体割合といいますか、あと劣悪な住宅にお住まいの方、その割合みたいなものがわかれば説明を求めました。","respondent":"松山高齢者地域支援課長","answer":"そのうち立ち退きの理由の方が大体４分の１ぐらいです。それから、劣悪な環境によるものが４分の１ということで、比較的最近では、高い家賃を安くしたいという方が増えている傾向にあります。","id":"exchange-015"},{"speaker":"安藤副委員長","kind":"質問・要望","question":"ですから、こういった住宅はやはり求められているのだと、今の高齢者の方の生活状況が悪化していますので、私は必要だと思います。その確認をさせていただきたいのと、そしてやはりこれはもう少しニーズに合わせて増やしていく必要があると思うのですけれども、いかがか尋ねました。","respondent":"松山高齢者地域支援課長","answer":"例えば資料Ｎｏ.１をおめくりいただきますと、八潮わかくさ荘であれば、条例で制定している家賃につきましては８万５,０００円と設けてあります。３万５,０００円というのは、前年の所得に応じて減額という料金を決めてあります。","id":"exchange-016"}]},{"id":"topic-03","title":"その他","agenda":"その他","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"そして、南品川四丁目の特養ホームの建設に向けての動きがどういう状況になっているのかというところを、ぜひ教えていただきたいというのが１点です。２点目も一緒に質問してもよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"同じく鈴木真澄議員のほうから質問がありました防災対策についての質問のところで、福祉避難所についての質問があったと思うのですけれども、要援護者に対しての対応というふうなところでお聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"財務省のホームページからの情報だけで、この社会福祉法人がどういう社会福祉法人なのかというのも、わかれば教えてほしいと求めました。その当時からもう何年も前から、要援護者の災害時の支援のマニュアルをつくるべきではないかということもずっと求めてきていたのですけれども、今。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう状況はわからないので、防災課のほうでは、この問題を防災課だけではつくれないわけですね。そこがどちらかというと中心になっていくという、そういうことであると思いますので、そういう観点からお聞きしております。","respondent":"渡部委員長、大串福祉計画課長、永尾高齢者福祉課長","answer":"改めて申し上げますが、その辺だけは私の言っていることをご理解いただいた上で進めしますので、よろしくお願いいたします。ご答弁お願いいたします。 先ほどご答弁申し上げたとおりです。国と法人のほうで進めている交渉、この推移の状況次第という形にはなってまいりますけれども… この間、防災の対策ということで、防災課が中心になって検討を行っているところです。障害者関係、また保健センター等も一堂に会して…","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"どういう社会福祉法人かというのもわかったら教えていただきたいと思うのですけれども、そういう情報もわかったら教えてほしいと求めました。ぜひ進めてほしいと求めましたので、ぜひ進めていただきたいということで、それは要望しておきます。","respondent":"大串福祉計画課長","answer":"これまで整備を進めてきた中では、区が土地を取得もしくは建物を建てて指定管理といった形が一般的だったかとは思います。こういったものに合わせていただくというのが最大の条件になってまいりますので、そういった形で協議を行ってまいりたいというふうに考えています。","id":"exchange-021"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/540863?Template=document&Id=3458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":66013,"voices":83}},{"id":"h28-20160928-8","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"建設委員会","time":"午前１０時００分～午後 ０時３１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を41件整理しています。","topics":[{"id":"topic-01","title":"大崎駅周辺のエリアマネジメント活動状況","agenda":"大崎駅周辺のエリアマネジメント活動状況","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"品川区はこの大崎駅周辺まち運営協議会に連携・支援ということなのですが、具体的にどのように関わって、何か会議体とかに一緒に参加したりだとか一緒に進めているということなのか尋ねました。","respondent":"稲田都市開発課長","answer":"４つの大きなものがございまして、それが個々にやるのではなくて、大きく大崎駅周辺のまちづくりをやっていこうということで設立されたものです。いろいろなイベント等があるときには、区の全体的なバランスとか区のほうの考えもある程度要望しながらやっていくという状況です。","id":"exchange-001"},{"speaker":"石田（ち）委員","kind":"質問","question":"この間は副区長が会長だったということですけれども、顧問になるということはどのような変化があるのか伺います。","respondent":"稲田都市開発課長","answer":"品川区も協力・連携しながらやっていこうという中におきましては、顧問に残していただいて、今後も協力・連携していこうというものです。","id":"exchange-002"},{"speaker":"西本委員","kind":"質問","question":"１番の主催のところですが、大崎エリアマネジメントという一般社団法人がいて、この関係性はどうなっているのでしょうか。３番の大崎駅西口バスターミナルの件ですが、どのぐらいの時間で行けることになるのでしょうかということと、目標値というのは。","respondent":"稲田都市開発課長","answer":"継続的に発展するためのまちの体制をつくっていこうではないかと位置付けられておりまして、大崎駅周辺まち運営協議会、事務局等で動いている。戦略的、継続的に発展させる体制をつくるというものに基づきまして、品川区とは連携しながらやるという形において進めているところで…","id":"exchange-003"},{"speaker":"西本委員","kind":"質問","question":"気になったのは、大崎・五反田タウンマネジメントと大崎エリアマネジメントの、この両者の関係性はどうなっているのでしょうか。大崎周辺で、いろいろなことをやっていかなくてはいけないと思うのですけれども、お互いの協力体制はどうなっているのか尋ねました。","respondent":"稲田都市開発課長","answer":"この両者の一般社団法人のお互いの関係ですが、これはまちづくり、再開発を進める中で、その経緯によって発生してきた法人団体なのです。そういうところにおきましては、６０ｈａを盛り上げようというところにおきましては、今その辺でいろいろと話し合いは持ったりという状況で…","id":"exchange-004"},{"speaker":"西本委員","kind":"質問","question":"わかりました、これは２法人。その２法人が入っているということは、今後の考え方と、あとそれに対する区の進め方は何かありますか尋ねました。","respondent":"稲田都市開発課長","answer":"この両者ですけれども、そのように意見が違ったり対立したりとか、そういうのは現在特にございません。ただ、やはり今後は一つになって大崎駅周辺のまちを盛り上げていくという方向がいいのではないかと考えながら、今やっているところです。","id":"exchange-005"},{"speaker":"西本委員","kind":"質問・要望","question":"大きく組織化するという方向もあるかと思うのですけれども、もうちょっと広い意味での大崎駅周辺の開発についてを考えていただきたいと思っています。広い地域なので、やはり広い視点での進め方をしていけるのは区側の役割なのかなと思いますので、そういう形で整理いただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-006"},{"speaker":"塚本委員","kind":"確認","question":"ここに出ている絵で大体もういっぱいいっぱいということなのか、まだまだ路線拡張の余力があるのかというところを確認したい。当然行き先からの折り返しもあると、基本的には往復であるということなのですか、説明を求めました。","respondent":"稲田都市開発課長","answer":"この大崎駅西口バスターミナルですが、バスが停まるところが４バースあります。最後、来ないものもありますけれども、基本的には大体往復ということです。","id":"exchange-007"},{"speaker":"塚本委員","kind":"質問","question":"すみません、もうちょっと細かく聞きたいのですけれども、成田国際空港と羽田空港、飛行機場とつなぐこの２つの路線は、成田国際空港から大崎駅、羽田空港から大崎駅という便もあるということでよろしいか尋ねました。","respondent":"稲田都市開発課長","answer":"はい、そのとおりです。","id":"exchange-008"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、宿泊施設が今後すごくニーズとしてこの地域に出てくる、今でもあることはあると思いますけれども。現状の問題はどの程度出ているか、また将来的にそれに対して何かするような考えがあるかというところをちょっとお伺いしたいのですけれども。","respondent":"稲田都市開発課長","answer":"周辺のホテルなのですけれども、現在大崎駅西口と東口に１つずつあるという状況です。この地域内におきますと、民間でのホテル建設が動き始めているという状況がありますので、そういう状況を見ながらということにはなるかと思います。","id":"exchange-009"},{"speaker":"塚本委員","kind":"質問","question":"宿泊も含めた新たなエリアマネジメント、大崎駅周辺の発展に向けての見解、あるいは品川区としての目標といったものをお伺いしたいと思います。","respondent":"稲田都市開発課長","answer":"それだけ整備すればいいというものではなくて、地域全体がそれらのお客さん等をうまく取り込んでいけるというのは非常に重要なことだと考えています。商業のほうとの連携、観光のほうとの連携というのは進めて、また今後の考え方も統一しながらやっていきたいと考えています。","id":"exchange-010"},{"speaker":"鈴木（真）委員","kind":"意見","question":"ここと今後どのように関連を持っていくのか。この中に入ってくるのか、それともあそこは別ということなのか、そこら辺はどのように考えていますかとの意見を述べました。","respondent":"稲田都市開発課長","answer":"ただ、大崎に接する連携する地域ですので、今後も大崎地区と連携しながら、隣接するというところでまちづくりはやっていかなければいけない。大井町から大崎に抜ける重要な都市軸のところにありますので、そういう面でもまちづくりとしては…","id":"exchange-011"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それともう一カ所、これから開発していくのが、どちらかというと山手通り寄りのラーメン屋さんのあるほう、あそこも今後開発が入ってきますよね。そこもやはり同じように考えればいいのかなということですが、大崎駅西口駅前地区との意見を述べました。","respondent":"稲田都市開発課長","answer":"大崎駅前西口地区というところで準備組合もできて、今、地域の方は勉強を進めているところです。隣接して、このまちづくりの中では主要なところですので、今後地域内には含めていこうかという考えはあります。","id":"exchange-012"},{"speaker":"鈴木（真）委員","kind":"質問","question":"大崎の発展のためにやっていくのでしたら、なるべくそういうのは一体になってやっていったほうがいいのではないかということで、質問しました。それからこれ、やはり一番問題になるのは、今後の補助１６３号の道路の問題だと思いますので、そこも含めて今後の検討を。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"}]},{"id":"topic-02","title":"土砂災害警戒区域等の指定に向けた東京都における斜面調査","agenda":"土砂災害警戒区域等の指定に向けた東京都における斜面調査","exchanges":[{"speaker":"石田（ち）委員","kind":"質問","question":"この土砂災害警戒区域の指定を受けるというのは、どういうことになるのかをお聞きしたいのですけれども。それは東京都と一緒にやっていたことなのか、区独自で調査してきたことなのかという、これまでの話も伺いたいと思います。","respondent":"鈴木建築課長","answer":"東京都が行う調査というのが５ｍ以上でございまして、２ｍ以上を対象にして水防活動、５ｍ以上のものも区の調査では行っております。ただ、行う調査の内容が目視で、東京都のほうは機械計測でやる関係もあって、内容が違うこともあって、２ｍ以上と、そのやり方がちょっと違うで…","id":"exchange-014"},{"speaker":"石田（ち）委員","kind":"質問","question":"そうすると、２ヶ年かけて調査されるということですけれども、大体の範囲というのは、区内で土砂災害が懸念される大体の場所はあると思うのですが、何カ所あるのか説明を求めました。","respondent":"鈴木建築課長","answer":"まだ調査の実施前ですので、非常に東京都もそういうことを心配しておりまして、詳細な情報は得ておりません。昔からの地形、池田山ですとか島津山ですとか、ああいったところに非常に集中しているというところは聞いてあります。","id":"exchange-015"},{"speaker":"石田（ち）委員","kind":"質問","question":"土砂災害に関連してですけれども、避難準備情報がこの間２回くらい出されたのですか。それで避難所も開設されたのですけれども、何人ぐらい来たのかを教えていただけませんか尋ねました。","respondent":"鈴木建築課長","answer":"本年度で言いますと、避難準備情報を一度出しまして、そのときは避難者の方は１人もいらっしゃらなかったです。それと、過去のものがすぐ手元になくて、今年度で言いますと一度避難準備情報を出して、避難者の方はいらっしゃらなかったということです。","id":"exchange-016"},{"speaker":"石田（ち）委員","kind":"質問","question":"避難所も開設しているのに１人も来ないというところでは、やはり知らない人が多いと受けとめるのですが、防災無線は流していないと思うのですけれども、これはなぜ流さないのかを伺いたいです。","respondent":"鈴木建築課長","answer":"今６カ所、その６カ所周辺の方々には基本的には毎年５月、対面できた方には個別のご案内を毎回しております。説明会も二度行っておりまして、限定した方への積極的な周知を行っている関係上、防災無線では行っていないです。","id":"exchange-017"},{"speaker":"石田（ち）委員","kind":"質問","question":"防災無線は限定した箇所に流すということはできないのでしょうか。毎年のように起きるかもしれないことですので、そういった工夫などを考えられていないか尋ねました。","respondent":"鈴木建築課長、古巻防災課長","answer":"概ね２００世帯の方々なのですけれども、あと今後検討していくことになろうかと思いますけれども、今後検討していきたいと考えております。 防災行政無線の関係についてお答えいたします。基本的にはメールですとか、そういった形での登録をお願いしているということで、防災行政無線については放送していないという形で進めております。","id":"exchange-018"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"限定した地域の方ということなのですけれども、やはり家にいないかもしれない、いてもなかなかそれに気づかないというのが一番、知らないということが一番怖いことだと思うので、何らかの形で工夫されていくということなのですけれども、知らせていく工夫をさらに進めてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、周りとの連携も進むと思うので、あそこは危険な地域だというのをみんなで共有していくというのも別にいいと思うのですけれども。そういった形で防災行政無線は流せるのではないかと私は思うのですけれども、いかがか尋ねました。","respondent":"鈴木建築課長","answer":"場合によっては避難所まで行けない方は、そういった事前の取り決めもしていただければ、さらに地域一丸となった対応ができるかなです。大雨のときに周辺の方も含めて情報を流すというのは非常に混乱が生じるというところで、限定した情報伝達が必要かです。","id":"exchange-020"},{"speaker":"塚本委員","kind":"確認","question":"限定的とは言っても、ほとんど区の半分とか４分の１とかぐらいに聞こえてしまうような、その確認です。数字が正確に出ればいいのですけれども、大体でいいですが、どれぐらいの世帯がその対象になっているのかというところをお伺いしたいと思います。","respondent":"古巻防災課長、鈴木建築課長","answer":"周囲にかなり聞こえてしまうということは、防災行政無線放送の特性上やむを得ないところということで、そういった機能です。 対象の地域の世帯数と人数ですが、１９２世帯３２１人というところが対象です。","id":"exchange-021"},{"speaker":"塚本委員","kind":"質問","question":"避難する間に水にさらわれてしまうなどということがあるわけですから、それぐらいのレベルだと思うので、それはよろしくお願いしたいと思います。一緒になってやることはあるのか、全く東京都にお任せで報告だけを待つという形でやるのか尋ねました。","respondent":"鈴木建築課長","answer":"調査結果の報告を区が待つという形です。区としてはその調査対象がある町会長、町会の方には、区のほうで調査の内容について説明をしていく予定にはなってあります。","id":"exchange-022"},{"speaker":"塚本委員","kind":"質問","question":"そのようなことがあったりするのではないかと思うのですけれども、そういう部分の東京都との連携というのは考えられているか。もし考えられていないのであれば、できることはやったほうがいいのではないかと思いますけれども、どうか尋ねました。","respondent":"鈴木建築課長","answer":"打合せを開始したところでございまして、今後調査を進めていくにあたって、そういったところで連携をとっていく。当然ながら地域に入っていくにあたって町会長への説明の際、そういった場所を確認しながら、先ほどまさに委員の方におっしゃっていただいたように。","id":"exchange-023"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"そういうリストからやったのかどうかわからないですが、ある方から、直接区以外のところから電話がかかってきたという方がいらっしゃると。非常に今後において心配もあるので、リストに関しては十分な注意を払っていただきたいということで、これは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"西本委員","kind":"質問・要望","question":"品川区であるとそれの倍ぐらいのところが、危険かどうかわからないですけれども、そういう箇所があるという認識でいいのでしょうかという確認です。それらの補償を含めてどう考えているのですかということは、東京都が中心にやるということで、ただやはり品川区民の皆さんのものなので。","respondent":"鈴木建築課長","answer":"品川区でも２ｍ以上の調査をやっておりますので、ご理解いただいて、ご協力いただくように考えております。書ける、書けないところはあると思うのですけれども、東京都のほうとしっかり内容について最終なものを詰めていきたいと考えています。","id":"exchange-025"},{"speaker":"西本委員","kind":"質問・要望","question":"調査が入る、法律で決まったからやるよみたいなことではなくて、結局は皆さんのためなのですよということじゃないですか。ですから、家屋の問題もあるでしょうし、それから何か災害があったときの協力体制というのを当然ながらつくっていかなければいけない。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-026"},{"speaker":"筒井委員","kind":"質問","question":"東京都の調査と品川区の調査、それぞれ目的が災害防止にあると思うのですけれども、東京都は５ｍ以上、品川区は２ｍ以上としたその根拠というのは何か尋ねました。","respondent":"鈴木建築課長","answer":"東京都の５ｍというのは法律に基づく高さです。品川区の２ｍというのは、建築基準法で言う工作物の安全の確認が必要な高さが２ｍでございまして、その違いです。","id":"exchange-027"},{"speaker":"筒井委員","kind":"意見","question":"東京都の５ｍ以上というのは法律で決まっているということなのですけれども、その法律のことですけれども、５ｍ以上とした具体的な根拠、５ｍ以上だからより危険だという法律の立法趣旨がわかれば、お教えくださいとの意見を述べました。","respondent":"鈴木建築課長","answer":"なかなか高さで５ｍ以上が崩れて、５ｍ未満が崩れないという、５ｍという線が引かれたのではないかと考えています。","id":"exchange-028"}]},{"id":"topic-03","title":"舟運社会実験の実施","agenda":"舟運社会実験の実施","exchanges":[{"speaker":"高橋（伸）委員","kind":"質問","question":"たしか８月ですか、そういうものを含めた啓発も当然やっていくかと思うのですけれども、その辺のところを説明を求めました。","respondent":"和田河川下水道課長","answer":"こちらのライトアップの計画ですけれども、当然品川区としても現在、委託の中でデザイナーを入れてどのような照明が効果的かということは検証中です。ただ、事業者の意見も聞きながら場所等、それから期間も含めて検討してまいりたい考えております。","id":"exchange-029"},{"speaker":"西本委員","kind":"提案","question":"その上にある１０月１日から平成２９年１月中旬（約３ヶ月）というのは何をする期間ですか、よくわからないのです。実際に提案された方がやれる時期というのは多分２ヶ月後、３ヶ月後という形になるとすると、この広報はどうするのか尋ねました。","respondent":"和田河川下水道課長","answer":"実施期間の話ですけれども、説明の内容にもありましたが、考えているところです。社会実験実施開始が１０月１日ですので、１週間しか猶予がありませんので、１０月１日にできないというのは当然考えられることです。","id":"exchange-030"},{"speaker":"西本委員","kind":"質問","question":"３ヶ月半でホームページだ、３ヶ月、そういうところがあるのかないのか。もう少し区切りとして延ばしたほうが、その辺は東京都とかの関係もあるのかなと思うのですが、どういう形になっているのか尋ねました。","respondent":"和田河川下水道課長","answer":"それから、まずはこの３ヶ月半を目途に、一回その課題の整理をしようかなというところで考えたところです。課題があればあったで３ヶ月半で見直すということもできますので、１月中旬に１回区切りを設けて整理させていただきたいというのが我々の考えです。","id":"exchange-031"},{"speaker":"西本委員","kind":"意見","question":"３ヶ月半というのは短過ぎるのではないか、やはり半年ぐらいやっている中で、その周知の部分も含めてどのような反応があるのだろうか。これは意見という形で、いろいろと走っていただきながら検証していただければいいかなと思いますとの意見を述べました。","respondent":"和田河川下水道課長","answer":"宣伝効果とか宣伝のあり方というのは、今先行して実施している東京都でも非常に苦心しているところです。そういう意味で、委員のご指摘も踏まえて、宣伝効果というポイントも含めてこの社会実験の中で検証できればと思っています。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"とりあえずまず３ヶ月半行うというところで、今お伺いしましたけれども、言えるところまでお伺いしたい。週に１遍なのか、月に１遍ぐらいこうやって十分に入念にいろいろな準備してやるか、具体的な船の走らせ方をお伺いしたいと思います。","respondent":"和田河川下水道課長","answer":"事前に声をかけている事業者は、区内事業者含めまして６社とか７社ぐらいには声をかけていて、前向きに検討するという回答は得られているところです。三回は、そのイメージに合致するかどうか、この辺を事業者と詳細に詰めていきたいと考えています。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"そうすると、乗っていただくということも当然あるのだけれども、なかなかスタートはそうそう広がらない部分もあるかもしれませんけれども。そういうところにおいては、皆さんが後から関心が高まっていくというのはこの１月中旬以降の課題としてもよくて、その辺はいかがか尋ねました。","respondent":"和田河川下水道課長","answer":"あの桟橋が閉鎖されていたということも含めて、この事業者の企画とか提案の中でうまいものが出てくればいいのかなと考えています。質問の答えになっているかわからないですが、質問の答えとしましては、まずは事業者の目線に立ってやっていきたいと考えております。","id":"exchange-034"},{"speaker":"筒井委員","kind":"質問","question":"もう一つは、一応理論上際限なく事業者は応募してくるということになるので、事業者数の限度というか制限というのはあるのでしょうか。この２点、お教えください。","respondent":"和田河川下水道課長","answer":"これも地元の方との調整が入りまして、今現在は区内の舟運事業者に限定をして募集させていただこうかと考えているというか、募集しております。当然際限なく応募を受け付けまして活性化できればなと考えていますが、多くても五、六事業者に留まるのかなとは想定をしています。","id":"exchange-035"},{"speaker":"筒井委員","kind":"質問・要望","question":"もうちょっとＰＲしていけば、結果的に区民の方の周知にもつながると思いますので、ぜひもう少し多めの広報をお願いしたいと考えております。今回の水辺利活用、舟運社会実験というのを行っていただきたいと思うのですけれども、区としてのお考えはいかがか尋ねました。","respondent":"和田河川下水道課長","answer":"区内イベントや観光施策との連携ということで、五反田で行われるイベントとの連携というのは必須だと我々も考えてありますので、事業者と調整していきたいと考えているところです。","id":"exchange-036"}]},{"id":"topic-04","title":"感震ブレーカー設置推進事業","agenda":"感震ブレーカー設置推進事業","exchanges":[{"speaker":"塚本委員","kind":"確認","question":"１点確認なのですが、新築住宅への取付けもここに１件ということになっていますけれども、これはいわゆるハウスメーカーが新たに新築をつくって売り出すというタイプのものは、助成対象にならないのか尋ねました。","respondent":"古巻防災課長","answer":"こちらの助成の対象に関しましては、今でも対象の建物に対して居住する方の申請という形になりますので、そういった形ですと助成対象にはならないです。","id":"exchange-037"},{"speaker":"西本委員","kind":"質問","question":"それとも１００件以上になった場合、１０件もそうですけれども、そこら辺はどうお考えになられているのでしょうかという点です。ちょっと細かいのですけれども、もう少し啓発できるような方法はとれないものかと思うのですが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"感震ブレーカー設置事業は本年度からの事業ということで、現時点ではまだ補助の対象地区について広げるということでは、検討を進めていない状況です。一定、申込開始時にかなり集中したということで、普及を阻害しないような形で柔軟に対応していきたいとは考えているところです。","id":"exchange-038"},{"speaker":"西本委員","kind":"質問・要望","question":"問い合わせ先が何も書いていないじゃないですか。せっかくいいものを安く買えるのですから、ぜひご検討願いたいと思いますが、いかがか尋ねました。","respondent":"古巻防災課長","answer":"まず木密の重点地域を優先的に普及を図っていきたいという区の考え方に基づきまして、それぞれいろいろ検討を進めてまいりたいと考えています。今後の進捗の状況を見据えまして検討を進めて、普及の促進の阻害にならないような形で進めてまいりたいと考えているところです。","id":"exchange-039"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"私も入らないかなと思っていたら入っていたので、すみません、この感震ブレーカーの部分はいつ頃掲載されたのか伺いたいと思います。は、福祉の部門と連携をして設置をしてくれるというふうにはならないかなと思うのですけれども、その辺はいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"}]},{"id":"topic-05","title":"その他","agenda":"その他","exchanges":[{"speaker":"西本委員","kind":"質問","question":"今の報告は、昨日のチャイルドシート装着車の対応について今検討して、その検討したものを後ほど報告するということでよろしいのか尋ねました。","respondent":"桑波田交通安全担当課長","answer":"今後のやり方を検討しておりますので、今後の第４回定例会を目指しまして、ご審議をいただくように考えております。","id":"exchange-041"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/862367?Template=document&Id=4184#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":44282,"voices":129}},{"id":"h28-20160928-9","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"文教委員会","time":"午前１０時００分～午後 ２時４０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を84件整理しています。","topics":[{"id":"topic-01","title":"「居住実態が把握できない児童」に関する調査の結果","agenda":"「居住実態が把握できない児童」に関する調査の結果","exchanges":[{"speaker":"あべ委員","kind":"確認","question":"８件全員の居住が確認できて、実態把握ができてよかったと思います。それで、この８件の中で、特に出国以外の件数の中で、福祉的な課題といいますか、状況があるようなケースもあったのかどうか説明を求めました。","respondent":"高山子ども育成課長","answer":"幸いにして、今回、調査の対象となりました方々の中に、そういった、いわゆる支援を要するようなケースというのはなかったということで確認しています。","id":"exchange-001"},{"speaker":"あべ委員","kind":"質問","question":"とすると、この方々の居住実態が把握できないままであったというのは、いろいろな行政サービスにつながっていなかったからということなのでしょうか。どういう背景があるとお考えなのか。","respondent":"高山子ども育成課長","answer":"これが転じて何か支援を要するにもかかわらず支援の手が差し伸べられていないというような状況がないように、幸いにして支援を要する方々がこの中に含まれていなかったというのは、そういった状況からというふうに考えております。","id":"exchange-002"},{"speaker":"のだて委員","kind":"確認","question":"区内で最終的には確認できた方が日本国籍の方で１件、どうやって防いでいくかというのはなかなか難しいとは思いますけれども、こういったことを生み出さない対策などは考えていらっしゃるのか伺いたいと思います。","respondent":"高山子ども育成課長","answer":"それが一つ、必ずしも支援の手が行き届いていなかったという、そのような緊急事態ということでもないと考えております。例えば、そういったところにお顔を出していただくなどということで、子育て支援などとあわせて進めていければと考えております。","id":"exchange-003"},{"speaker":"新妻委員","kind":"確認","question":"今回、８名が確認できたということで、一旦調査は終わるということでしょうか。これから以降、こういう未確認の方というのは出ないようにしていただいていると思いますけれども、確認をさせてください。","respondent":"高山子ども育成課長","answer":"今回は厚生労働省が実施します全国規模の調査ということで、６月１日時点の定点観測のようなものです。昨年度中にこういった形で対象となったお子さんというのは４６名ということでございまして、通年の取り組みとして進めているところです。","id":"exchange-004"}]},{"id":"topic-02","title":"小・中学生の生活状況調査の結果","agenda":"小・中学生の生活状況調査の結果","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"いつごろの見通しであるかということを教えていただきたいのが１点です。合計の回答率が４３％ということで、それに基づいた施策展開に活かしていただきたいと思うのですが、いかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"回答率の４０％台ということについては、目標としては６割ということを考えていたのですが、郵送であると４０％台というのが大体多かったです。いろいろな、これだけで判断するというのは危険だという考えがございまして…","id":"exchange-005"},{"speaker":"鈴木（博）委員","kind":"質問","question":"回答率はどうなのかと思ったのですが、もう少し質問項目をまとめると、最初に率直に感じたのです。は質問内容なのですけれども、１ページの問１５の、「家事専業」と「仕事をしていない」というのはどう違うのか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"仕事をしていないというのは、仕事ができる状況にないというイメージで設問をつくったところです。家事専業は家事だけです。","id":"exchange-006"},{"speaker":"鈴木（博）委員","kind":"質問","question":"課長の思いはわかったのですけれども、率直に、この質問を読んで、そこまでわかるのですか。税金がどうのこうのと書いてあるから、もうちょっと雑駁でも、そういう意見にはどういうふうにお答えしますか。","respondent":"廣田子ども家庭支援課長","answer":"設問についてですが、「仕事をしていない」は、したいけどしていないという、無職というイメージなのですけれども、これについて、いろいろなほかの自治体でやっている調査票も参考にさせていただきまして、いろいろ練ったのですけれども、また今後、答えやすいように……。","id":"exchange-007"},{"speaker":"鈴木（博）委員","kind":"質問","question":"最後に。この細かいデータをもとにして、保護者の方の書きやすさというのは考えたほうがいいのではないかという気がしたのですが、これはいかがか尋ねました。","respondent":"廣田子ども家庭支援課長","answer":"いろいろな収入とほかの項目と突合するときには、細かいほうが状況がわかるのではないかというところで、細かくとったところです。","id":"exchange-008"},{"speaker":"新妻委員","kind":"質問・要望","question":"朝食べていなくて学校の給食だけで、もし今、２０番の数をお答えいただけるようであれば教えていただけますでしょうか。品川区が相対的な貧困の年収は何万円以下とお考えなのかというところを教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"２年生で「毎日食べる」という回答が９６.３％、「全く食べない」と回答したのが１名で０.９％です。年収イコールで見られるというふうには考えておりませんで、今、研究しているところです。","id":"exchange-009"},{"speaker":"新妻委員","kind":"質問・要望","question":"ありがとうございました。またこの精査をしっかりとしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"のだて委員","kind":"確認","question":"設問、これは大綱ができたというところで、国のほうでつくってやっていると思うのですが、この設問というのは区独自のものになるのでしょうか。全国的に統一されているもの等もあるのか伺いたいと思います。","respondent":"廣田子ども家庭支援課長","answer":"低所得の家庭だけに支援をするというわけではありませんで、課題を抽出して、ニーズに合わせて必要なサービスをしていくという考え方です。優先的に先に検討していくという話で、考え方としては全児童の、子どもの未来のためのプロジェクトということでやっています。","id":"exchange-011"},{"speaker":"のだて委員","kind":"質問","question":"それで、設問の中で、１４番と１６番の帰宅時間についても、今わかる範囲で教えてほしいと求めました。世帯全員の年収が２００万円以下の子が４％あるというところで、これはもし共働きで２００万円以下であると、教えてほしいと求めました。","respondent":"廣田子ども家庭支援課長","answer":"帰宅時間については、父親の最も多い回答ですと、２年生の父親ですと、２０時から２２時が２６.６％、２２時以降が２３％となっています。２年生のお母さんですと、最も多い回答が１８時までで３９.６％いまして、仕事をしていませんという回答が３１.７％ありますので。","id":"exchange-012"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"１つは、その後、事業につなげていっていただきたいということが１つです。これは子ども家庭支援課長にお聞きするのはあれなのかもしれませんが、現実の学校等の関係からすると、その点が１つ。","respondent":"廣田子ども家庭支援課長","answer":"今後検討を進めていく上で必要な分については分科会的にメンバーを、教育総合支援センターであるとか、密度濃く検討していくというような話で。その他は、あとは養育費の受給状況であるとかというのは、戸籍であるとか、各部署から集めて、行政で持っているものをかき集めるです。","id":"exchange-013"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"ぜひそちらとも連携をとっていただきたいということです。ぜひクロス、それを中でできるというのは非常に分析には効果的なことだと思うので、ぜひ有効な報告と事業につなげていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"}]},{"id":"topic-03","title":"平成２７年度指定管理者による管理に対するモニタリング・評価の結果","agenda":"平成２７年度指定管理者による管理に対するモニタリング・評価の結果","exchanges":[{"speaker":"鈴木（博）委員","kind":"質問","question":"具体的にどういうことなのかご説明をお願いしたいことが１つと、それからあと、事案というのがありますか。それについてお伺いします。","respondent":"木村品川図書館長","answer":"１点目の蔵書管理につきましてですけれども、例えば、それはちょっと待ってというようなところでの調整が必要になってくる場面が多々あります。実際にファクスの誤送信であるとか、そういう事例がございましたので、そういう意味では再発防止のために繰り返し周知を行っているで…","id":"exchange-015"},{"speaker":"鈴木（博）委員","kind":"意見","question":"ヒヤリ・ハットというのは、要するに、ファクスなんかで個人情報が漏れてしまうとかというニュアンスも含まれていると。例えば、図書館の中で誰かが暴れるとか、けがをするとか、そういうようなことをイメージしていたのですけれども、その部分ではないとの意見を述べました。","respondent":"木村品川図書館長","answer":"どちらかといいますと、こちらは個人情報保護、情報保護の関係が主になっております。","id":"exchange-016"},{"speaker":"あべ委員","kind":"質問","question":"家庭あんしんセンターについて伺いたいのですが、子育て短期支援事業の利用料が平成２５年度から平成２７年度で見て、半減している。と同時に、評価の視点別コメントというところには短期支援事業についてはまるで言及がないのですが、それがなぜかということも説明を求めました。","respondent":"高山子ども育成課長","answer":"ご自宅で一日過ごしたいといった親の考え方、意識が変わってきたというようなところもあろうかと思います。真に必要とされている方がその利用につながっていただければということで、特段、コメントとしてはそちらのほうに記載させていただいていないです。","id":"exchange-017"},{"speaker":"あべ委員","kind":"質問","question":"５５０万円から２８０万円という、ほぼ３００万円落ちているのが、そういう構造の事業になっているということなのでしょうか。これから先はこのシートだけではなくて、別の機会でもずっといろいろ伺っていきたいと思いますけれども、いかがお考えでいらっしゃいますか。","respondent":"高山子ども育成課長","answer":"先ほど２つ理由として申し上げましたところの１つは、たくさんの日数を利用される方の利用が、転居等に伴ってなくなったというのも一つの要素だと。特に利用に当たって厳しい規制を設けているわけではありませんので、特段の問題はないというふうには考えております。","id":"exchange-018"},{"speaker":"あべ委員","kind":"質問","question":"委託料が十分であるかどうかということも踏まえた上での、つまり、処遇改善が不十分であるという意味なのでしょうか。どういう区のスタンスなのかということを説明を求めました。","respondent":"高山子ども育成課長、佐藤保育施設調整担当課長","answer":"先ほどお尋ねの前段の部分、ショートステイ、トワイライトステイにつきましては、利用を希望する３日前までに申し込むという形で、直前の利用にも応えられる形で受け付けのほうをしています。 まず１点目として、常に清掃であったり点検を定期的に見直して、少しでもお金を節約しようということで書かせていただいたところです。","id":"exchange-019"},{"speaker":"あべ委員","kind":"質問","question":"ぷりすくーる西五反田、直接このシートとかかわらないかもしれないのですけれども、今、社会福祉法人化を進めているという話もありますが、組織の形態が大きく変わるということで、もし進捗などわかれば、教えてほしいと求めました。","respondent":"佐藤保育施設調整担当課長","answer":"ですので、今の段階では白紙に戻ってはいるのですが、現在、運営している代表理事もそういう法人化は進めたいという話は聞いております。そういった状況です。","id":"exchange-020"},{"speaker":"あべ委員","kind":"質問","question":"次に、３ページのＢグループのほうなのですけれども、「大井図書館は苦情・トラブルの多い館であるが」という部分があります。これは何か大井図書館としての個別の事情があっての、もし何か大井図書館、こういうことがあるのであれば説明を求めました。","respondent":"木村品川図書館長","answer":"利用者の方で、対応がなかなか難しい方が複数名いらっしゃるです。それから対応その他は、集中まではいかないのですけれども、ちょっと多いという形の認識です。","id":"exchange-021"},{"speaker":"あべ委員","kind":"質問","question":"サポートスタッフ、応援を頼めるような仕組みをつくられたかと思うのですが、そのあたりは機能されているということでよろしいでしょうか。あまり運営メンバーに負担がかかるようでは、図書館とは違った仕事が増えてくると思いますので、その辺はうまく連携がとれているのか尋ねました。","respondent":"木村品川図書館長","answer":"各グループ内に危機管理スタッフという者がおりまして、警察ＯＢ、その方が巡回して、何かあれば飛んでいくというような形をとって対応しております。","id":"exchange-022"},{"speaker":"のだて委員","kind":"質問","question":"管理運営委託料が毎年少しずつ上がっているのですが、利用者があまり変わらないのに増えていくというのはどういうことなのかお聞きしたいと思います。総括のところで、これはどういった形で改定して、労働環境を改善されたのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長","answer":"２点目は、就業規程の改定の内容ですが、給与体系をより細分化して、経験や職務をより反映できるようにしたと。時短勤務について取得期間の延長や対象者の拡大を図ったということで、改善をしたというふうに聞いております。","id":"exchange-023"},{"speaker":"のだて委員","kind":"質問","question":"再委託というのはどういった業務を再委託されているのでしょうかということと、基盤強化というのは、何が問題があることを意味しているのでしょうか。伺います。","respondent":"佐藤保育施設調整担当課長","answer":"１点目の再委託の関係ですが、これは清掃とか消火設備の点検業者というふうに聞いております。バックアップ体制がなかなか厳しいところもありますので、法人自体の体制を強化するといいますか、そういった意味で書いてあるところです。","id":"exchange-024"},{"speaker":"のだて委員","kind":"確認","question":"Ａグループの荏原図書館のグループだけ副館長がいるということが書いてあったのですが、ここだけ副館長がいるというのはなぜか伺いたいと思います。Ｃグループのところで、裏面に、突発的な事情というのは何か運営の問題であったのかどうか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長、木村品川図書館長","answer":"基本的には法人化をするのはＮＰＯ法人自体の考えで行いますので、できる支援はしますけれども、その辺は第一義的には法人が行うです。それらも含めて基盤強化を図っていったほうがいいという意味で書いております。 その他区との協議の中で不在にする部分が多い部分がありますので、そういう意味で、統括館長のほかに副館長を設置しています。何か運営に支障がというような部分よりも…","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぷりすくーる西五反田のところで、それ以外のところの基盤強化というのがどういうものになるのか、具体的に教えてほしいと求めました。図書館のほうでは、統括館長の補佐役ということで副館長が一緒にまとめるという役割だということでいいのか、確認です。","respondent":"佐藤保育施設調整担当課長、木村品川図書館長","answer":"基盤強化の具体的な中身です。人員等にそんなに余裕があるわけでもありませんので、事務方の処理とか、さまざまな面でより質を上げて基盤を強化するという意味で書いております。 Ａグループに関しましては、指定管理全体、３グループの統括というような意味もありますので、そういう意味ではご認識どおりです。補佐役です。","id":"exchange-026"},{"speaker":"飯沼委員","kind":"質問・要望","question":"給食の調理業務は委託になっていないのかどうか、そこを聞きたいのが１点と、職員の体制をお伺いしたいのです。勤務の勤続年数、賃金についてもぜひ教えていただきたいのと、それもあわせてお伺いします。","respondent":"佐藤保育施設調整担当課長、廣田子ども家庭支援課長","answer":"給食の件ですが、給食の件に関しては、年度当初、直営ということで動きはあったのですけれども、７月１日から委託されております。法人自体の運営の中の話だと考えております。 家庭あんしんセンターの職員体制ですが、全部細かく必要でしょうか。","id":"exchange-027"},{"speaker":"飯沼委員","kind":"質問・要望","question":"わかったら教えていただきたいのが１点です。意見を聞いていくという図書館協議会の設置についてのお考えを聞かせてほしいと求めました。","respondent":"齋藤子ども未来部長","answer":"モニタリングシステムの報告につきましては、区で統一的な考えで行っておりますので、申し入れの点につきましては企画部にお伝えいたします。","id":"exchange-028"},{"speaker":"飯沼委員","kind":"質問・要望","question":"図書館協議会については、全国的には６割ぐらいが設置をされていると聞いております。住民が参加をしていくというシステムはとても大事なことであると思うので、ぜひこのことを検討していただきたいのですが、いかがか尋ねました。","respondent":"木村品川図書館長","answer":"今のご要望につきましても、利用者の方からのお声もいただいているところではあります。ただし、先ほどの繰り返しになってしまいますけれども、現時点では設置という形については考えておりません。","id":"exchange-029"}]},{"id":"topic-04","title":"東五反田児童センター改修工事に伴うオアシスルーム等の一時休館","agenda":"東五反田児童センター改修工事に伴うオアシスルーム等の一時休館","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"例えば、代替施設などはお考えなのか、休館期間中の対応についても教えてください。張替工事の張替えに使うグルーというのですか、接着剤なのですか、そういったことへの配慮はどうなっているか説明を求めました。","respondent":"竹田保育課長","answer":"工事業者にそうした申し入れをするとともに、工事期間のほうは余裕を持って設定しておりますので、十分管理して事故のないようにしたいと思います。所定の検査もして、ＶＯＣ検査を行いまして、安全を確保してまいります。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問・要望","question":"１カ月休むわけですので、教えてください。なぜなら、やはり求められているという事もあるので、その辺を説明を求めました。","respondent":"竹田保育課長","answer":"４月以降は毎月２０人から４０人ぐらい間で新規の登録者の数が増えておりまして、４月から８月までは１５５人の方に登録していただいております。それから月々の利用者数ですが、おおむね一月当たり１３０人から１５０人ぐらいの方にご利用いただいているところです。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"近くで利用できないとお困りになる方もあるのかなと思うのですが、その辺の、代替で一番近いのが西五反田のぷりすくーるのところですか。あまりあいているところはないかもしれないけれども、そういった状況もご案内をしていただけたらと思うのですが、いかがか尋ねました。","respondent":"竹田保育課長","answer":"近所等を探しますと、７月から北品川第二保育園のほうで新規にオープンしている施設もありますので、そういったことも含めて、近隣の施設のご紹介をしていきたいと考えております。","id":"exchange-032"}]},{"id":"topic-05","title":"旧荏原第四中学校跡地の活用計画（案）","agenda":"旧荏原第四中学校跡地の活用計画（案）","exchanges":[{"speaker":"あべ委員","kind":"質問・要望","question":"基本的に保育園ということと、それから非常に求められている改築のための一時移転仮設園舎等々、基本的な方向を今回初めて伺いました。とりあえず改修で５年ということで、５年を過ぎても利用するということなのか、５年後のその後のイメージについても説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問・要望","question":"具体的なことはまた今後も時間があると思いますが、基本的に小さい子どもたちの施設であるという状況、環境に持っていってほしいと求めました。こちらは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-034"},{"speaker":"のだて委員","kind":"確認","question":"今回、イメージがちょっとわからないのですが、これはこの２つの園があるというようなイメージになるのでしょうか。これはどういった、部活動に使うという話ですけれども、校舎とか体育館なども使っていくということなのか伺いたいと思います。","respondent":"佐藤保育施設調整担当課長、品川庶務課長","answer":"１点目の保育園の施設のイメージですが、それも含めて今後検討をしてまいります。３点目のどこの保育園が改築の対象になるかというご質問だと思うのですが、老朽化や改修経過等を見ながら今後検討をしてまいります。 戸越台の改修の件ですが、資料に書いてありますとおり、部活動等で活用することを現在のところは考えております。改修工事、必要に応じて利用できるところがないかどうかも検討しながら進めていきたいと考えております。","id":"exchange-035"},{"speaker":"のだて委員","kind":"質問","question":"戸越台のところで、利用できるところも検討してという、ちょっとよくわからなかったのですが、校舎とかも使っていくということでしょうか。おそらく２園になっていくのかなとは思っているのですが、どういった形で考えているのか、もう少し具体的にあれば教えてほしいと求めました。","respondent":"品川庶務課長、佐藤保育施設調整担当課長","answer":"校舎の利用ですが、現在のところ、部活動等でグラウンド、体育館の利用は想定はしております。その辺についてはいろいろ工事のスケジュールも検討しながら、利用について考えていきたいと、このように思っております。 園舎の関係ですが、財政負担と園運営の状況等も考えながら、今後検討してまいります。","id":"exchange-036"}]},{"id":"topic-06","title":"認可保育園の新規開設","agenda":"認可保育園の新規開設","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"園庭はないのかどうか、そこを確認させていただきたいのと、そのときの代替公園というのはどこになるのか伺いたいと思います。人材確保、この間出てきたときには毎回聞かせていただいておりますが、保育士の確保がしっかりできるのか、今どういう状況なのか伺いたいと思います。","respondent":"大澤待機児童対策担当課長","answer":"青物横丁えほん保育園につきましては、鮫洲公園まで４００ｍほどありますが、そちらが代替遊戯場ということになります。早い時期から保育士確保には努めているということで、事業者のほうから希望者にいろいろ説明をして、保育士を集めているというふうに聞いております。","id":"exchange-037"},{"speaker":"のだて委員","kind":"確認","question":"そうしましたら、一応４月開園に向けて順調に進んでいるという認識でいいかという確認です。先ほど代替公園、西大井広場と鮫洲公園ということでしたけれども、ほかにもそこを代替公園としている保育園が何園ぐらいあるのか説明を求めました。","respondent":"大澤待機児童対策担当課長","answer":"近隣への説明も済ませまして、工事も１１月から開始ということで、順調に計画どおり進んでいるところです。申しわけございません。","id":"exchange-038"},{"speaker":"新妻委員","kind":"意見","question":"新規もこれから検討いただいているということですが、今回、石井保育園が隣の土地を買って、拡大をしていただいたという報告がありました。新規ではなくてこういう形で石井保育園のように、定員を拡大できる可能性のある園というのは…","respondent":"大澤待機児童対策担当課長","answer":"既存の園で現在のところ定員拡大の予定のある園はございません。","id":"exchange-039"},{"speaker":"あべ委員","kind":"質問","question":"石井保育園の定員なのですけれども、２７人増、これ、年齢構成を説明を求めました。","respondent":"大澤待機児童対策担当課長","answer":"石井保育園、改定後の定員です。０歳児１２名、１歳児１５名、２歳児１８名、３、４、５歳児がそれぞれ２０名ずつです。","id":"exchange-040"},{"speaker":"あべ委員","kind":"意見","question":"やはり１歳の需要が非常に大きいというのと、アンジェリカさんなんかは６人から１２人ということで、今後もその点を配慮して開設をしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"飯沼委員","kind":"質問・要望","question":"やはり民設民営で民間に来てほしいという姿勢からすると、だから、地域のこのアンバランスを何とかしていただきたいと思うのが１点です。わかったら教えていただきたいのと、質問で９月１日の申し込みを伺いましたが、今後について考えていらっしゃるのかお聞かせいただきたい。","respondent":"大澤待機児童対策担当課長、齋藤子ども未来部長","answer":"今、荏原地域から民間事業者からの提案もありますので、そちら、何とか実現できるように私どもも進めてまいりたいと考えています。就学前人口が増えておりますので、こちら… ただ、問題なのは、若干周囲の方のご理解を得にくいという点もあります。現場もお見せしたいとか、そういう努力も重ねてまいりますので、お見守りをお願いしたいと考えています。","id":"exchange-042"},{"speaker":"飯沼委員","kind":"質問・要望","question":"なので、ぜひ小山台住宅の跡地とか都有地とかもしっかり視野に入れて、荏原地域の待機児問題の解消に努めていただきたいと思うのが１点です。よかったね、とにかく来年度の保育園の３倍ぐらいつくっても、この辺の認識はどのようにされているのかも最後にお伺いいたします。","respondent":"大澤待機児童対策担当課長","answer":"平成２９年度の待機児童のほうですけれども、子ども・子育て計画上の見込み数で考えますと、そのような数字にはなってあります。希望される方が平成２８年度４４.８％ということで、できるだけ計画前倒しで開設したいと考えておりますので、何とか進めていきたいと思います。","id":"exchange-043"},{"speaker":"飯沼委員","kind":"質問・要望","question":"子育て、子ども未来部のところの努力だけでは、とても解決しないところであると思っています。この方針では解決をしないというところで、区立保育園もつくるといった姿勢に立ち返ってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"あべ委員","kind":"質問","question":"短時間保育、少しは品川もつくっていますけれども、非常に少ないです。総合的に見て、新規保育園開設だけではない子育て支援策、区としてはどのように考えていらっしゃいますか尋ねました。","respondent":"齋藤子ども未来部長","answer":"ライフワークバランスということで、介護休暇の延長ですとか、さまざまな施策ということで考えております。ちょっと長くなってしまうとあれなのですけれども……。","id":"exchange-045"},{"speaker":"あべ委員","kind":"質問・要望","question":"別の機会で構いません。いろいろ区としても考えていらっしゃると思いますが、ぜひそういった中期的、長期的なことも考えながら施策を進めていただければと要望いたします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"}]},{"id":"topic-07","title":"学校改築事業の進捗","agenda":"学校改築事業の進捗","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"こちらもグラウンドの広さを知りたいというのが１点と、あと、近隣の方との関係でどうなのかというのを１つ教えてください。後地小学校は平成２８年９月から基本設計に着手ということなのですけれども、図面がいつ出てくるのか説明を求めました。","respondent":"篠田学校計画担当課長","answer":"現行は約４,２００m2ですので、広さは増す予定です。出てくるのは今年度末という形で、それに引き続きまして、来年度実施設計をしていくという形になってまいります。","id":"exchange-047"},{"speaker":"飯沼委員","kind":"質問","question":"１点なのですが、城南幼稚園のところなのですけれども、施設が一体になるということで、基本的に中身的には特に変わりないのか、その点だけ説明を求めました。","respondent":"篠田学校計画担当課長","answer":"城南幼稚園につきましては、現在およそ５００m2あるのですけれども、面積的には、新しくなりますと、６００m2程度となる予定です。小学校と一緒に一体的に使えるということで、逆に言うと、小学校の施設とあわせて今後使えるような形でも考えているところです。","id":"exchange-048"},{"speaker":"のだて委員","kind":"質問・要望","question":"図面からはよくわからなかったので、確認させてほしいと求めました。学年の割り振りというのでしょうか、どういった感じになっているのかというのが決まっていれば教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"この図面でいきますと、多目的ホールというのが１階のところにありまして、こちらが小学校の施設です。その上の３階の教室が３年生から６年生までの場所となっておりまして、３クラスごとに学年ごとにまとまりが図れるような形での設計となっております。","id":"exchange-049"},{"speaker":"新妻委員","kind":"質問","question":"芳水小学校と城南小学校、それぞれ特別支援学級ができるということで、この図面上ですと、どこにそのクラスが配置されるか、もう決まっていましたら教えていただけますか。","respondent":"篠田学校計画担当課長","answer":"一応、配置につきましては、クラスルーム、それぞれの教室が配置されている関係で、どこでも使えるような形で、特別支援も普通の学級と同じようにして使えるような形に設計をしておりますので、この中でどこを使うかというのは、学級編制によることになります。","id":"exchange-050"},{"speaker":"あべ委員","kind":"質問","question":"今のところなのですけれども、これは決まっていないけれども、両校とも特別支援教室は教室とある中の１つを使っていくという理解でよろしいか尋ねました。","respondent":"篠田学校計画担当課長","answer":"そのとおりです。この中の教室が並んでいる中で、普通教室とあわせて特別支援教室を確保していただいているという形になります。","id":"exchange-051"},{"speaker":"あべ委員","kind":"質問","question":"芳水小学校が長いのは、プールを別にする関係とか、敷地の関係なのでしょうか。それぞれの学校の特徴といったらあれですけれども、工事の面での特徴を教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"１つはこちら、こちらのほうの工事が相当時間がかかるというのが１点と、今の子どもたちを移動させるということがあります。今あるグラウンドのほうに建てるということですので、その分の工期が短くなっているということで、工事をすることになります。","id":"exchange-052"},{"speaker":"あべ委員","kind":"質問・要望","question":"パースで見ると木造風な感じになっているかと思うのですが、平面図ではこれは一体の校舎のように、これはどういう感じになっているのでしょうか。ちょっと教えていただきたい。","respondent":"篠田学校計画担当課長","answer":"隣のお寺だったり、通りが石だたみということがありますので、それに合わせた形で落ちつきのあるデザインということになっております。現在、区の景観審議会等と打ち合わせをしながら、詳細の部分を詰めているような格好です。","id":"exchange-053"},{"speaker":"あべ委員","kind":"質問・要望","question":"この間、いろいろ調整もされているようなのですけれども、基本的には内装に木質の材料をできるだけ使ってほしいと考えています。そういった意味で、そういった心理的な面も考慮して材料その他を選んでいただきたいと思っているのですが、いかがお考えか尋ねました。","respondent":"篠田学校計画担当課長","answer":"こちらのほう、今、学校のほうも、新しく建てるもの、例えば、最近ですと、御殿山小学校なんか木造の部材をふんだんに入れていると思います。城南小学校はただいま実施設計中ですので、できるだけそういった形での取り組みを進めていければというふうに考えております。","id":"exchange-054"},{"speaker":"高橋（し）委員","kind":"確認","question":"それとも、何らかの、私、この図からわからないのですが、児童がどのような形でこういうプール指導はどこでということになるのでしょうか。３クラスでもという声も少し地域の方からはあるのですが、もちろんこの計画は３クラスでいくのですけれども、その点についていかがか尋ねました。","respondent":"篠田学校計画担当課長、竹田保育課長","answer":"今回、これ以降はかわりのプールというのは設置できない見込みですので、ほかの体育の授業でなるべく対応いただくような形になります。基本的に人口推計上は１８クラスあれば足りる予定ではあるのですけれども、これにつきましては… 幼稚園のプール遊びですが、近隣の保育園、幼稚園のほうの協力を得ながら、できるだけプール遊びのほうを確保していきたいと考えております。","id":"exchange-055"},{"speaker":"高橋（し）委員","kind":"意見","question":"この間、今の４年生ぐらいだとずっとできない形になるかもしれませんから、説明のほうをしていただけるとありがたいと思います。１クラスが増えた場合のことも、そういった配慮がなされているということで、承知いたしましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-056"},{"speaker":"あべ委員","kind":"質問","question":"近隣の学校に何度か行ってプールの授業をやったというようなことがあったので、今回もきっとそうするのかと思っていたのですけれども、城南小学校の場合はそういったことは全く想定はされていないのか尋ねました。","respondent":"篠田学校計画担当課長","answer":"申しわけございませんでした。近隣の学校と連携をしまして、例えば、シーズン中何回かお借りしたいとかという形での対応というのは今後もあり得ると思います。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問・要望","question":"できるだけの工夫をしていただいて、やはり夏にプールがずっとないというのは、子どもたちにとっては厳しいと思いますので、ぜひ工夫してほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"}]},{"id":"topic-08","title":"品川区学事制度審議会の設置","agenda":"品川区学事制度審議会の設置","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"学事制度審議会、先ほど学事制度の中で幾つか挙げていらっしゃいましたけれども、もう少し具体的な内容を説明いただけますでしょうか。これは傍聴とか公開されるのかというところも教えてほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"学区域の問題なんかですと、かなり事例として挙げてご検討いただくといっても、今回はこの会議については非公開という形で考えております。細かい部分、ポイントを絞りまして、要点について随時公開をしていきたいというふうに考えております。","id":"exchange-059"},{"speaker":"のだて委員","kind":"質問・要望","question":"要点についてご報告していくということですので、随時ご報告してほしいと求めました。会派としてはかねてから統廃合をやめるべきだということと、廃止も含めて検討してほしいと求めましたが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"こちらの選択制等の意義に関しましては、こちらの審議会の中で審議をしていただくという形になりますので、その審議を見守りたいと考えております。","id":"exchange-060"},{"speaker":"新妻委員","kind":"確認","question":"確認します。この内容ですとか、また、要点を文教委員会には報告をいただけますか尋ねました。","respondent":"篠田学校計画担当課長","answer":"開催時期、タイミングにもよりますけれども、必要に応じましてこちらの委員会にもご報告をさせていただきたいというふうに考えています。","id":"exchange-061"},{"speaker":"あべ委員","kind":"質問","question":"学事制度審議会の所掌事項としては内容がいろいろ書いてあるわけですけれども、実際に来月から始まる学事制度審議会の主なテーマというのは、ここに書かれている学区域、学校選択制、学校規模・学校配置等というのが今回の主なテーマと理解してよろしいか尋ねました。","respondent":"篠田学校計画担当課長","answer":"基本的にはここに書かれているものが中心的なテーマになろうかと考えております。ただ、審議の推移等によりまして、この結果、さまざまな課題が議題に上ってくることもあり得るというふうには考えております。","id":"exchange-062"},{"speaker":"あべ委員","kind":"質問","question":"委員の方、これはどういった方かというのもこれ以上のことは現段階では公開されないということでしょうか。参考人として呼んだり、あるいはその他の学識経験の方から意見を聞いたりというような、外部との協議をされるかどうか。","respondent":"篠田学校計画担当課長","answer":"品川の教育に精通されているような方にお願いをしているというような形ですので、正式に委嘱が済みましたらご報告をさせていただきたいと思います。こちらも審議の進捗によりまして…","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"審議期間が１年弱で、月１回程度の開催で、どう数えてもそうなります。かなり事務局主導でないと中間答申まで至らないのではないかというふうに思っているのですが、その運営についてはどのようにお考えか尋ねました。","respondent":"篠田学校計画担当課長","answer":"確かに課題としましては、かなり盛りだくさんな状況になっているのは事実です。あくまで課題に沿った形で各委員、自由闊達な意見をいただきながらまとめていけたらというふうに考えております。","id":"exchange-064"},{"speaker":"あべ委員","kind":"質問・要望","question":"ぜひ広範な意見を聞きながら、短期的ではない結論を出していただきたいと。これはもう希望ではありますけれども、ぜひ十分な審議を尽くしてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-065"},{"speaker":"飯沼委員","kind":"質問・要望","question":"最後にパブリックコメントを求めるだけではなく、区民参加、住民参加の姿勢をぜひ持っていただきたい。手挙げ方式というか、関心の強い方の出席も求めたほうがより活発な議論ができるのではないかと考えていますが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"先ほどもちょっとご説明したとおり、あるいは委員のできるだけ自由闊達な意見を求めるといった観点から、今回は非公開とするものです。それから、パブリックコメントを丁寧に実施することによって、幅広く区民の方のご意見を聞く機会として捉えていきたいと考えています。","id":"exchange-066"},{"speaker":"飯沼委員","kind":"質問・要望","question":"こういう思いでこんな中身に今なっていますがどうですかという、今一番求められているので、ここはぜひ再考してほしいと求めました。区民を拒否するものなので、そこは絶対改善が必要であると思いますが、いかがか尋ねました。","respondent":"篠田学校計画担当課長","answer":"パブリックコメントを丁寧にすることによって、それで区民の声をできるだけお聞きするという機会として捉えていきたいと考えております。公開制ですけれども、今回の審議会につきましては非公開という形で進めさせていただきたいと考えております。","id":"exchange-067"},{"speaker":"飯沼委員","kind":"質問・要望","question":"ぜひ区民のかわりにお仕事をしているという意味では、私はブラックボックスというか、見えないところをつくってはいけないと思うのです。ぜひ公開、ガラス張りの区政、教育行政も求めていきたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-068"},{"speaker":"沢田副委員長","kind":"質問・要望","question":"学事制度審議会はかねてからうちの会派からも求めてまいりましたので、歓迎いたします。そういったところのお考えをお聞かせいただきたいのと、全体というよりも、そのあたりのお考えを説明を求めました。","respondent":"篠田学校計画担当課長","answer":"学区域の問題ですとか、そういった問題にもかかってくると思っていますので、そういったことも審査しながら進めていっていただければと考えています。審議の答申が出るまではなかなか外に対してご説明する機会は難しいとは思うのですけれども、町会長会議ですとか…","id":"exchange-069"},{"speaker":"高橋（し）委員","kind":"質問・要望","question":"学習指導要領の新しい形がどうなるか、平成３０年度というのは非常に再スタートいいますか、新たなスタートの年になると思うのです。学区域、そういうところに向けてという位置づけで少しどのようなお考えというか、位置づけについてご説明ほしいと求めました。","respondent":"篠田学校計画担当課長","answer":"平成３０年３月に答申が出たとして、例えば、実際に制度として変わっていくのは先になってくるだろうと考えております。ただ、中身によりますので、いずれにしても４月から全て変わりますということではないというように考えているところです。","id":"exchange-070"}]},{"id":"topic-09","title":"所管質問","agenda":"所管質問","exchanges":[{"speaker":"のだて委員","kind":"質問","question":"「のびのび育つしながわっ子」には３つの品川区が目指す子ども像などありますけれども、具体的に何が問題だったのか伺いたいと思います。区の責任がないとしている根拠、理由を伺います。","respondent":"竹田保育課長","answer":"理事長の配偶者である統括園長と実施してまいりましたが、本年５月ごろより、相互の認識にずれが生じたものです。保育の実施を委託することは継続的な信頼関係が不可欠であることから、相手方法人は、法人の保育方針に基づき園運営を行うという立場を堅持し。","id":"exchange-071"},{"speaker":"のだて委員","kind":"質問・要望","question":"具体的なことを聞いているので、一つ一つの理由では解除できないということですから、さまざま理由があったと思うのです。事業者交代という事態になってしまったということであれば、それはやはり責任があるのではないかと思いますけれども、いかがか尋ねました。","respondent":"竹田保育課長","answer":"そのような保育の方針に相違が生じましたので、今回の結論となったものです。選定時にはしかるべき選定の手続を適切に行っておりますので、その後に判明したことですので、区の責任はないと考えております。","id":"exchange-072"},{"speaker":"のだて委員","kind":"質問・要望","question":"いかがでしょうかということで、区の責任のほうですけれども、６月に不正発覚して、契約した後なので責任がないというのはおかしいと思うのです。その後変わっていくということを見破れなかったということだと思いますけれども、その点で責任はないということなのか、伺いたいと思います。","respondent":"竹田保育課長","answer":"昨日の繰り返しになりますけれども、保育方針の違いというのは多岐にわたっておりますので、ここで一つ一つ全てをご説明することはできません。事業者の事務所に行って帳簿を調べるといったようなこともできませんので…","id":"exchange-073"},{"speaker":"飯沼委員","kind":"質問","question":"そう思っているのですか。今までの私……、発言許されていないから。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-074"},{"speaker":"飯沼委員","kind":"質問","question":"フォロー質問というのは、いつでもいろいろな疑問点があったら出せる状況にしていったほうがいいのではないかという意見交換もあった時期があります。のだて委員が質問をしましたけれども、それに対しては委員会全員で発言をしていくというスタンスだと私は思っています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-075"},{"speaker":"飯沼委員","kind":"質問","question":"その上で発展してお話し合いをしてもいいのではないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-076"},{"speaker":"飯沼委員","kind":"質問・要望","question":"区の説明で、今後再発防止が防げるのですか。原因究明の機会の役割、チェックをするということをどう考えていらっしゃるのか、ぜひ私はここの会場にいらっしゃる委員の皆さんにご意見を伺いたい。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-077"},{"speaker":"あべ委員","kind":"意見","question":"今後の５年間の園運営にとっては、それを実際に現実のものにするには、双方の合意というものが必要である。であれば、今区がとっている態度というのは、私はおのずから理解ができますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-078"},{"speaker":"飯沼委員","kind":"質問・要望","question":"どういった時期にどのような中身で検証されるというお考えなのか、そこの中身を１点聞かせていただきたいのと、この件に関していかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"民営化を実施する平成３３年度以降の公営・民営それぞれの運営費に対する国や都、区の負担割合等を比較、検証します。次に、民営化実施後に保護者を対象に保育に対する満足度調査を行うなど、保護者の意向や保護者から見た保育の質を検証したいと考えております。","id":"exchange-079"},{"speaker":"飯沼委員","kind":"質問","question":"２つ質問したのですが、後段のほうも今のお答えで含まれていたのでしょうか。ぜひ今回のひろまち保育園の公設民営の、言ってみたら民営化の第１号……。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-080"},{"speaker":"飯沼委員","kind":"質問","question":"今の答弁は、平成３３年度以降に実際に実施をされた段階で検証をしていくということなのですか。メンバーを、想定する範囲でお知らせください。","respondent":"佐藤保育施設調整担当課長","answer":"今から５年後になりますので、検討はしているものはありますけれども、お出しできるものはありません。５年後ですので、その時点で状況を見ながら検討して、詳細を決めたいと思います。","id":"exchange-081"},{"speaker":"飯沼委員","kind":"質問","question":"５年も先ということで、どなたが業務に携わるかもわからないのですけれども、そういった意味においては、５年後実施をして検証というよりも、今からやはりもうちょっと身近にある問題を検証されたほうがいいのではないかと思うのですが、いかがか尋ねました。","respondent":"佐藤保育施設調整担当課長","answer":"身近な課題といわれますと、待機児童対策とか、老朽化対策の問題かと思いますが、その辺に関しては区は全力で課題に取り組んでいる、調査、研究しております。","id":"exchange-082"}]},{"id":"topic-10","title":"行政視察","agenda":"行政視察","exchanges":[{"speaker":"あべ委員","kind":"意見","question":"やはりある意味、正反対のベースを持ったところでの公立保育園の民間委託なのだということを押さえて視察ができればいいかなというふうに思いました。そこが欠落すると、ただこういう民間移管というだけでは誤解して考えられる可能性もあると思いましたので…","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-083"},{"speaker":"鈴木（博）委員","kind":"質問","question":"本会議でも質問したのですけれども、どういう形でやるかというのは、足すのは無理ですよね。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-084"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/462438?Template=document&Id=4896#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":65371,"voices":285}},{"id":"h28-20160928-5","meetingId":"h28-cm09","date":"2016年9月28日","dateIso":"2016-09-28","committee":"総務委員会","time":"午前１０時００分～午後 １時５０分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を54件整理しています。","topics":[{"id":"topic-01","title":"第８５号議案 平成２８年度品川区一般会計補正予算","agenda":"第８５号議案 平成２８年度品川区一般会計補正予算","exchanges":[{"speaker":"須貝委員","kind":"質問","question":"歳入のほうですか、そして都支出金のほうでやはり２分の１ということは、区のほうでは一切お金を出さなくて済むのでしょうか。そういうところはどうなのか尋ねました。","respondent":"秋山財政課長","answer":"それから、しながわ１１０番ですけれども、所管のほうからは１１０番の設置ということで話は聞いておりますけれども。それから、ＬＥＤですけれども、中小企業対策費の中の商店街活性化事業という中でＬＥＤ装飾灯等の事業をやっておりますので、それでつけているです。","id":"exchange-001"},{"speaker":"須貝委員","kind":"質問・要望","question":"その辺も今後、区のほうとしてもっと１１０番設置助成ですか、こういうところも私は拡大していく必要があるのではないかなと思います。意見だけにしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"南委員","kind":"質問","question":"しながわ１１０番に関連してなのですけれども、今回１５ページについては高齢者福祉施設、それを伺っておきたいなと思っています。そういった人的配置も含めて改善が望まれるなと私は思っているのですけれども、その辺についての見解がどうなのかを伺っておきたいと思います。","respondent":"秋山財政課長","answer":"しながわ１１０番の通報システムですけれども、相模原の事件を受けて入所施設ということで考えさせていただいたというところがまず１点目あります。学校１１０番につきましては、幼稚園等につけていますので、今後も必要に応じて検討はしていくということで考えてあります。","id":"exchange-003"},{"speaker":"南委員","kind":"質問","question":"今後の考え方、今やっている対応についてはありがとうございました。そのあたりの見解、認識を伺ったつもりなのですけれども、どなたでも。","respondent":"秋山財政課長","answer":"ボタン一つで全てが解決するということでは考えておりませんので、対応訓練、そういう中で総合的に安全・安心については確保していきたいと考えています。","id":"exchange-004"},{"speaker":"南委員","kind":"質問・要望","question":"したがって、そういうことについての意見、必要な機関に、国も含めてしっかり言って、体制確保ができるように。それこそ安心・安全で、入所者の命も含めて守れるような体制をつくっていただきたいということをこの機会に申し上げたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-005"},{"speaker":"大倉委員","kind":"質問・要望","question":"少し教えていただきたいのが、寄附していただいた方にどういうふうに使いましたというお話をしていくのかなというのを教えていただきたいのと、いまいちイメージがつかないので教えてほしいと求めました。","respondent":"工藤選挙管理委員会事務局長、黒田税務課長","answer":"今回、購入予定ということで書いてありますけれども、今のところいわゆる記載台を購入しようと思ってあります。購入しましたときには、また寄附された方にこういったことに使いましたという形でご説明して、丁寧にお礼をするです。 ふるさと納税との関係ですが、歳入としては一般寄附という形で区分しておりまして、それぞれの目的を持った寄附は指定寄附としてそれぞれの所管で寄附を受けていただくというような関係です。","id":"exchange-006"},{"speaker":"つる副委員長","kind":"質問・要望","question":"このあたりの可能性についてどういう、この辺もし情報があれば１点伺っておきたいのと、何人分で何泊分という形なのかというところです。１回こうやってどんとやると、このあたりに関連してくると思いますけれども、このあたりをどういうふうに捉えているか説明を求めました。","respondent":"秋山財政課長","answer":"この予算の積算なのですが、そのうちサービスの利用を希望する割合が６０％ということで計算をしていって、大体年間３５０人ぐらいを想定しています。その辺は東京都からの補助金もありますので、国の補助金、都の補助金等も勘案しながら検討していくという……。","id":"exchange-007"},{"speaker":"つる副委員長","kind":"確認","question":"もし仮にこういった場合の予算というのはどういう形で手当てできるのかというのと、１点確認、東京都のほうの補助金の位置づけというのはどういう形で来ているのかというのを確認させてください。","respondent":"秋山財政課長","answer":"この辺は対応させていただきたいと考えております。産後ケアの補助金ということではなくて、名称がすぐ出てこないのですが、それの一部を使うというような形で考えているところです。","id":"exchange-008"}]},{"id":"topic-02","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"南委員","kind":"意見","question":"前文の下から３行目の真ん中、「回復基調にある景気」というところが実態とは違うのではないかなと私は思っております。しかし、出すこと自体は昨日も賛成しましたし、大いに多くの方々に還元されるところなので、このところに意見を付しておきたいと思いますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-009"}]},{"id":"topic-03","title":"品川区制７０周年記念事業のＰＲ","agenda":"品川区制７０周年記念事業のＰＲ","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"どうしてこれだけなのかなと思ったので。それぞれの１から４まで、１から４までというか、教えてほしいと求めました。","respondent":"久保田総務課長","answer":"それぞれの予算ですけれども、ラッピングバスについては予算は３００万円で２台という予定、実際はもう少し契約単価は安くなってあります。リーフレットが予算としては１００万円を予定しているというものです。","id":"exchange-010"},{"speaker":"吉田委員","kind":"確認","question":"確認なのですけれども、それぞれが２台、２台走るのか。その辺を計算されてそういうふうになったのか、それとも予算もありますから、そこから割り出されたものなのか教えていただけますか。","respondent":"久保田総務課長","answer":"１台のバスで朝から夜まで走っていますので、人の目に触れる可能性はかなりあると私たちは見込んでいるところでございまして、「わ！バスを走らせると同時にホームページとか、そういったいろいろな広報媒体を使ってＰＲを図っていきたいと考えています。","id":"exchange-011"},{"speaker":"吉田委員","kind":"質問","question":"具体はこれから検討されると思うのですけれども、それはどういう手順というか、それで決まっていくのでしょうか。こういうところを呼んでほしいとか、そういう意見を言う場面というのはあるのかどうか説明を求めました。","respondent":"久保田総務課長","answer":"この講演会とかコンサートの内容は私どものほうで決めていきたいと考えています。コンサート等についてもそういった、品川区の歴史を振り返る式典ですので、そういった方にお願いをしていきたいと考えています。","id":"exchange-012"},{"speaker":"吉田委員","kind":"質問・要望","question":"みんなでつくり上げていったというような気持ちの、区民とともに醸成していけるといいなと思ったものですから、今の質問をさせていただきました。これは要望にとどめします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-013"},{"speaker":"須貝委員","kind":"質問","question":"それはないのですかという。７０周年だという認識がそこでできると思うのですが、いや、こういうふうにやるから大丈夫なのですよという活動というのはあるのか尋ねました。","respondent":"久保田総務課長、中元広報広聴課長","answer":"それぞれのイベントに来庁した方が見ると品川区は７０周年を迎えるのだということをわかってもらいたいと思っています。７０周年で区民全員に何か記念品を配るという予定はございませんけれども… 今、総務課長からもお話がございましたが、９月１日号の広報しながわで区制７０周年記念特集号ということでやらせていただいております。「区制７０周年を迎えます」というものを入れる方向で今、検討をして…","id":"exchange-014"},{"speaker":"須貝委員","kind":"質問・要望","question":"こういうことなのだというのがわかりやすく私はコマーシャルもしていただきたいし、そういうことも大事だし、あの車は今何で走っているのだろうと。本当に近くの生活基盤の区道でも、今でも工夫はされていると思いますが、より多くの方にという形でＰＲしていただきたいと要望します。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-015"},{"speaker":"大倉委員","kind":"質問・要望","question":"教えていただきたいのが、６０万円でどのくらいつくるのかなというところと、どういうふうな考え方でつくられたのかというのを教えてください。ぜひやってほしいと求めましたが、どういうふうにされていくのか教えていただきたいのと、お聞かせほしいと求めました。","respondent":"久保田総務課長、中元広報広聴課長","answer":"その他広報媒体等でＰＲを図っていくという予定ですので、その張る製作現場へ行って、そうした映像も撮ってＰＲしていきたいと思ってあります。学校への対応ですが、学校の対応についてはまず… 広報広聴課のほうで製作現場に取材に行く予定が確定しています。それで事前のマスコミ向けのプレスリリース、また当日のプレスリリース等も予定に入ってあります。","id":"exchange-016"},{"speaker":"大倉委員","kind":"質問・要望","question":"区全体で７０周年をお祝いしたいという、していこうというところで、いろいろな方がお祝いしてくれるようにやっていただきたいなと思っています。時間帯の設定についてこれからということなのですが、どういうふうにお考えなのか教えてほしいと求めました。","respondent":"久保田総務課長","answer":"３月１５日がちょうど品川区が誕生した日ですので、３月１５日に実施をしたいところなのですけれども、きゅりあんが休館日であったです。団体等につきましても今検討していますので、具体的な団体の名前は申し上げることはできませんけれども、こういったものを考えているもので…","id":"exchange-017"},{"speaker":"石田（秀）委員","kind":"確認","question":"それがずっと来年度１年間やれとは言わないけれども、いろいろなことがあるではないですか、町会のまつりだ何だ。８０事業は決めたからそれをやって、この全体１,２００万円で終わりですよというのか、そこら辺の考え方だけを教えてほしい。","respondent":"久保田総務課長","answer":"ただ、来年９月３０日までをＰＲの期間と考えていますので、そういう点では平成２９年度の７０周年のＰＲには努めていきたいと思ってあります。言い方はあれかもしれませんけれども、満７０歳を迎えたというような形で、地域も含めてＰＲができればと思ってあります。","id":"exchange-018"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"ある程度どういうイベントがあって８０事業、必ずそういうところで実り多い７０周年、９月３０日まで迎えられるようにお願いだけしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"大沢委員","kind":"確認","question":"確認をさせてください。交わったところ、ここは碑文谷というか目黒本町の郵便局の横のところにあるバス停でここのところは１回、車をかえるのか尋ねました。","respondent":"久保田総務課長","answer":"車はですね、バスはそのまま終点まで。","id":"exchange-020"},{"speaker":"大沢委員","kind":"質問","question":"ラッピングしていない車にかえるのですかという。わかりますか、言っていること。","respondent":"久保田総務課長","answer":"区外も走りますので。いわゆる品川区を越えて終点が区外であれば、それはバスはかえないでそのまま最後まで行くということです。","id":"exchange-021"},{"speaker":"大沢委員","kind":"質問","question":"世田谷区からしたらいきなり「品川区制７０周年」というバスが来たら、そこらのあたりというのは、相手に連絡なりしてあるのですか。これを言いたいだけなのです。","respondent":"久保田総務課長","answer":"ラッピングバスを走らせますという話は周辺の区の方にはお話は、大田区のほうですけれども、お話はしてありますので、その他の区についてもご報告をしていきたいと思います。","id":"exchange-022"},{"speaker":"大沢委員","kind":"質問","question":"小山三丁目から２６号線のところ。世田谷区と目黒区をお忘れであれば、やはりそれなりに一報は入れておいたほうがよろしいのではないかなと思いまして、質問させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-023"},{"speaker":"南委員","kind":"質問・要望","question":"昭和２０年代から今日まで毎月、その辺を少し中身をわかる範囲で教えていただきたいのと、そういう時期というか時代ですね。ですから、その辺についてどんな見解でこういう事業を組み立てているのか、少し知りたいと思っています。","respondent":"久保田総務課長","answer":"ただ、スペースの問題もありますので、全てを網羅するということはできませんけれども、それらの主なものを掲出していきたいと考えているところです。２３区初の区長準公選を実施したということは大きなことでありますし、区議会…","id":"exchange-024"},{"speaker":"南委員","kind":"質問・要望","question":"改めて、そういう認識を持っておられて、７０周年の記念事業をそれぞれ取り組んでいくということはわかりました。１本確立していただきたいと思っているのですけれども、地方自治の歴史、そのあたりを先ほどの答弁ではわかりませんので説明を求めました。","respondent":"中元広報広聴課長","answer":"広報広聴課のほうで区制７０周年記念番組を今回計画しておりまして、今準備中ですので、周知を図っていきたいと考えています。今はスマートフォンに対応しておりますので、周知が図れるかと考えています。","id":"exchange-025"},{"speaker":"南委員","kind":"確認","question":"そういう思いで具体的にどうなのかなというのを聞いたので、ケーブルテレビで終わりだということなのかどうか、確認をしたいと思います。","respondent":"久保田総務課長","answer":"それと、あとはいろいろな機会を捉えてそういったことをＰＲしていきたいと考えております。区議会と、そういったものも積極的に紹介していきながら、自治権確立の歴史というものを区民の方により多く知ってもらいたいと思ってあります。","id":"exchange-026"},{"speaker":"南委員","kind":"質問・要望","question":"ただ単に７０周年のお祭り、お祭りというと語弊がありますけれども、そういうものに終わらせずに、きちんとした、大事なところは１本立てて、抜かさないで取り組んでいただきたいと考えています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-027"},{"speaker":"つる副委員長","kind":"確認","question":"平成２８年度内ということですからそういうことだと思うのですけれども。そういうのもあると思うのですけれども、まずバスの広告のラッピングについての一般的な決まりみたいなところを確認させてください。","respondent":"久保田総務課長","answer":"我々が直接審議会に出ていってということはやってございませんけれども、広告の規制等についても全てクリアしていると私どもは認識をしています。両方の審議会の審査が通りましたという報告もきちんと受けてありますので、特に問題なく走ることができるというものです。","id":"exchange-028"},{"speaker":"つる副委員長","kind":"質問","question":"そういう作業の、取材も行かれるという話もありましたが、型みたいなものというのはあるのですか。どんな形、形状でもこういうラッピングというのはできるものなのかどうか、わかれば説明を求めました。","respondent":"久保田総務課長","answer":"バス事業者と話をして製作してきていますので、ある程度そういった型というか、原型みたいなものはあるのだと思います。空調の空気が出ているところとかがバスの車種によって違いますので、そういう意味では型がある程度決まっているものだと私どもは認識しています。","id":"exchange-029"},{"speaker":"つる副委員長","kind":"質問","question":"ＰＲ期間が来年９月までというお話もありましたから、そんなものというのはやることができるのかどうか、区の決まりとかも含めて。その辺、いかがか尋ねました。","respondent":"久保田総務課長","answer":"屋外広告の規制などもクリアすれば、できないことはないと思います。マイクロバスもできるとは思います。","id":"exchange-030"}]},{"id":"topic-04","title":"しながわ区民公園キャンプ場等改修工事請負契約","agenda":"しながわ区民公園キャンプ場等改修工事請負契約","exchanges":[{"speaker":"石田（秀）委員","kind":"確認","question":"１点だけ教えてください。しながわ区民公園というのはかまどは１０基だと思うのだけれども、３７基と書いてあるのだけれども、それだけ確認させてください。","respondent":"立川経理課長","answer":"おおむね面積的には変わらないのですけれども、そうしたいわゆる炊事ができるような場所というのは拡張するという、今までの数よりはふやすと聞いております。","id":"exchange-031"},{"speaker":"石田（秀）委員","kind":"質問","question":"どうしてこんなことを聞くかというと、プレイパークもあって、今１０基だったわけです。だから、１０基が、今、拡大するとおっしゃったけれども、それを教えてくださいというだけ。","respondent":"立川経理課長","answer":"内訳ですけれども、かまどが１５基になりまして、野外卓が１８基で、その他の手洗い場、水飲み場ということで、合計３７基です。","id":"exchange-032"},{"speaker":"石田（秀）委員","kind":"確認","question":"それは確認で、今の話だと１５基になるから、１００人だったものがこれからは１５０人になりますよという。区民にとってのサービスが広がりますよということで理解しておけばいいのですねと言ったわけ。","respondent":"立川経理課長","answer":"人数の詳細については聞いていないところなのですけれども、いわゆる受け入れの組数としては拡大することは確かです。","id":"exchange-033"},{"speaker":"南委員","kind":"確認","question":"確認なのですけれども、今回の改修工事にそれが含まれるのか、場所がどこなのかを確認したいのですけれども。説明を求めました。","respondent":"立川経理課長","answer":"場所的には、４ページの平面図の右のほうですけれども、かまどや炊事場とかと印がしてあるところの左側のスペースになりまして、こちらがプレイパークのスペースです。","id":"exchange-034"},{"speaker":"南委員","kind":"質問","question":"そうすると、一緒の工事になるという認識でいいのですか。プレイパークもつけた改修工事という認識でいいのか尋ねました。","respondent":"立川経理課長","answer":"２ページの支出科目のところに、目としまして公園新設改良費と児童福祉総務費というふうに、いわゆるプレイパークの経費も含めて今回の工事になっているです。","id":"exchange-035"},{"speaker":"南委員","kind":"質問・要望","question":"位置的にはこれが入っているのでどうなのかなという確認で質問したのですけれども、プレイパークの位置を改めて確認したいのと、プレイパークの部分についての説明をしてほしいと求めました。","respondent":"立川経理課長","answer":"所管が異なりますのでプレイパーク自体の詳しい説明はできないところなのですけれども、ほとんどそのまま残すと聞いております。このままだとなかなか難しいということで、この辺についていわゆる植栽をしたり、伐採をしたりということで手を加えると聞いているところです。","id":"exchange-036"},{"speaker":"南委員","kind":"質問・要望","question":"平面図の上の部分、大きな道路に面しているところの手を入れるということはわかります。中に排気ガスがみたいなものが入ってこないようにしっかりとした植栽はしていただきたいと思っているのですけれども、では、それはそれでいいです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-05","title":"品川区北品川一丁目付近再構築工事請負契約","agenda":"品川区北品川一丁目付近再構築工事請負契約","exchanges":[{"speaker":"吉田委員","kind":"質問","question":"すごく基本的なことなのですけれども、７ページの工事内容のところで、言葉の説明をお願いします。雨水ますを撤去するという、その雨水ますというのはどういう機能を持ったものなのか説明を求めました。","respondent":"立川経理課長","answer":"雨水ますといいますと、今まで雨水を一時的にますの中にためておくという機能ですが、今後はそのたまった水が徐々に地面のほうに浸透するというますに取り替えるという工事です。","id":"exchange-038"},{"speaker":"吉田委員","kind":"質問","question":"では、２４カ所というのは対応していると考えてよろしいのでしょうか。では、２４カ所というのは、場所を説明を求めました。","respondent":"立川経理課長","answer":"８ページの赤字でお示しした全体の中で、雨水ますを取り替えるところが２４カ所あるです。","id":"exchange-039"},{"speaker":"須貝委員","kind":"質問","question":"お聞きしますが、管きょ工ですか、内面被覆工法というものなのですが、参考にお聞きしたいのですが、これは耐久期間はどれぐらいあるのですか。もとの管があるのですが、下水道管はセメントのものはなくて鉄か何かでできているという、そこに内面被覆工法をするということなのか尋ねました。","respondent":"立川経理課長","answer":"東京都によりますと、こうした工事を実施することで３０年耐用期間を延ばすことができるとしているところであります。素材については、鉄かコンクリートかというのは聞いていないところです。","id":"exchange-040"},{"speaker":"須貝委員","kind":"質問","question":"もとがどんどん、どんどん老朽化していくとセメント類はぼろぼろになるわけで、これをやって３０年もちますよというのは今わかりました。だけれども、もとがだめになったら意味がないのかなと今思ったもので、質問させていただきました。","respondent":"立川経理課長","answer":"東京都では老朽調査の方法としまして、定期的に下水道管にテレビカメラを入れたりしながら、老朽度を調査しています。７ページの４の、老朽が激しいものについては掘り返して管を新しいものに入れ替えるという、そういうことです。","id":"exchange-041"}]},{"id":"topic-06","title":"所管事務調査","agenda":"所管事務調査","exchanges":[{"speaker":"須貝委員","kind":"質問・要望","question":"取組みを一生懸命やっていくと思いますが、その辺も加味して発信をしてほしいと求めました。意見だけです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"石田（秀）委員","kind":"質問","question":"両方、見え方が弱いような気がしてならなくて、そこら辺の考えをどうお考えになっているかというのを教えてほしいな。目的のところでも構わないので。","respondent":"中島企画部副参事","answer":"それ加えまして、区の施策というか、子育ての魅力でありますとか、交通の利便性を含めた総合的なものを区外の方に伝えていきたいと考えています。懐かしい魅力、温かい魅力があるということも積極的に発信して、住みやすいまちであることも伝えていきたいと考えています。","id":"exchange-043"},{"speaker":"石田（秀）委員","kind":"意見","question":"誇りと、住み続けてほしいのだということをやっていくのですよと。そこら辺のもう一回思いをきちんと説明してくれないと、よくわからないとの意見を述べました。","respondent":"中山企画部長","answer":"ある種、幅広にしながら、その中に観光の部分は観光してしっかり別の場面で取り組んでいくことも品川の魅力発信につなげていく。幅広い部分でありますけれども、プロモーションというのは包括的に品川区としてやっていきたい。","id":"exchange-044"},{"speaker":"石田（秀）委員","kind":"質問・要望","question":"区分けなりをしていただいて、こちらは大きいものでいくのだよというようなところが、目的から含めて見えるようにぜひしていただきたいなと思います。これは要望にしておきます。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"つる副委員長","kind":"確認","question":"石田秀男委員からも目的について確認がありましたけれども、捉え方、それによっていろいろ売り出し方というものがあると思います。改めてそこの部分どういうふうに、すごく幅広なのですけれども、この点を１点確認させてください。","respondent":"中島企画部副参事","answer":"品川区、短期的には今、総合戦略でありますとか、実施計画の中でメディア認知度とかいうものも掲げているところですが、最終的には区民が誇りと愛着を持ち、そしてまた定住人口も引き続き確保できるというところを目指してプロモーションのほうを進めていきたいと考えています。","id":"exchange-046"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ですから、これは取組み始めたところですから、行政としても。質問ですが、もう少し、既にそういうコンテみたいなものがあったとしたら内容を詳しく教えていただけますか。","respondent":"中島企画部副参事、中元広報広聴課長","answer":"今回、動画のほうが１分半のものを２パターンということで、ＣＭみたいなものを１つつくる予定です。最終的には懐かしい魅力を見た方に植えつけたいと、品川区に行ってみたいな… 都会的なイメージ、物事に動じない女性で都会的なイメージの方をオーディションの中で選ばせていただいたということで、その方がお祭りとかに行って少し品川区に対するイメージが変わるというような内容で今つくっているところです。","id":"exchange-047"},{"speaker":"つる副委員長","kind":"質問・要望","question":"ですから、今回おそらく主役になるであろう俳優さんが女性という観点ですから、これは要望ですがしてほしいと求めました。３ページの(6)のオリジナルフレーム切手ですが、もしくは逆に歳入として入ってくる部分があるのかどうか、これを説明を求めました。","respondent":"中島企画部副参事","answer":"今回、単価１,５００円のフレーム切手ですが、広報広聴課が区政資料コーナーで３００シートを販売する予定です。ですので、４５万円の切手を購入いたしまして、それを同額で販売するという形で予定しています。","id":"exchange-048"},{"speaker":"吉田委員","kind":"質問","question":"皆さんのご意見すごくもっともだと伺いました。３ページの４の今後の取組みについて、皆さんのご意見を伺っても、それを考えていらっしゃるということだと思います。","respondent":"中島企画部副参事","answer":"適宜見直しということで、まず今年度アンケートを行いますので、その結果を踏まえてまた見直し等を行ってまいりたいと考えています。","id":"exchange-049"},{"speaker":"吉田委員","kind":"質問","question":"「指標を検討し」というふうに書かれているのですが、指標についてはどのように検討されていて、いつまでには決めるという、そちらのほうも説明を求めました。","respondent":"中島企画部副参事","answer":"そのほかの方法、広告換算等は、どのような形で進めていくのがいいのかというところは日々検討しております。ですので、数値化できると判断した段階で、指標として定めていきたいと考えております。","id":"exchange-050"},{"speaker":"吉田委員","kind":"質問","question":"わかりました。１本この数値に設定したという、その辺は今までの皆さんのご意見を伺っても、その点お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"南委員","kind":"質問","question":"先ほど、オリジナルフレーム切手は経費がかかっていないという話なのですが、７事業をやるに当たって、それぞれどのくらいの事業費を予算としているのか、具体的な数字、わかっている範囲で説明を求めました。","respondent":"中島企画部副参事","answer":"４の２８年度の取組みについてですが、予算としましては２,６７４万円を計上しています。(1)から(7)まで記載していますが、その経費につきましては２,６７４万円と、あとシティプロモーションサミットが３０５万円を予定しています。","id":"exchange-052"},{"speaker":"南委員","kind":"質問・要望","question":"その個々の７つの事業でかかったものがあれば、具体的な数字を教えていただきたいのです。","respondent":"中島企画部副参事","answer":"鉄道車内動画モニターへの広告掲載は約２４０万円、ＰＲポスターの制作につきましては約３００万円、その他諸経費が約５０万円を予定しています。魅力発信事業は予算が５００万円、シティプロモーションサミットが３０５万円です。","id":"exchange-053"}]},{"id":"topic-07","title":"総務委員会を再開いたします。 改めまして、行政視察","agenda":"総務委員会を再開いたします。 改めまして、行政視察","exchanges":[{"speaker":"石田（秀）委員","kind":"質問","question":"我々も基金検討委員会などというのを伺ったりもしてきたのだけれども、指定寄附金の話があったではないですか、１億１,１１３万６,１７６円。どういう感じで、どういうぐらいの、何かそういうのを行く前に知っておきたいなと。","respondent":"田村総務部長","answer":"できるだけ視察に間に合うように。結構所管がばらばらになってしまっていて、単発なのと、同じ人がずっと出しているのとありますので。","id":"exchange-054"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/701406?Template=document&Id=2058#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":51084,"voices":165}},{"id":"h28-20160929-14","meetingId":"h28-cm09","date":"2016年9月29日","dateIso":"2016-09-29","committee":"行財政改革特別委員会","time":"午前１０時００分～午後 ２時５２分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を65件整理しています。","topics":[{"id":"topic-01","title":"公有地等、公共施設活用に関すること","agenda":"公有地等、公共施設活用に関すること","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"3)の資産としての有効活用のところで、有効活用プランのところで、既にこのところで売却されたところがあるのか伺いたいと思います。３の公園施設長寿命化計画のところで、これはどういったものになっていくのか、何が対象になってくるのか教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"そういうことではありませんで、それから改修の時期をどうするのだというのを当然その施設の管理者である各所管部門が検討するわけですけれども。その施設の利用状況…","id":"exchange-001"},{"speaker":"のだて委員","kind":"質問・要望","question":"ゼロベースで見直すのは、全てやっているわけではないということでしたが、今進んでいるのが幾つか、何があるのか教えてほしいと求めました。これは建て替えるということも検討の中には入っているのか、ちょっと今見た感じだとないのですが、その考えもあるのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"橋の架替そのものも検討したり、歩道橋みたいなものについては、用途に応じてそこを廃止するといったところの考え方で建替えも含めて考えはあります。建物ですので、これは老朽度に応じて…","id":"exchange-002"},{"speaker":"のだて委員","kind":"質問・要望","question":"これは現在検討中で、まだその段階には至っていないという認識でいいのか確認させてほしいと求めました。そして、今ある長寿命化計画も改訂をしていくということになるのでしょうか、伺いたいと思います。","respondent":"柏原企画調整課長","answer":"そういったところから、また、そういった視点に立って公共施設の今後のあり方というのは検討すべきであろうというところに立っているというものです。それから、これからちょっと検討中ですので…","id":"exchange-003"},{"speaker":"のだて委員","kind":"質問・要望","question":"今いろいろ平準化等していく、区民の福祉向上の観点からしっかりと検討していってほしいと求めましたが、いかがでしょうか。そして、この総合管理計画、２３区内では既につくっているところというのはどのくらいあるのか、現在の状況をぜひ教えてほしいと求めました。","respondent":"柏原企画調整課長","answer":"計画の考え方のところであると思いますけれども、これは無視はできませんので、念頭に置きながらです。ですから、さまざまなところを検討しながら、この計画に基づいてその施設のあり方というのを考えていくべきものというふうに考えてあります。","id":"exchange-004"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、補助金の関係で、どういったものが個別計画もないと補助金が出ないのか、今わかれば教えてほしいと求めました。どういったニーズがあるのか、こういった調査もしてほしいと求めましたが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"全ての部分においてそういうふうに考えるかというのは、当然そういったことも、ゼロベースで検討するというのはあり得ることであると思います。それは区のほうでいろいろな内部での検討、当然お使いいただく方々の意見…","id":"exchange-005"},{"speaker":"渡部委員","kind":"質問","question":"幾つかお伺いするのですけれど、これから先どういうふうにあればいいのだというような中で、では学校をどういうふうにしよう。昭和４２年でしたっけ、ですからもう５０年を超えていまして、大改築があって耐震化がありました。","respondent":"柏原企画調整課長","answer":"区の内部の検討という形で、その施設の規模であったりというのがありますので、これは少し検討しながらやらせていただきたいと思ってありますが。機能、検討しなくてはいけないだろうと思ってありますが…","id":"exchange-006"},{"speaker":"渡部委員","kind":"質問・要望","question":"例えば２０年前と比較して、行政が何かを建てたり壊したりするときの地域住民の合意形成というのが日に日に難しくなっているような気がしております。今考え方は伺いましたので、要望といいましょうか、では最後に考え方だけ聞かせてください。","respondent":"中山企画部長","answer":"少し大きな答え方になってしまうかもしれませんけれども、こういう施設を検討する際に、あるいは今後の考え方のベースになってくるかと思います。反映の仕方、または伝え方というのは工夫しながら…","id":"exchange-007"},{"speaker":"あべ委員","kind":"確認","question":"では６５年ということになれば、この５０年、６５年というのはどういうことを意味しているかということをまず考え方として確認したいと思います。ですから、平成３０年代のところの差額より大分広がっているわけです。","respondent":"柏原企画調整課長","answer":"鉄筋コンクリートですと６５年という数字が出ていたりしますので、ある意味、その負担がどうなるのだというのを示させていただいたのがこれです。平成２４年から平成３６年に向けて、単純に後ろにいくというつもりではなかったのですけれども、意味合いとしてはそういうことです。","id":"exchange-008"},{"speaker":"あべ委員","kind":"質問・要望","question":"数字はわかったらまた後で教えていただきたいのですが、この建設関係だけでも今後３０年間で数千億円というような需要がほぼ確実に発生していく。それから、支出が右肩上がりで収入が伸びどまるであろうという考え方に対して、品川区としてはどのように捉えていらっしゃるかお伺いしたい。","respondent":"柏原企画調整課長","answer":"区としては認識としてはそういうのは、総合戦略も含めてですけれども、これからも検討しなくてはいけないと思っているところです。いろいろな部分で考えなくてはいけないというところがありますので、そういったところをトータルで考えてということで認識をしています。","id":"exchange-009"},{"speaker":"あべ委員","kind":"質問・要望","question":"そういったこともぜひ気を遣っていただきたいと、ぜひ配慮していただきたいと思うのですが、いかがでしょうか。これもお考えを説明を求めました。","respondent":"柏原企画調整課長","answer":"建設の関係の事業者とか、検討する場がありますので、ご指摘いただいた部分は参考にさせていたたきながら進めさせていただければと思います。なおかつサービス維持、さまざまな民間の手法等もありますけれども…","id":"exchange-010"},{"speaker":"あべ委員","kind":"質問・要望","question":"使えるのであれば別に１００年使っても２００年使っても全然問題ないわけですから、そこは、ぜひ実をとってほしいと求めました。最後は要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"筒井委員","kind":"確認","question":"確認なのですけれども、つくるべきものはつくる、建て替えるべきものは建て替えるべきだと考えております。そうした人口増地域の小学校について、この計画でどうお考えになるのか、この３点を説明を求めました。","respondent":"柏原企画調整課長","answer":"考え方としてはその施設、それから、その事業そのものが民営化たり得るのかどうかという視点での検討ということであろうかと思います。今、まさに今それは教育委員会のほうで、学事制度審議会の中でそういったところの考え方というのは検討しています。","id":"exchange-012"},{"speaker":"筒井委員","kind":"質問","question":"そうしたお考えはあるのか。そのほうが長期的に見てコストが低くなると思いますので、歩道橋を廃止して横断歩道に移行するお考えがあるのかということをお聞きしたいと思います。","respondent":"柏原企画調整課長","answer":"ものによっては廃止している歩道橋もあるやには聞いてありますし、やはり使われていてこれがないとというところもあるやには聞いてあります。ですので、そういった利用状況とかを踏まえながらということであろうかと思います。","id":"exchange-013"},{"speaker":"若林委員","kind":"質問・要望","question":"いわゆる供用年数というのですか、自治体としての、公共団体としてのこの年数の設定の仕方は何か決まりがあるのでしょうか。勝手に５０年だ、そういうことで今後こういう計画を立てるのですというような国とかの考え方があるのかというのをちょっとまず確認させてください。","respondent":"柏原企画調整課長","answer":"長寿命化をすることによって鉄筋コンクリート造の建物を躯体が持ちこたえられる部分まで延ばしましょうというのが考え方としてとっています。そこがたしか鉄筋コンクリートは６０年、そういったところを参考にしながら区としてはこのデータのつくり方をしているというものです。","id":"exchange-014"},{"speaker":"若林委員","kind":"質問・要望","question":"前回８月のこの行財政改革特別委員会では総合計画のスパンはどのぐらいですかと聞いたときに、３０年を経過している施設が既に６０％ありますと。そうすると１０年、逆にそういうものを巻き起こすというような前向きな総合計画であるべきではないのかという感想を持ったのですが、お答えください。","respondent":"柏原企画調整課長","answer":"パブリックコメントはやる予定ではありますけれども、逐一ご意見を伺える場面ということで情報提供させていただきながら進めていきたいと思います。皆さんが使う施設でありますので、それについては…","id":"exchange-015"},{"speaker":"若林委員","kind":"提案","question":"他の委員のさまざまな感想とかご提案、要望というのが、６０年は超えると。もう少しこの交付金の見通しを持てるような、答弁というかご努力というか、今後のあり方というのを、その２点との意見を述べました。","respondent":"中山企画部長","answer":"それから方針のところ、施設の類型に応じた整理をもう少しやっていくということが総合計画の中で出てこようかなというところが考えられます。イメージとしてはまだどこまでかというのをさまざま検討している中で申し上げたと、こういうふうなことでご理解いただければと思います。","id":"exchange-016"},{"speaker":"安藤委員","kind":"質問","question":"当時、何かに基づいてつくったのでしょうか、何か区が受諾したモデル事業だったのでしょうか。そこら辺があればまず説明を求めました。","respondent":"柏原企画調整課長","answer":"それに基づいて考え方をきちんと示して、それに基づいた施設のありよう、進め方をしなくてはいけないという問題意識のもとにやったということです。ですから、どこからか国の法律が変わったとか動きがあったとかということではなく、区の発意というところで動き出したものです。","id":"exchange-017"},{"speaker":"安藤委員","kind":"確認","question":"一つ質問したいのが、わずか３年の間に７年伸びて平成３９年になったわけですけれども、その要因を伺いたいと思います。どうやって人口構成を維持していくのか、その手段、品川区はどのようにしていこうと思っているのかお伺いします。","respondent":"柏原企画調整課長","answer":"７０年と、どういう考え方でつくるかというのは非常に大切な部分でありますので、この総合計画の中で整理をしながら検討していきたいです。いろいろ要素はあると思いますけれども、転入がそういった形で我々の予想以上に伸びているというのが現状だです。","id":"exchange-018"},{"speaker":"安藤委員","kind":"質問・要望","question":"ちょっと委員長にも要望したいのですけれども、資料として出してもらいたいと思います。例えばこの学校施設ですけれども、建替えの際の財源や補助算定についてはどのような仕組みになっているのか、そこの点だけ具体的にお伺いします。","respondent":"柏原企画調整課長","answer":"第一の前提で、先ほどの資料で説明させていただいた２ページ目の(1)で、長期基本計画の着実な実現ということで示させていただています。一定程度の財政の確保というのは考えないと、先ほども議論がありましたけれども…","id":"exchange-019"},{"speaker":"安藤委員","kind":"質問・要望","question":"２５ある施設を２０にするという数値まで出ているのですけれども、今回、これをそのまま進めていくのでしょうか。それをちょっとお伺いします。","respondent":"柏原企画調整課長","answer":"今検討しております施設の総合計画につきましては、この有効活用プランの考え方がベースになるというのは先ほど来申し上げているとおりです。この部屋の広さは建てられた当時の部屋の広さになっていますから…","id":"exchange-020"},{"speaker":"安藤委員","kind":"質問・要望","question":"費用対効果を考えて規模を設定となりますと、一体どう考えたらいいのかというふうに思うのですけれども、そこら辺も含めてちょっとお伺いします。売却方針を柱に入れるのは、プランには入っていますけれども、総合計画ではやめるべきだと思いますけれども、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"所管部門の考え方、方針等々もありますので、そういったところを踏まえて特別養護老人ホームという施設を新たに入れさせていただいたというものです。最後といいますか、一つの考え方として売却という考え方があるといものですので、売却ありきではございません。","id":"exchange-021"},{"speaker":"安藤委員","kind":"質問・要望","question":"公共施設有効活用プランの中身を発展的にという話もありましたが、私は、それは考え直していただきたいということで意見を改めて述べさせていただきまして終わります。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-022"},{"speaker":"あべ委員","kind":"質問・要望","question":"借金を毎年しているような中で、今後、自治体に対する補助金が全体として増えていく可能性というのは極めて少ないと考えております。たしか土地が９割と建物も２分の１と４分の１といった、補助金というのもこれは実は現在と比べるとマイナスの、区の考えはいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"もろもろの補助金、突然打ち切りされたりとかというものもありますので、それを前提とした計画というのはなかなか厳しいと思っています。増えるか減るかというのはなかなか判断が難しいところですが、その辺は慎重に状況を見ながらということになろうかと思います。","id":"exchange-023"}]},{"id":"topic-02","title":"旧荏原第四中学校跡地の活用計画（案）","agenda":"旧荏原第四中学校跡地の活用計画（案）","exchanges":[{"speaker":"のだて委員","kind":"質問・要望","question":"４番のその他のところで地域利用等々ありますけれども、これはどういったことが検討されていらっしゃるのか伺いたいと思います。その人数分減らすことがないように確保できるのかということもあわせて伺いたいと思います。","respondent":"柏原企画調整課長","answer":"検討中でございまして、この段階でどちらの保育園というのは明確な回答はできないのですけれども、近隣ということで今調整検討しています。できればプラスアルファの部分というのができるかどうかというのは、今後の改修の中で詰めていきたいというふうに思ってあります。","id":"exchange-024"},{"speaker":"のだて委員","kind":"質問・要望","question":"戸越台の学校の改築も３３年までというところで、そういった中でどういう考え方でこの５年になっているのかということをお伺いしたいと思います。今やってないと思うのですが、今後、今後こういった体育館の開放も考えているのか伺いたいと思います。","respondent":"柏原企画調整課長","answer":"行政需要を満たすためにどうしたらいいかという検討の中で、やはり待機児童対策というのは一つ大きな視点がありますので、その保育園の設置。戸越台中の関係ということで、その期間の中ででき得る行政需要に対応できるものということで…","id":"exchange-025"},{"speaker":"のだて委員","kind":"質問・要望","question":"そして、暫定活用の後、検討されているのか、どういった計画があるのか伺いたいと思います。その中でぜひ特養のほうも考えていただきたいと思うのですが、いかがか尋ねました。","respondent":"柏原企画調整課長","answer":"まだこちらにつきましては検討の段階ということで、建物の更新というところも念頭に入れなくてはいけませんので、そういったところも含めて。広い視野を持ちながら検討していきたいというふうに思ってあります。","id":"exchange-026"},{"speaker":"のだて委員","kind":"質問","question":"そうすると、大体もう５年後には新たな施設の建替えもしていくというところで、計画を検討されているということでよろしいのか尋ねました。","respondent":"柏原企画調整課長","answer":"建物の寿命というところを考えますと、はっきりした年数が何年ということは言えませんけれども、５年程度ということで、更新も念頭に入れながら、次の計画案に向けて検討していきたいというものです。","id":"exchange-027"},{"speaker":"のだて委員","kind":"質問・要望","question":"ぜひ、新たな更新のときには、保育需要もありますけれども、特養のほうも検討の中に入れてやっていってほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"渡部委員","kind":"質問・要望","question":"要望はお願いしていたのですが、この度また平成２９年の１２月ですか、やはりこの４番の地域利用という中には。豊葉しかないようなところですから、先ほどの体育館の話もございましたけれども、その辺はお考えをお聞かせいただきますか。","respondent":"柏原企画調整課長","answer":"基本的にはそういったような流れになればというふうには我々も思っております。管理の問題であるとか、できるだけ前の状態に戻せるような努力はしたいと思いますけれども、調整をさせていただければというふうに思ってあります。","id":"exchange-029"},{"speaker":"松澤委員","kind":"質問・要望","question":"ますます旧荏原第四中学校というものが、ほかの要望を唱えているようですけれども、その点はしっかりと心にとめておいてほしいと求めました。その点は一つお聞きしたいと思いますけれどもいかがか尋ねました。","respondent":"柏原企画調整課長","answer":"それから何か事故が起こってはという部分がありましたので、水を抜いて、現在そのままの状態にしているという状況です。現在あのままの状態で水を入れるというのは非常に難しいと思ってございまして、現段階では水を入れるという考え方は、今はないという状況です。","id":"exchange-030"},{"speaker":"あべ委員","kind":"質問","question":"最近のもの以外は区立の保育園それぞれ老朽化していたと思います。順番やどこというのは全て決まっていないにせよ、何園ぐらいの仮園舎にする予定にしているのか説明を求めました。","respondent":"柏原企画調整課長","answer":"期間が今５年程度というふうに考えてありますので、その建物改修する年限とか考えますと２園ぐらいを想定しています。３園はちょっとできないだろうというふうに思ってあります。","id":"exchange-031"},{"speaker":"あべ委員","kind":"質問","question":"この時期が前後するのかと思ったのですけれども、５年というのがまず先にあって、５年間でできる園数という考え方でよろしいのでしょうか。ここで２園程度しかこなせないとすると、それも勘案してのここでは２園程度ということなのか尋ねました。","respondent":"柏原企画調整課長","answer":"先ほど申しましたように、旧荏原第四中学校につきましてはその後の検討というところもありまして、５年程度という考え方をとらせていただきました。代替地を確保しながら建物の更新を図っていきたいということで、これは保育所管部門のほうでも今検討を進めているというものです。","id":"exchange-032"},{"speaker":"あべ委員","kind":"確認","question":"一応確認なのですけれども、耐震基準そのものにはこの旧校舎は適合しているということでよろしいでしょうか。ある程度その５年先にはどうするというさらなる次の検討を控えている状態であると考えてよろしいのか尋ねました。","respondent":"柏原企画調整課長","answer":"それから５年という考え方ですが、それからどういう保育園、この規模を目指しての運営の仕方ということで考えています。今の形態では５年ということで考えてありますので、そうした中では５年というのを一つ軸と考えたいというものです。","id":"exchange-033"},{"speaker":"あべ委員","kind":"質問","question":"最近プレハブとは言わないのですか、仮設の建物を建てて、引き続き保育園として保育事業を行うという可能性もあるということなのでしょうか。その５年というのが本当にかっちり５年なのか、どういうことなのかということをお伺いしたいと思います。","respondent":"柏原企画調整課長","answer":"なるべくこの建物を有効活用したいということで考えてはいるのですが、そういった部分も経費の面も含めて今検討しています。そういうのも含めて、運営に大きくそこはかかわるところでもありますから、そういうのも含めて今検討している状況というものです。","id":"exchange-034"},{"speaker":"あべ委員","kind":"質問","question":"多分運営主体の違う２つの別々の保育園で、厨房を２つつくるのかとか、とてもいろいろな課題が出てくると思います。設計ですとか、あるいは暫定保育園をするのであれば事業者の決定ですとか、どのような順番でスケジュールを決めていくのか尋ねました。","respondent":"柏原企画調整課長","answer":"すぐ作業に入っていきたいという思いはありますので、来年度の予算には、そういうスケジュール感で進められればというふうに思っています。並行にはなってしまいますけれども、平成３１年の当初には動き出せるような状態ということで…","id":"exchange-035"},{"speaker":"安藤委員","kind":"質問・要望","question":"やはり翌年の４月に保育園の暫定ですから、これは開設を間に合わせるということが私は非常に求められているのではないかと思っていまして。それと、２つの保育園が共存するということになるという質疑もありましたけれども、そこら辺の現時点での区の考え方をお伺いします。","respondent":"柏原企画調整課長","answer":"問題につきましては、これは区の喫緊の課題というふうに捉えてありますので、できるだけ早く対応したいというような思いはあります。思いといたしましては、なるべく待機児童解消というものは早く対応していきたいというところがありますので、スケジュール感については。","id":"exchange-036"},{"speaker":"安藤委員","kind":"提案","question":"それと、のだて委員からも提案がありましたけれども、それは総合的に防災のことも踏まえながらぜひ検討していただければと考えています。要望ですとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-037"}]},{"id":"topic-03","title":"意見書（案）","agenda":"意見書（案）","exchanges":[{"speaker":"渡部委員","kind":"質問・要望","question":"これが飛ぶことによる騒音、努めてほしいというようなところでございまして、「区民の不安解消」というような言い回しにさせていただきました。３番につきましても、その中でこのような形で修正をしていただきたいという思いで出させていただきました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-038"},{"speaker":"こんの委員","kind":"質問・要望","question":"情勢的にどうなのかという声がありましたので、してほしい要望としての事項なので、ここは削除というふうに考えました。それから要望事項ですけれども、１点目には「協議の場」というところの表現は、そういう表現に改めてはいいのではないかということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-039"},{"speaker":"安藤委員","kind":"質問","question":"考えが違うから会派が違うわけですから、先ほど委員長も言っていましたけれども、少なくとも一致できるのではないかというふうに思います。進めるに当たってこうしてほしいという文脈に中身がなってしまっているというのが、大きく意味合いが変わってきてしまうということです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-040"},{"speaker":"あべ委員","kind":"提案","question":"かつ私たちは一昨年１２月に１回目の意見書を出しているわけですから、あのときもいろいろ議論がありましたけれども、私はあり得ると考えています。そういったことで、内容をご理解いただき、提案として受けとめてほしいと求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-041"},{"speaker":"筒井委員","kind":"提案","question":"あべ委員からご提案があった、この新飛行ルート案、上空２００メートルから４５０メートル低空飛行するということ。〔「だめですよ」「出してないのですから」と呼ぶ者あり〕との意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-042"},{"speaker":"筒井委員","kind":"質問","question":"ですから、先ほど委員長がおっしゃられたように、品川区との協議の正式な場の設定というのは必要かと思います。住宅への防音工事をやってほしいというご意見も多いので、「住宅への防音工事拡大」という旨を載せるということもよいのかなと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-043"},{"speaker":"渡部委員","kind":"質問","question":"何かあるのだったら９月２日までに出すべきところを出していない会派から言う発言というのは信じられませんので申し上げします。しっかり議事録に残してください。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-044"},{"speaker":"渡部委員","kind":"質問","question":"１件ちょっと。それともう１件だけよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-045"},{"speaker":"渡部委員","kind":"質問","question":"ですからもう一度まとめて提示いただいて、行財政改革特別委員会としてなるべく全会一致でいきたい原則が当然ありますので。そういうような進め方でお願いしたいと思うのですが、公明党、民進党いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-046"},{"speaker":"渡部委員","kind":"質問","question":"すみません、失礼しました。委員長そのように思うのですが、いかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-047"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"今、渡部委員のほうから、委員長の仕切りとして各会派のお考えを伺っていきたいと思いますという仕切りで行いました。そのときに、確認したい事項等がありましたら、そういう思いも含めてちょっとご議論いただきたいなという思いで出したものです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-048"},{"speaker":"渡部委員","kind":"質問","question":"まさに今数分前にこれをやっていたわけですから、これ以上の意見もございませんし、そもそもこの後に向かってでも意見書は出せないのではないですか。今日の今日、これはきつくないか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-049"},{"speaker":"あべ委員","kind":"質問","question":"一応９月２日の設定で修正案を出すという、一応委員会としてのルールもあったわけですから、今後の話として私は思います。今の委員会の雰囲気ですと、逆にお互いの案をまとまらない方向に行ってしまうことをちょっと今危惧したものですから、皆さんいかがか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-050"},{"speaker":"安藤委員","kind":"質問・要望","question":"私も反対すべきだと思うのですが、そこまで皆さんに一致を求めるということは難しいかなという判断なのです。ですから、やはりもう少しお互いに意見交換といいますか、いろいろ質疑し合うというのが私は大事だというふうに思っておりますけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-051"},{"speaker":"若林委員","kind":"意見","question":"３会派から修正案が出ておりまして、維新・無所属の会派からは今日意見は開陳されましたけれども、文書として出ていないと。９月の２日は今日とうに過ぎて、もしかしたら大事なのかなという感想を持ちましたので、一応投げかけておきますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-052"},{"speaker":"本多副委員長","kind":"質問","question":"私副委員長ですから、我々２人でこの修正案を一つの、今日この場で皆様方からご発言をいただきました。改めて何か結論が出せそうな気になりましたので、いただいたご意見で、正副でもみ直せればなというふうに思いました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-053"},{"speaker":"筒井委員","kind":"質問・要望","question":"前回の委員会で、９月２日の締め切りで意見を求めるということだったのですけれども、それはちょっと私の個人的な考えだったのですけれども。最終的には皆さんの意見が折り合うという正副委員長案が最終的には提示されるという進め方でよろしいのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-054"},{"speaker":"鈴木（ひ）委員長","kind":"質問・要望","question":"今、副委員長としては正副で改めて案が出せそうな気がしてきたというお話なのですけれども、私はちょっと皆さんに確認させていただきたいのが。ここは、だから本当にこのままずっと強行するのはだめですよと、こういう立場はこの議会として出していきたいというところはよろしいか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-055"},{"speaker":"若林委員","kind":"質問","question":"こういう表現はいかがなものですかということに対して、副委員長がまともにそうだねと非常に前向きな明るいお話がありました。もし今この場でぱっと言えないことがあれば、そういうふうにお引き取りいただいてもいいのかなと思いますけれども。","respondent":"鈴木（ひ）委員長","answer":"このまま進めるというふうなことはだめですよという、そこの前提は私は今回の……、そういうふうに進められようとしているわけではないですか。そこら辺のご意見はいただけたらなと思うのですが、いかがでしょうか。","id":"exchange-056"},{"speaker":"渡部委員","kind":"質問","question":"それに対してというものが意見書として上がってくるでしょうから、思いとしては本当に今委員長の思いは思いで当然伺わせていただいて。このようなことは委員会運営上、あり得ませんので、そこの配慮だけは一つくれぐれも。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-057"},{"speaker":"あべ委員","kind":"質問","question":"あの７月の会というのは、性質の違うことであったと私は考えておりますし、ご答弁もそのような内容だったと思います。厳密に言えば、ここの表現というのはちょっと事実関係とずれがあるのではないかと思っているのですが、皆さんのご解釈はどうか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-058"},{"speaker":"こんの委員","kind":"質問・要望","question":"委員長がそこを押し通すみたいな形でどうですかとなると、話が全然まとまらないような気がするのですが、いかがでしょうか。委員長のお１人の意見のようにここはどうかというふうに皆さんに意見が求められると、案は、非常に疑問に思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-059"},{"speaker":"こんの委員","kind":"質問","question":"今おっしゃられたことは、皆さんの意見認識はどうかとおっしゃるならば、どうでしょうか。理事者の方、ご説明願えますか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-060"},{"speaker":"こんの委員","kind":"質問・要望","question":"要するに、ここの「了承を得た」というところの認識がどうかということを今皆さんに聞いてますけれども、区としてはそこら辺の、議会でも質問がありましたけれども、もう一度その点ご説明ほしいと求めました。","respondent":"中村都市計画課長","answer":"理解したという意味は、それをもって関係自治体としてそれを進めてほしいとか、国から説明がありました。あるいは説明を十分に尽くしていただいたりというような、そういったところで区として、そういった役目として一生懸命頑張っているところです。","id":"exchange-061"},{"speaker":"安藤委員","kind":"提案","question":"もう一つまた、航空機からは大量のナノ粒子が排出されているということが確認されたとありました。区に改めてお伺いしたいのですけれども、都民の皆さんの質問に対してどのような回答を出しているのか、改めて伺いたいのですがとの意見を述べました。","respondent":"中村都市計画課長","answer":"国からの説明によれば、フェーズ２の中でも、パネルにもございましたけれども、大気汚染につきましては、この影響は限定的であるというような、そういった文章として表現がなされております。","id":"exchange-062"},{"speaker":"安藤委員","kind":"質問","question":"そしてこれにゴーサインを出すようなことがあってはならないと思いますので、私は改めてこの大気汚染というのは残すべきだなと思いました。もし、皆さんで何かご意見とかありましたら、ぜひお伺いしたいと思いますが、意見は述べします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-063"},{"speaker":"あべ委員","kind":"質問","question":"別に何ていったらいいのでしょうか、うがって見ることなくその言葉どおりに受けとめていただければありがたいと思います。やはりこれをまとめていきたいというのが最大の目的です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-064"}]},{"id":"topic-04","title":"の議会閉会中継続審査調査事項","agenda":"の議会閉会中継続審査調査事項","exchanges":[{"speaker":"安藤委員","kind":"質問","question":"夏８月からでしたけど、もう９月ということですので、最新の状況がどうなっているのか伺えればと思います。平成２４年から８年ということになりますと、平成３２年９月で返還されるということに関しては、変わりがないのかもあわせて伺えますか。","respondent":"柏原企画調整課長","answer":"ＴＯＣの中で建替えに関しての検討といいますか、現段階でいつから着工といったところとか、そういったところは状況としては聞いてないところです。そういったところから、その後の状況については、こちらはまだ細かい計画については聞いてないといったところです。","id":"exchange-065"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/858443?Template=document&Id=6016#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":72280,"voices":154}},{"id":"h28-20160930-18","meetingId":"h28-cm09","date":"2016年9月30日","dateIso":"2016-09-30","committee":"オリンピック・パラリンピック推進特別委員会","time":"午前１０時００分～午後 ４時１４分","status":"正式会議録","sourceType":"formal","overview":"オリンピック・パラリンピック推進特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を35件整理しています。","topics":[{"id":"topic-01","title":"特定事件調査","agenda":"特定事件調査","exchanges":[{"speaker":"あくつ委員","kind":"質問・要望","question":"本文の上から３行目、丸ポツの１行目なのですけれども、ちょっと教えていただきたいのですが、こういう言い方があるのかどうか。すみません、つまらないことですけれども、それだけ確認をと思いまして。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"後利用という考え方は、東京都のほうで示されております。ただし、「跡」という字が「後」になりますので、こちらは「後」という字に修正したほうがいいかと思われます。","id":"exchange-001"},{"speaker":"いながわ委員","kind":"質問・要望","question":"こういう要望書に関しては「である」調というか、「模索していくべきである」と来て、こういう文章の書き方でいいのかどうなのか。よくこういう要望書とか、そういうものというのは統一感は出したほうがいいと思うので、その辺は。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-002"},{"speaker":"いながわ委員","kind":"質問・要望","question":"例えば、丸ポツの２つ目の最後のほうに「方策を模索していくべきである」、その次の丸ポツも「留意すべきである。ずっとその下、最後に「下記の事項を強く要望いたします」だと、要望書というのはおそらく「である」調でよく書くのではないかと思うのですけれども。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-003"},{"speaker":"いながわ委員","kind":"質問・要望","question":"やはり何かこちらからしっかり意見を、要望を出すので、ちょっと強目なのかと。通常、要望書とかそういうのはそういう書き方をしていたのではないかと、ちょっとわからなかったのでお伺いしました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-004"},{"speaker":"つる委員","kind":"意見","question":"最後の「つきましては」の１つ前の「考えております」なので、ここは「います」、「います」かと思います。そこだけとの意見を述べました。","respondent":"渡辺委員長","answer":"ここはそうですね。「考えています」に直します。","id":"exchange-005"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"この形で正しいと思うのですけれども。これは下の記書き以下の要望事項だから「ます」であって、意見書全て、前半部分はこの形だと思いますけれども。","respondent":"渡辺委員長","answer":"正副で考えたときは、項目については「ある」と。主張があって、それを取りまとめて一括した場合が「要望いたします」という形で、そういう２段階の区分で考えています。","id":"exchange-006"},{"speaker":"南委員","kind":"質問・要望","question":"これは大井ふ頭中央海浜公園および潮風公園ということに限っての要望書という理解でいいのですよね。この２つの公園以外に、それはこれには属さないで出していくという理解で、別の機会にそういう要望もしていくという理解でいいのか尋ねました。","respondent":"渡辺委員長","answer":"整備のところで具体性のあるものを６個絞ったという考え方でおりますので、おそらく東京都もそうですし、私たちも大前提であるという解釈です。","id":"exchange-007"},{"speaker":"鈴木（真）委員","kind":"意見","question":"この中でちょっと気になったのは、１６番のところです。「航行スピードや走行音」というのは、何の航行速度というのを前段につけたほうがいいのではないかとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-008"},{"speaker":"鈴木（真）委員","kind":"意見","question":"例えば、ジェットスキーとかということ、そうしないと、モーターボートも含むから、書き方も含めてちょっと検討してもらったらどうかとの意見を述べました。","respondent":"渡辺委員長","answer":"そのとおりかと思います。","id":"exchange-009"},{"speaker":"南委員","kind":"質問","question":"４０番の「大会経費の効率化に向けた検討を行われたい」という、ここのところを、この扱い方について委員長のお考えを伺いたいと思っています。それから、１番の一番トップのところに括弧書きでブラインドサッカーと書いてあるので、この辺についてはどうなのかと思ったりしています。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-010"},{"speaker":"松永委員","kind":"質問","question":"区内競技場周辺整備の中に、３番の「会場周辺整備」というのは、２、４、５、６、７のことではないかと思うのですけれども、ほかにアバウトというか、ふわっという感じでよく内容がわからないのですが、３番についてどうなのかというので、お聞きしたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-011"},{"speaker":"南委員","kind":"意見","question":"１番のところの関係で、４１番が障害者スポーツの振興ということで、障害者スポーツとしての位置づけで理解することになるということですよねとの意見を述べました。","respondent":"渡辺委員長","answer":"これは私ども自民党会派で出したものなので、説明を私のほうから。区内開催予定でもあったし、まず１つ軸をつくったほうが、１つの競技に特化しているものではないです。","id":"exchange-012"},{"speaker":"南委員","kind":"質問","question":"きちんと取り上げることで関心が広がるし、私たちも含めた自覚、そういうのが広がるという点では大事だと思います。ここについてはちょっとあれかなと思って、ですから、そこのところは削除するなりしなくてはいけないかなと思っています。","respondent":"渡辺委員長、小川オリンピック・パラリンピック準備課長","answer":"変更点と、今日報告を受けて、次回、資料からは訂正いたしたいと思います。以上で特定事件調査を終了いたします。 ８月６日、視察第１日目からご説明をいたしますが、獲得することができたと考えています。世界の誰もが納得する高いレベルの対応、ハードとソフトの連携を実施することが重要なポイントであるということを感じました。","id":"exchange-013"}]},{"id":"topic-02","title":"リオデジャネイロオリンピック視察報告","agenda":"リオデジャネイロオリンピック視察報告","exchanges":[{"speaker":"いながわ委員","kind":"提案","question":"これは提案も含めてなのですが、外国人ゲストへの対応策としてフリーWi-Fiを整備している個店、事業主も多くあります。先ほど行政からも提案がありましたが、品川区の伝統や文化、工芸品を世界に発信することも必要であると考えておりますとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-014"},{"speaker":"南委員","kind":"質問・要望","question":"項目が立ててあるので、あったのかもしれないと思っているので、あえてそのことを伺いたいと思います。もうちょっと早く提出していただきたかったと思ったのですが、その点について、前日になった事情、それを教えていただきたい。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"目次のところで、１番から５番までということでしていますけれども、構成は少しこれから最終に向けては調整したいというふうに考えてあります。今回の９月３０日の特別委員会を逃すと、できたてのものですので、ご理解をお願いしたいと考えています。","id":"exchange-015"},{"speaker":"南委員","kind":"質問","question":"あまり時間がない中で、私ばかり言ってしまうのは申しわけない。先ほど課長が口頭で説明してくださった部分と、後半のこちらがどういう関係で見たらいいのかというのがちょっとわからないので、説明を求めました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-016"},{"speaker":"南委員","kind":"質問","question":"では、７０ページの議員の視点からということで、お二人の委員が視察に行かれた、そこの２人の委員の報告部分ということなのか尋ねました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-017"},{"speaker":"あくつ委員","kind":"質問・要望","question":"残念ながら、区においてはやっているのはＴｗｉｔｔｅｒですかね。これが非常に感触がよかったのかなというのもあるのですが、この点について、いながわ委員のご意見をもう一回伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"組織委員会はほぼ実施されていなかったというのは事実です。住民の主体性を重視ということで、プロジェクト自体が、リオ市が主催というプロジェクトは実施していなかったという意味です。","id":"exchange-018"},{"speaker":"いながわ委員","kind":"質問・要望","question":"今、やはりそういう部分はしっかりと作製しておくべきなのかなというのもありますので、今後の課題としてしっかりとやっていただきたいと。とにかく英語表記がないと全然意味がわからないと思いますので、そこはしっかりやっていただきたいという思いがします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-019"},{"speaker":"吉田委員","kind":"質問・要望","question":"ボランティアによる２回のセキュリティチェックを受けました」ということで、この辺が、していただきたいというふうに思いました。これを区民の皆さんに示したときに質問も出てくるかと思うのですけれども、報告会のようなものは検討されているのかどうか伺いたいと思います。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-020"},{"speaker":"伊藤委員","kind":"意見","question":"２０２０年、あれだけの費用をかけてうんぬんかんぬんより、あるいは数十倍の価値が出てきたということを具体化していかないといけないと思うのです。こういうことを踏まえた上で品川区はどういう計画をして、具体的にあの批判にどう応えていくかということをお答えほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"例えば、ホスピタリティハウスなどは、現地に行かなければ絶対にわからないような情報でございました。来年度だけでなく、こういった予算につながったということが目に見える形でわかるように、区としてはそういった方向で考えているところです。","id":"exchange-021"},{"speaker":"伊藤委員","kind":"質問・要望","question":"出ないものもありますし、それから物によっては大会組織委員会に提言することもあるでしょうし、それから東京都に対する対応もあるでしょう。具体的な責任を求めていく、やはり部長から一言いただきたいのですが、いかがか尋ねました。","respondent":"安藤文化スポーツ振興部長","answer":"すぐ区民サービスに直結できるものは来年度の政策として提案して、そして、４年後までにそれを実現化していきたい。議会の方々も一緒になって、さまざまな関係機関に物を申して、品川区民に利益のあるような施策を打っていきたいというふうに感じております。","id":"exchange-022"},{"speaker":"つる委員","kind":"確認","question":"議員としては決意をしたところでありますが、まず、本当に感謝したいと考えています。いろいろざっと確認したい点があるのですが、まず１点、印象だけ教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"海岸自体はきれいな海岸通りではあったのですけれども、一歩海に近づくようなところには行くなとガイドには厳しく言われておりました。観光地という印象ではありますが、表裏一体で、危険な部分もあわせ持った地帯であるというような印象です。","id":"exchange-023"},{"speaker":"いながわ委員","kind":"意見","question":"非常に朝からにぎわい、それがずっと遅くまで続くというのが現状であって、非常ににぎわいの創出はされていた。もともと観光地なので、さらにオリンピック・パラリンピックを機にそのにぎわいが過熱していたというイメージを受けましたとの意見を述べました。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-024"},{"speaker":"つる委員","kind":"質問・要望","question":"この場で答弁は特段求めませんが、今後の構成、てにをはのチェックの中で確認いただければと。これは要望でとどめておきますので、以上です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-025"},{"speaker":"石田（ち）委員","kind":"提案","question":"提案というふうに、この提案を品川区の施策に活かしていくということで、提案もされているということですので。具体的にどんなバリアフリーのことなのか、イメージを教えてほしいと求めました。","respondent":"稲田都市開発課長","answer":"まちづくりは私のほうが書きましたのでお答えしますが、そういうのがあって初めてバリアフリーのレベルが高いというのではないかということで、私はこういうふうに記入しました。","id":"exchange-026"},{"speaker":"石田（ち）委員","kind":"質問","question":"ですので、やはり今まで不十分だったところを充実させていくということなのだろうというふうに私は理解しています。会場周辺も見ていただいて、どんなバリアフリーが必要なのかということを進めていくことが必要だと思うのですけれども、いかがか尋ねました。","respondent":"稲田都市開発課長","answer":"大井町のバリアフリー、まちづくりの計画におきましても、障害者の方々とまち歩きをしながら計画を立ててきたところです。今後もそういうところをしっかりやっていくです。","id":"exchange-027"},{"speaker":"石田（ち）委員","kind":"質問・要望","question":"ぜひ充実させるためにも、しっかり、そして、早急に進めてほしいと求めました。改めて確認できたというような内容だったのですけれども、これがよかったというのがあれば改めて伺いたいのですけれども、お願いします。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-028"},{"speaker":"石田（ち）委員","kind":"確認","question":"改めて確認できた、リオの状況がわかった、それはそうだと思うのです。約１,５００万円かけて行っただけのものが、これが行けてよかったと思っていることがあれば、伺いたいのです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-029"},{"speaker":"藤原委員","kind":"質問・要望","question":"これでこの資料を出したから終わりではなくして、この資料をこれから活用して、活かしていただきたい。ですから、要望なので、委員長からお答えしていただけますか。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-030"},{"speaker":"藤原委員","kind":"質問・要望","question":"ですから、要望といいますか、活かしてもらいたい。どうしても要望として言わざるを得なかったもので、要望としてお話しさせていただきましたけれども、一言でも何かいただければ幸いです。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-031"}]},{"id":"topic-03","title":"ブラインドサッカーの競技会場正式決定","agenda":"ブラインドサッカーの競技会場正式決定","exchanges":[{"speaker":"南委員","kind":"質問・要望","question":"今、報告を聞いたのですが、その前にいろいろ東京都のほうから、青海に変更した等々のそういう話は聞いておりました。改めてですけれども、変更した理由というのはどういうことだというふうに、発表があるのかないのかも含めて、まず教えてほしいと求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"変更した理由につきましては、組織委員会のホームページにも何ら記載がございません。私どもも、東京都に確認しているのですけれども、把握できておりません。","id":"exchange-032"},{"speaker":"南委員","kind":"質問","question":"担当のところでは当然そういうことだと思うのですけれども、その辺についてはどういうふうに認識しておられるかと。そういう点について、どういうふうに区として認識しておられるかを伺いたいと思います。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"平成２６年からブラインドサッカーフェスタを皮切りにさまざまな事業を展開してきたところですし、本当に残念な気持ちでいっぱいです。それは東京都に引き続ききちんとした回答を求めてまいりたいとは思いますが、憶測で物を言うことは控えたいと考えているところです。","id":"exchange-033"},{"speaker":"吉田委員","kind":"質問","question":"でも、一方で応募してくださっている方もあるという中で、今後の扱いをどうするのか説明を求めました。","respondent":"小川オリンピック・パラリンピック準備課長","answer":"もともとは大会組織委員会のほうから、大会組織委員会が募集しているものと混在されないように、区が応援する３競技という形で求めてまいりました。特にゆかりのあるという面で、３競技について応援しましょうということで、区民の方に盛り上げていただきたいという思いです。","id":"exchange-034"},{"speaker":"吉田委員","kind":"質問・要望","question":"ブラインドサッカーの連盟とか、そういう方たちにも理解していただいて、扱いには十分気をつけてほしいと求めました。それは要望です。","respondent":"","answer":"この発言に対する個別の答弁・回答は、会議録に記録されていません。","id":"exchange-035"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/158474?Template=document&Id=6502#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=18&TermStart=2016-01-01&TermEnd=2016-12-31"}],"sourceMeta":{"pages":0,"characters":49614,"voices":101}}]);
